@app.on_event("startup")
async def startup_event():
    global GLOBAL_LOOP
    GLOBAL_LOOP = asyncio.get_running_loop()
    sync_static_html_versions()
    # 启动时整理资产库：给所有图片分组（含默认角色/场景）建好文件夹，并把根目录里的旧素材归整进去。
    try:
        await asyncio.to_thread(migrate_asset_library_into_dirs)
    except Exception as exc:
        print(f"资产库分组整理失败: {exc}")
    # 修复历史遗留的双重扩展名素材（foo.png.png → foo.png），否则这些卡片无法显示
    try:
        await asyncio.to_thread(migrate_double_extension_uploads)
    except Exception as exc:
        print(f"修复双重扩展名素材失败: {exc}")
    # 纠正内容与扩展名不符的图片（如 WebP 内容却叫 .png），否则严格客户端解不出来
    try:
        await asyncio.to_thread(migrate_mislabeled_image_extensions)
    except Exception as exc:
        print(f"纠正图片扩展名失败: {exc}")
    try:
        load_canvas_task_store()
    except Exception as exc:
        print(f"恢复画布任务记录失败: {exc}")
    try:
        load_canvas_agent_run_store()
    except Exception as exc:
        print(f"恢复画布 Agent Harness 记录失败: {exc}")
    try:
        await asyncio.to_thread(_commerce_analysis_init_store)
    except Exception as exc:
        print(f"初始化商品分析任务库失败: {exc}")
    try:
        load_scheduled_task_store()
        start_scheduled_task_scheduler()
    except Exception as exc:
        print(f"初始化定时任务失败: {exc}")


@app.on_event("shutdown")
async def shutdown_event():
    # The browser Skill is lazy, but if it was used during this process it
    # must not leave the loopback helper orphaned after the FastAPI server exits.
    await stop_canvas_agent_harness()
    await stop_scheduled_task_scheduler()
    await asyncio.to_thread(_browser_agent_stop)
    await asyncio.to_thread(stop_canvas_share_services)

@app.websocket("/ws/stats")
async def websocket_endpoint(websocket: WebSocket, client_id: str = None, canvas_id: str = ""):
    share = _canvas_share_from_websocket(websocket)
    client_host = getattr(getattr(websocket, "client", None), "host", "")
    gateway_request = False
    try:
        gateway_request = str(websocket.headers.get("x-xiaomei-share-gateway") or "").strip() == "1"
    except Exception:
        pass
    if _request_host_is_loopback(client_host) and not gateway_request:
        share = None
    elif share is False and _request_host_is_loopback(client_host):
        share = None
    if share is False or (not share and not _request_host_is_loopback(client_host)):
        await websocket.close(code=1008)
        return
    canvas_scope = ""
    if share:
        canvas_scope = str(share.get("canvas_id") or "")
        if canvas_id and re.sub(r"[^a-zA-Z0-9_-]", "", canvas_id) != canvas_scope:
            await websocket.close(code=1008)
            return
    await manager.connect(websocket, client_id, canvas_scope)
    try:
        while True:
            data = await websocket.receive_text()
            if data == "ping":
                await websocket.send_text(json.dumps({"type": "pong"}))
    except WebSocketDisconnect:
        await manager.disconnect(websocket, client_id)
    except Exception as e:
        print(f"WS Error: {e}")
        await manager.disconnect(websocket, client_id)


@app.websocket("/ws/canvas-collab/{canvas_id}")
async def canvas_collaboration_endpoint(
    websocket: WebSocket,
    canvas_id: str,
    client_id: str = "",
    name: str = "",
    color: str = "",
):
    """Presence and lightweight edit-lock channel for one canvas."""
    clean_canvas_id = _share_clean_canvas_id(canvas_id)
    if not clean_canvas_id:
        await websocket.close(code=1008)
        return
    share = _canvas_share_from_websocket(websocket)
    client_host = getattr(getattr(websocket, "client", None), "host", "")
    gateway_request = False
    try:
        gateway_request = str(websocket.headers.get("x-xiaomei-share-gateway") or "").strip() == "1"
    except Exception:
        pass
    is_local_host = _request_host_is_loopback(client_host) and not gateway_request
    if is_local_host:
        share = None
    if share is False or (not share and not is_local_host):
        await websocket.close(code=1008)
        return
    if share and not _canvas_share_canvas_allowed(share, clean_canvas_id):
        await websocket.close(code=1008)
        return
    try:
        load_canvas(clean_canvas_id)
    except Exception:
        await websocket.close(code=1008)
        return
    member = {
        "id": client_id,
        "name": name,
        "color": color,
        "role": (share or {}).get("role") or "editor",
        "host": is_local_host,
    }
    await manager.connect_collab(websocket, clean_canvas_id, member)
    try:
        while True:
            raw = await websocket.receive_text()
            try:
                payload = json.loads(raw)
            except Exception:
                continue
            await manager.handle_collab_message(websocket, payload)
    except WebSocketDisconnect:
        await manager.disconnect_collab(websocket)
    except Exception as exc:
        print(f"Collaboration WS error: {exc}")
        await manager.disconnect_collab(websocket)

