def _browser_agent_node_executable():
    """Find the existing Node runtime used by the commerce analysis tools."""
    configured = str(os.getenv("XIAOMEI_NODE", "")).strip()
    candidates = [configured, shutil.which("node"), shutil.which("node.exe")]
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return os.path.abspath(candidate)
    return ""


def _browser_agent_process_alive():
    process = BROWSER_AGENT_PROCESS
    return bool(process is not None and process.poll() is None)


def _browser_agent_free_port():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind(("127.0.0.1", 0))
        return int(sock.getsockname()[1])


def _browser_agent_start():
    """Start the local browser bridge lazily, without opening a browser on app startup."""
    global BROWSER_AGENT_PROCESS, BROWSER_AGENT_PORT, BROWSER_AGENT_TOKEN
    with BROWSER_AGENT_LOCK:
        if _browser_agent_process_alive():
            return
        node = _browser_agent_node_executable()
        if not node:
            raise RuntimeError("未找到 Node.js，无法启动浏览器技能。请先安装 Node.js。")
        if not os.path.isfile(BROWSER_AGENT_SCRIPT):
            raise RuntimeError("小美画布浏览器桥接文件不存在，请检查 tools/commerce-analysis/browser-session.mjs")
        os.makedirs(BROWSER_AGENT_PROFILE_DIR, exist_ok=True)
        os.makedirs(BROWSER_AGENT_OUTPUT_DIR, exist_ok=True)
        BROWSER_AGENT_PORT = _browser_agent_free_port()
        BROWSER_AGENT_TOKEN = uuid.uuid4().hex
        command = [
            node,
            BROWSER_AGENT_SCRIPT,
            "--port", str(BROWSER_AGENT_PORT),
            "--token", BROWSER_AGENT_TOKEN,
            "--profile-dir", BROWSER_AGENT_PROFILE_DIR,
            "--output-dir", BROWSER_AGENT_OUTPUT_DIR,
        ]
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
        try:
            BROWSER_AGENT_PROCESS = subprocess.Popen(
                command,
                cwd=os.path.dirname(BROWSER_AGENT_SCRIPT),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creationflags,
            )
        except Exception:
            BROWSER_AGENT_PROCESS = None
            BROWSER_AGENT_PORT = 0
            BROWSER_AGENT_TOKEN = ""
            raise


def _browser_agent_stop():
    global BROWSER_AGENT_PROCESS, BROWSER_AGENT_PORT, BROWSER_AGENT_TOKEN
    with BROWSER_AGENT_LOCK:
        process = BROWSER_AGENT_PROCESS
        BROWSER_AGENT_PROCESS = None
        BROWSER_AGENT_PORT = 0
        BROWSER_AGENT_TOKEN = ""
        if process is None:
            return
        try:
            process.terminate()
            process.wait(timeout=4)
        except Exception:
            try:
                process.kill()
                process.wait(timeout=2)
            except Exception:
                pass


def _browser_agent_public_url(file_path):
    """Expose only files created below /output, never an absolute local path."""
    if not file_path:
        return ""
    try:
        output_root = os.path.realpath(OUTPUT_DIR)
        target = os.path.realpath(str(file_path))
        if os.path.commonpath([output_root, target]) != output_root:
            return ""
        relative = os.path.relpath(target, output_root).replace(os.sep, "/")
        if relative in ("", ".") or relative.startswith("../"):
            return ""
        return "/output/" + urllib.parse.quote(relative, safe="/")
    except (OSError, ValueError):
        return ""


def _browser_agent_public_result(value):
    result = dict(value or {}) if isinstance(value, dict) else {"ok": False, "error": str(value)}
    local_path = result.pop("path", "")
    public_url = _browser_agent_public_url(local_path)
    if public_url:
        result["file_url"] = public_url
        if result.get("status") == "screenshot":
            result["screenshot_url"] = public_url
    return result


async def _browser_agent_call(payload, start=True):
    """Proxy one browser action through the authenticated loopback bridge."""
    if start:
        await asyncio.to_thread(_browser_agent_start)
    if not _browser_agent_process_alive() or not BROWSER_AGENT_PORT:
        raise RuntimeError("浏览器技能服务没有运行")
    endpoint = f"http://127.0.0.1:{BROWSER_AGENT_PORT}/action"
    headers = {"X-Xiaomei-Browser-Token": BROWSER_AGENT_TOKEN}
    timeout = httpx.Timeout(65.0, connect=2.0)
    last_error = None
    async with httpx.AsyncClient(timeout=timeout) as client:
        for attempt in range(40):
            try:
                response = await client.post(endpoint, headers=headers, json=payload or {})
                data = response.json()
                if response.status_code >= 400:
                    detail = data.get("error") or data.get("message") or f"浏览器服务 HTTP {response.status_code}"
                    error = RuntimeError(str(detail))
                    setattr(error, "browser_result", _browser_agent_public_result(data))
                    raise error
                result = _browser_agent_public_result(data)
                if str(payload.get("action") or "").lower() == "close":
                    await asyncio.to_thread(_browser_agent_stop)
                return result
            except RuntimeError:
                raise
            except (httpx.ConnectError, httpx.ConnectTimeout, httpx.ReadError, httpx.RemoteProtocolError) as exc:
                last_error = exc
                if attempt >= 39 or not _browser_agent_process_alive():
                    break
                await asyncio.sleep(0.15)
    raise RuntimeError(f"浏览器技能服务未能响应：{last_error or '未知错误'}")

def _storage_abs_path(value, fallback):
    text = str(value or "").strip()
    if not text:
        return os.path.abspath(fallback)
    text = os.path.expanduser(os.path.expandvars(text))
    if not os.path.isabs(text):
        text = os.path.join(BASE_DIR, text)
    return os.path.abspath(text)

def _read_storage_settings_raw():
    raw = {}
    try:
        if os.path.exists(STORAGE_SETTINGS_FILE):
            with open(STORAGE_SETTINGS_FILE, "r", encoding="utf-8-sig") as f:
                raw = json.load(f) if f else {}
    except Exception as exc:
        print(f"加载存储目录设置失败: {exc}")
        raw = {}
    return raw if isinstance(raw, dict) else {}


def _storage_dirs_from_raw(raw):
    dirs = {}
    for key, fallback in DEFAULT_STORAGE_DIRS.items():
        dirs[key] = _storage_abs_path((raw or {}).get(key), fallback)
    return dirs


def _storage_image_space_from_raw(raw, dirs):
    explicit = str((raw or {}).get("image_space") or (raw or {}).get("root") or "").strip()
    if explicit:
        return _storage_abs_path(explicit, DEFAULT_IMAGE_SPACE_DIR)
    # 兼容旧版三个独立目录：先给用户推导一个不改变旧目录的目标根目录。
    # 例如 F:\上传素材、F:\images、F:\本地素材 会得到 F:\图片空间。
    try:
        common = os.path.commonpath(list(dirs.values()))
    except (TypeError, ValueError):
        common = ""
    common = os.path.abspath(common) if common else ""
    if common:
        # 已经是“图片空间/三个子文件夹”的目录集合时，common 本身就是根目录。
        if all(os.path.basename(os.path.normpath(dirs.get(key, ""))) == folder_name for key, folder_name in IMAGE_SPACE_FOLDER_NAMES.items()):
            return common
        return os.path.join(common, "图片空间")
    return os.path.abspath(DEFAULT_IMAGE_SPACE_DIR)


def _storage_paths_equal(left, right):
    try:
        return os.path.normcase(os.path.abspath(str(left or ""))) == os.path.normcase(os.path.abspath(str(right or "")))
    except (TypeError, ValueError):
        return False


def _storage_settings_result(dirs, image_space, legacy_dirs=None, unified=None, migration=None):
    result = {
        "dirs": {key: os.path.abspath(value) for key, value in (dirs or {}).items()},
        "image_space": os.path.abspath(image_space),
        "root": os.path.abspath(image_space),
        "folder_names": dict(IMAGE_SPACE_FOLDER_NAMES),
        "legacy_dirs": {key: os.path.abspath(value) for key, value in (legacy_dirs or {}).items() if value},
        "unified": bool(unified),
    }
    if migration is not None:
        result["migration"] = migration
    return result


def load_storage_settings():
    raw = _read_storage_settings_raw()
    dirs = _storage_dirs_from_raw(raw)
    image_space = _storage_image_space_from_raw(raw, dirs)
    legacy_raw = raw.get("legacy_dirs") if isinstance(raw.get("legacy_dirs"), dict) else {}
    legacy_dirs = {}
    for key in IMAGE_SPACE_FOLDER_NAMES:
        value = str(legacy_raw.get(key) or "").strip()
        if value:
            legacy_dirs[key] = _storage_abs_path(value, dirs[key])
    target_dirs = {
        key: os.path.join(image_space, folder_name)
        for key, folder_name in IMAGE_SPACE_FOLDER_NAMES.items()
    }
    unified = bool(str(raw.get("image_space") or raw.get("root") or "").strip()) and all(
        _storage_paths_equal(dirs.get(key), target_dirs[key]) for key in IMAGE_SPACE_FOLDER_NAMES
    )
    if not unified:
        for key in IMAGE_SPACE_FOLDER_NAMES:
            current = dirs.get(key)
            target = target_dirs.get(key)
            if current and target and not _storage_paths_equal(current, target):
                legacy_dirs.setdefault(key, current)
    return _storage_settings_result(dirs, image_space, legacy_dirs, unified)


def _storage_collision_path(path):
    if not os.path.exists(path):
        return path
    folder, filename = os.path.split(path)
    stem, ext = os.path.splitext(filename)
    for index in range(2, 10000):
        candidate = os.path.join(folder, f"{stem}_旧目录{index}{ext}")
        if not os.path.exists(candidate):
            return candidate
    return os.path.join(folder, f"{stem}_旧目录_{uuid.uuid4().hex[:8]}{ext}")


def _merge_move_storage_tree(source, target):
    """将旧目录内容合并到图片空间，不覆盖目标文件，返回移动数量。"""
    source = os.path.abspath(source)
    target = os.path.abspath(target)
    if _storage_paths_equal(source, target) or not os.path.isdir(source):
        return 0
    os.makedirs(target, exist_ok=True)
    moved = 0
    for entry in list(os.scandir(source)):
        destination = os.path.join(target, entry.name)
        if entry.is_dir(follow_symlinks=False):
            moved += _merge_move_storage_tree(entry.path, destination)
            try:
                os.rmdir(entry.path)
            except OSError:
                pass
            continue
        if not entry.is_file(follow_symlinks=False):
            continue
        destination = _storage_collision_path(destination)
        try:
            shutil.move(entry.path, destination)
            moved += 1
        except OSError as exc:
            print(f"整理图片空间文件失败: {entry.path} -> {destination} ({exc})")
    try:
        os.rmdir(source)
    except OSError:
        pass
    return moved

def save_storage_settings(payload):
    payload = payload if isinstance(payload, dict) else {}
    previous = load_storage_settings()
    requested_space = str(payload.get("image_space") or payload.get("root") or "").strip()
    if requested_space:
        image_space = _storage_abs_path(requested_space, previous.get("image_space") or DEFAULT_IMAGE_SPACE_DIR)
        dirs = {
            key: os.path.join(image_space, folder_name)
            for key, folder_name in IMAGE_SPACE_FOLDER_NAMES.items()
        }
        legacy_dirs = dict(previous.get("legacy_dirs") or {})
        # 第一次切换到图片空间时保留旧目录映射，历史记录和旧素材仍可访问。
        for key in IMAGE_SPACE_FOLDER_NAMES:
            old_path = previous.get("dirs", {}).get(key)
            if old_path and not _storage_paths_equal(old_path, dirs[key]):
                legacy_dirs.setdefault(key, old_path)
        migrate_legacy = bool(payload.get("migrate_legacy"))
    else:
        # 兼容旧客户端继续提交三个绝对路径的请求；如果没有提交任何目录，
        # 直接保留当前图片空间配置，避免旧前端把目录重置回默认值。
        if not any(str(payload.get(key) or "").strip() for key in IMAGE_SPACE_FOLDER_NAMES):
            current_dirs = previous.get("dirs") or {
                key: os.path.join(previous.get("image_space") or DEFAULT_IMAGE_SPACE_DIR, folder_name)
                for key, folder_name in IMAGE_SPACE_FOLDER_NAMES.items()
            }
            return _storage_settings_result(
                current_dirs,
                previous.get("image_space") or DEFAULT_IMAGE_SPACE_DIR,
                previous.get("legacy_dirs") or {},
                unified=bool(previous.get("unified")),
                migration={"moved": 0, "failed": 0, "performed": False},
            )
        # 旧版三个独立目录配置。
        dirs = {}
        for key, fallback in DEFAULT_STORAGE_DIRS.items():
            dirs[key] = _storage_abs_path(payload.get(key), previous.get("dirs", {}).get(key) or fallback)
        image_space = _storage_image_space_from_raw({}, dirs)
        legacy_dirs = dict(previous.get("legacy_dirs") or {})
        migrate_legacy = False
    for path in dirs.values():
        os.makedirs(path, exist_ok=True)
    os.makedirs(DATA_DIR, exist_ok=True)

    migration = {"moved": 0, "failed": 0, "performed": False}
    if requested_space and migrate_legacy:
        migration["performed"] = True
        for key, source in list(legacy_dirs.items()):
            destination = dirs.get(key)
            if not source or not destination or _storage_paths_equal(source, destination):
                continue
            try:
                migration["moved"] += _merge_move_storage_tree(source, destination)
            except Exception as exc:
                migration["failed"] += 1
                print(f"整理图片空间目录失败: {source} -> {destination} ({exc})")
            if not os.path.exists(source):
                legacy_dirs.pop(key, None)

    persisted = dict(dirs)
    persisted.update({
        "version": 2,
        "image_space": image_space,
        "legacy_dirs": legacy_dirs,
    })
    with open(STORAGE_SETTINGS_FILE, "w", encoding="utf-8") as f:
        json.dump(persisted, f, ensure_ascii=False, indent=2)
    apply_storage_settings(dirs)
    return _storage_settings_result(
        dirs,
        image_space,
        legacy_dirs,
        unified=bool(requested_space),
        migration=migration,
    )

def apply_storage_settings(dirs=None):
    global OUTPUT_INPUT_DIR, OUTPUT_OUTPUT_DIR, LOCAL_UPLOAD_DIR
    dirs = dirs or load_storage_settings().get("dirs") or {}
    OUTPUT_INPUT_DIR = dirs.get("upload") or OUTPUT_INPUT_DIR
    OUTPUT_OUTPUT_DIR = dirs.get("generated") or OUTPUT_OUTPUT_DIR
    LOCAL_UPLOAD_DIR = dirs.get("local") or LOCAL_UPLOAD_DIR

apply_storage_settings()

