def provider_key_env(provider_id):
    if provider_id == "comfly":
        return "COMFLY_API_KEY"
    if provider_id == "modelscope":
        return "MODELSCOPE_API_KEY"
    if provider_id == "runninghub":
        return "RUNNINGHUB_API_KEY"
    if provider_id == "volcengine":
        return "ARK_API_KEY"
    return f"API_PROVIDER_{re.sub(r'[^A-Za-z0-9]', '_', provider_id).upper()}_KEY"

def runninghub_wallet_key_env():
    return "RUNNINGHUB_WALLET_API_KEY"

def volcengine_access_key_env():
    return "VOLCENGINE_ACCESS_KEY_ID"

def volcengine_secret_key_env():
    return "VOLCENGINE_SECRET_ACCESS_KEY"

def read_api_env_value(key: str) -> str:
    key = str(key or "").strip()
    if not key or not os.path.exists(API_ENV_FILE):
        return ""
    try:
        with open(API_ENV_FILE, "r", encoding="utf-8-sig") as f:
            for raw_line in f.read().splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                env_key, value = line.split("=", 1)
                if env_key.strip() == key:
                    return value.strip().strip('"').strip("'")
    except Exception:
        return ""
    return ""

def provider_env_key_value(provider_id: str) -> str:
    provider_id = str(provider_id or "").strip().lower()
    env_key = provider_key_env(provider_id)
    key = os.getenv(env_key, "") or read_api_env_value(env_key)
    if key:
        return key
    if provider_id == "modelscope":
        return MODELSCOPE_API_KEY or ""
    return ""

def runninghub_wallet_key_value() -> str:
    env_key = runninghub_wallet_key_env()
    return os.getenv(env_key, "") or read_api_env_value(env_key)

def volcengine_access_key_value() -> str:
    env_key = volcengine_access_key_env()
    return os.getenv(env_key, "") or read_api_env_value(env_key)

def volcengine_secret_key_value() -> str:
    env_key = volcengine_secret_key_env()
    return os.getenv(env_key, "") or read_api_env_value(env_key)

def volcengine_provider_api_key(explicit_key: str = "") -> str:
    explicit_key = str(explicit_key or "").strip()
    if explicit_key:
        return explicit_key
    return provider_env_key_value("volcengine")

def mask_secret(value):
    if not value:
        return ""
    tail = value[-4:] if len(value) > 4 else value
    return f"••••••••{tail}"


KEY_PROFILE_ID_RE = re.compile(r"^[a-zA-Z0-9_-]{2,80}$")
KEY_PROFILE_ENV_RE = re.compile(r"^[A-Z][A-Z0-9_]{1,160}$")


def key_profiles_supported(provider_or_id) -> bool:
    """Return whether the provider's primary API key can have saved records.

    RunningHub has two different key types, while the CLI providers use local
    login state.  Their existing dedicated UI remains the source of truth.
    """
    if isinstance(provider_or_id, dict):
        provider_id = str(provider_or_id.get("id") or "").strip().lower()
        protocol = str(provider_or_id.get("protocol") or "").strip().lower()
    else:
        provider_id = str(provider_or_id or "").strip().lower()
        protocol = ""
    if provider_id in {"runninghub", "jimeng", "codex", "gemini-cli"}:
        return False
    return protocol not in {"runninghub", "jimeng", "codex", "gemini-cli"}


def _key_profile_store_default():
    return {"version": 1, "providers": {}}


def _load_key_profile_store():
    if not os.path.exists(API_KEY_PROFILES_FILE):
        return _key_profile_store_default()
    try:
        with open(API_KEY_PROFILES_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, dict) or not isinstance(raw.get("providers"), dict):
            raise ValueError("记录文件结构无效")
        return {
            "version": 1,
            "providers": raw.get("providers") or {},
        }
    except Exception as exc:
        # 不把记录文件中的任何内容（尤其是未来可能出现的密钥别名）写入日志。
        print(f"加载 API Key 记录失败：{exc}")
        return _key_profile_store_default()


def _key_profile_env_key(provider_id: str, profile_id: str) -> str:
    base = provider_key_env(provider_id)
    safe_id = re.sub(r"[^A-Za-z0-9_]", "_", str(profile_id or "").strip()).upper()
    safe_id = safe_id[:48] or "KEY"
    return f"{base}_PROFILE_{safe_id}"


def _new_key_profile_id() -> str:
    return f"key_{secrets.token_hex(8)}"


def _clean_key_profile_name(value, fallback: str) -> str:
    text = re.sub(r"[\x00-\x1f\x7f]", "", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip()[:40]
    return text or fallback


def _read_key_profile_value(env_key: str) -> str:
    env_key = str(env_key or "").strip()
    if not env_key:
        return ""
    return os.getenv(env_key, "") or read_api_env_value(env_key)


def _key_profile_timestamp() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def _normalize_key_profile_entry(raw, provider_id: str, index: int):
    if not isinstance(raw, dict):
        return None
    profile_id = str(raw.get("id") or "").strip()
    if not KEY_PROFILE_ID_RE.fullmatch(profile_id):
        return None
    env_key = str(raw.get("env_key") or "").strip().upper()
    expected_prefix = f"{provider_key_env(provider_id)}_PROFILE_"
    if not KEY_PROFILE_ENV_RE.fullmatch(env_key) or not env_key.startswith(expected_prefix):
        env_key = _key_profile_env_key(provider_id, profile_id)
    now = _key_profile_timestamp()
    return {
        "id": profile_id,
        "name": _clean_key_profile_name(raw.get("name"), f"账号 {index + 1}"),
        "env_key": env_key,
        "created_at": str(raw.get("created_at") or raw.get("createdAt") or now).strip(),
        "updated_at": str(raw.get("updated_at") or raw.get("updatedAt") or now).strip(),
    }


def _key_profile_state(store, provider_id: str, migrate=True, env_updates=None):
    """Normalize one provider's metadata and lazily migrate its old active key.

    The returned metadata contains only env variable names.  The secret values
    are read from API/.env and are never placed in the JSON record file.
    """
    provider_id = str(provider_id or "").strip().lower()
    providers = store.setdefault("providers", {})
    raw_record = providers.get(provider_id)
    raw_profiles = raw_record.get("profiles") if isinstance(raw_record, dict) else []
    raw_profiles = raw_profiles if isinstance(raw_profiles, list) else []
    profiles = []
    seen = set()
    for index, raw_profile in enumerate(raw_profiles):
        profile = _normalize_key_profile_entry(raw_profile, provider_id, index)
        if not profile or profile["id"] in seen:
            continue
        seen.add(profile["id"])
        profiles.append(profile)

    active_id = str(raw_record.get("active_id") or raw_record.get("activeId") or "").strip() if isinstance(raw_record, dict) else ""
    base_env_key = provider_key_env(provider_id)
    base_value = provider_env_key_value(provider_id)
    changed = profiles != raw_profiles

    # Existing installations only have the single provider env key.  Turn it
    # into the first record once, keeping the old env key as the live value for
    # compatibility and copying it to a private profile env entry.
    if not profiles and migrate and base_value:
        legacy_id = "key_legacy"
        legacy = {
            "id": legacy_id,
            "name": "账号 1",
            "env_key": _key_profile_env_key(provider_id, legacy_id),
            "created_at": _key_profile_timestamp(),
            "updated_at": _key_profile_timestamp(),
        }
        profiles = [legacy]
        active_id = legacy_id
        changed = True
        if env_updates is not None:
            env_updates[legacy["env_key"]] = base_value

    if profiles:
        if active_id not in {profile["id"] for profile in profiles}:
            active_id = profiles[0]["id"]
            changed = True
        active_profile = next((profile for profile in profiles if profile["id"] == active_id), profiles[0])
        active_value = _read_key_profile_value(active_profile["env_key"])
        if base_value and not active_value and env_updates is not None:
            env_updates[active_profile["env_key"]] = base_value
        elif active_value and not base_value and env_updates is not None:
            env_updates[base_env_key] = active_value
        normalized_record = {"active_id": active_id, "profiles": profiles}
        if not isinstance(raw_record, dict) or raw_record != normalized_record:
            changed = True
        providers[provider_id] = normalized_record
    elif isinstance(raw_record, dict):
        normalized_record = {"active_id": "", "profiles": []}
        if raw_record != normalized_record:
            changed = True
        providers[provider_id] = normalized_record

    return {
        "active_id": active_id if profiles else "",
        "profiles": profiles,
        "changed": changed,
    }


def _save_key_profile_store_locked(store):
    os.makedirs(DATA_DIR, exist_ok=True)
    _atomic_write_json_locked(API_KEY_PROFILES_FILE, store)


def ensure_key_profile_store_for_providers(providers):
    """Ensure old single-key values are visible as records in the settings UI."""
    provider_items = [item for item in (providers or []) if isinstance(item, dict)]
    with GLOBAL_CONFIG_LOCK:
        store = _load_key_profile_store()
        env_updates = {}
        changed = False
        for provider in provider_items:
            if not key_profiles_supported(provider):
                continue
            state = _key_profile_state(store, provider.get("id"), migrate=True, env_updates=env_updates)
            changed = changed or bool(state.get("changed"))
        if env_updates:
            update_env_values(env_updates)
            reload_env_globals()
        if changed or env_updates:
            _save_key_profile_store_locked(store)
        return store


def _public_key_profile_bundle(provider_id: str, store=None):
    provider_id = str(provider_id or "").strip().lower()
    if not key_profiles_supported(provider_id):
        return {"active_id": "", "profiles": []}
    if store is None:
        store = ensure_key_profile_store_for_providers([{"id": provider_id}])
    state = _key_profile_state(store, provider_id, migrate=False)
    active_id = state.get("active_id") or ""
    current_value = provider_env_key_value(provider_id)
    profiles = []
    for profile in state.get("profiles") or []:
        value = _read_key_profile_value(profile.get("env_key"))
        if profile.get("id") == active_id and not value:
            value = current_value
        profiles.append({
            "id": profile.get("id") or "",
            "name": profile.get("name") or "",
            "has_key": bool(value),
            "key_preview": mask_secret(value),
            "active": profile.get("id") == active_id,
        })
    return {"active_id": active_id, "profiles": profiles}


def _sync_key_profiles_from_provider_payload(sync_items):
    """Keep legacy PUT /api/providers key writes in sync with saved records."""
    if not sync_items:
        return
    with GLOBAL_CONFIG_LOCK:
        store = _load_key_profile_store()
        env_updates = {}
        changed = False
        for provider_id, spec in (sync_items or {}).items():
            provider_id = str(provider_id or "").strip().lower()
            if not key_profiles_supported(provider_id):
                continue
            spec = spec if isinstance(spec, dict) else {}
            key = str(spec.get("key") or "").replace("\r", "").replace("\n", "").strip()
            state = _key_profile_state(store, provider_id, migrate=True, env_updates=env_updates)
            profiles = list(state.get("profiles") or [])
            active_id = state.get("active_id") or ""
            target_id = str(spec.get("profile_id") or "").strip() or active_id
            target = next((profile for profile in profiles if profile.get("id") == target_id), None)
            if spec.get("clear"):
                if target:
                    env_updates[target["env_key"]] = ""
                    profiles = [profile for profile in profiles if profile.get("id") != target["id"]]
                    changed = True
                next_profile = next((profile for profile in profiles if _read_key_profile_value(profile.get("env_key"))), None)
                active_id = next_profile.get("id") if next_profile else ""
                env_updates[provider_key_env(provider_id)] = _read_key_profile_value(next_profile.get("env_key")) if next_profile else ""
            elif key:
                if bool(spec.get("create_new")) or not target:
                    target = {
                        "id": _new_key_profile_id(),
                        "name": _clean_key_profile_name(spec.get("name"), f"账号 {len(profiles) + 1}"),
                        "env_key": _key_profile_env_key(provider_id, ""),
                        "created_at": _key_profile_timestamp(),
                        "updated_at": _key_profile_timestamp(),
                    }
                    target["env_key"] = _key_profile_env_key(provider_id, target["id"])
                    profiles.append(target)
                    changed = True
                elif spec.get("name"):
                    next_name = _clean_key_profile_name(spec.get("name"), target.get("name") or "账号")
                    if next_name != target.get("name"):
                        target["name"] = next_name
                        target["updated_at"] = _key_profile_timestamp()
                        changed = True
                active_id = target["id"]
                env_updates[target["env_key"]] = key
                env_updates[provider_key_env(provider_id)] = key
            record = store.setdefault("providers", {}).setdefault(provider_id, {})
            next_record = {"active_id": active_id, "profiles": profiles}
            if record != next_record:
                changed = True
            store["providers"][provider_id] = next_record
        if env_updates:
            update_env_values(env_updates)
            reload_env_globals()
        if changed or env_updates:
            _save_key_profile_store_locked(store)


def _key_profile_provider(provider_id: str):
    provider_id = str(provider_id or "").strip().lower()
    if not PROVIDER_ID_RE.fullmatch(provider_id):
        raise HTTPException(status_code=400, detail="API 平台 ID 不合法")
    provider = next((item for item in load_api_providers() if item.get("id") == provider_id), None)
    if not provider:
        raise HTTPException(status_code=404, detail="未找到 API 平台")
    if not key_profiles_supported(provider):
        raise HTTPException(status_code=400, detail="当前平台使用专用登录或 Key 类型，不支持通用 Key 记录")
    return provider_id, provider


def _key_profile_response(provider_id: str, store=None):
    provider_id = str(provider_id or "").strip().lower()
    bundle = _public_key_profile_bundle(provider_id, store)
    key = provider_env_key_value(provider_id)
    return {
        "provider_id": provider_id,
        "active_id": bundle["active_id"],
        "profiles": bundle["profiles"],
        "has_key": bool(key),
        "key_preview": mask_secret(key),
        "key_env": provider_key_env(provider_id),
    }

def strip_auth_scheme(value, scheme="Bearer"):
    text = str(value or "").strip()
    if not text:
        return ""
    pattern = rf"^{re.escape(scheme)}\s+"
    return re.sub(pattern, "", text, flags=re.I).strip()

def bearer_auth_value(value):
    token = strip_auth_scheme(value, "Bearer")
    return f"Bearer {token}" if token else ""

