@app.get("/")
async def index():
    return static_html_response("index.html")

@app.get("/api/view")
def view_image(filename: str, type: str = "input", subfolder: str = ""):
    # 先按原逻辑去各 ComfyUI 后端找
    for addr in COMFYUI_INSTANCES:
        try:
            url = f"http://{addr}/view"
            params = {"filename": filename, "type": type, "subfolder": subfolder}
            r = requests.get(url, params=params, timeout=1)
            if r.status_code == 200:
                return Response(content=r.content, media_type=r.headers.get('Content-Type'))
        except Exception:
            continue
    # 后端都拿不到时回退本地 assets/<input|output>/
    # 适用场景：画布通过 /api/ai/upload 把参考图直接落到本地 assets/input/，
    # 但 ComfyUI 的 input 可能因为重启/清理而丢失，导致 enhance/klein 等页面预览对比图 404
    if not subfolder and type in ("input", "output"):
        safe_name = os.path.basename(filename or "")
        if safe_name:
            local_path = output_path_for(safe_name, "input" if type == "input" else "output")
            if os.path.isfile(local_path):
                return FileResponse(local_path, media_type=content_type_for_path(local_path))
    raise HTTPException(status_code=404, detail="Image not found on any available backend")

@app.get("/api/download-output")
def download_output(request: Request, url: str, name: str = "", inline: bool = False):
    _share_request_media_access(request, url)
    url = rewrite_runninghub_file_url(url)
    path = output_file_from_url(url)
    if not path:
        path = local_media_file_by_basename(filename_from_media_url(url, ""))
    if path:
        filename = sanitize_export_filename(os.path.basename(name) if name else os.path.basename(path), os.path.basename(path))
        return FileResponse(path, media_type=content_type_for_path(path), filename=None if inline else filename)
    # 远程文件：流式代理，绝不把整段视频/大文件读进内存（否则多个视频同时代理会撑爆内存、拖垮单进程服务）。
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise HTTPException(status_code=400, detail="无效的下载地址")
    try:
        upstream_headers = {"User-Agent": "ComfyUI-API-Modelscope/1.0"}
        range_header = request.headers.get("range")
        if range_header:
            upstream_headers["Range"] = range_header
        upstream = requests.get(
            url, stream=True, timeout=(10, 60),
            headers=upstream_headers,
        )
        upstream.raise_for_status()
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"远程文件下载失败：{exc}")
    content_type = upstream.headers.get("content-type") or "application/octet-stream"
    fallback = filename_from_media_url(url, "download.bin")
    filename = sanitize_export_filename(os.path.basename(name) if name else fallback, fallback)
    disposition = "inline" if inline else "attachment"
    headers = {"Content-Disposition": f"{disposition}; filename*=UTF-8''{urllib.parse.quote(filename)}"}
    for key in ("content-range", "accept-ranges"):
        value = upstream.headers.get(key)
        if value:
            headers["-".join(part.capitalize() for part in key.split("-"))] = value

    def stream_remote():
        try:
            for chunk in upstream.iter_content(chunk_size=256 * 1024):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return StreamingResponse(stream_remote(), media_type=content_type, headers=headers, status_code=upstream.status_code)

@app.post("/api/upload")
async def upload_image(files: List[UploadFile] = File(...), app_id: str = Form(""), workflow_json: str = Form("")):
    uploaded_files = []
    files_content = []
    upload_addresses = list(COMFYUI_INSTANCES)
    app_item = _canvas_comfy_app_for_workflow(workflow_json, app_id)
    if app_item:
        app_library = globals().get("COMFY_APPS")
        if not app_library:
            raise HTTPException(status_code=503, detail="本地工作流应用库尚未初始化，无法上传参考图")
        upload_backend, _ = await asyncio.to_thread(app_library.backend, app_item, start=True)
        upload_backend = str(upload_backend or "").strip()
        if not re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", upload_backend):
            raise HTTPException(status_code=503, detail="应用工作流没有可用的本机 ComfyUI 地址，无法上传参考图")
        upload_addresses = [upload_backend]
    for file in files:
        content = await file.read()
        files_content.append((file, content))

    for file, content in files_content:
        success_count = 0
        last_result = None
        for addr in upload_addresses:
            try:
                files_data = {'image': (file.filename, content, file.content_type)}
                response = requests.post(f"http://{addr}/upload/image", files=files_data, timeout=5)
                if response.status_code == 200:
                    last_result = response.json()
                    success_count += 1
            except Exception as e:
                print(f"Upload error for {addr}: {e}")

        if success_count > 0 and last_result:
            uploaded_files.append({"comfy_name": last_result.get("name", file.filename)})
        else:
            raise HTTPException(
                status_code=503,
                detail="本地 ComfyUI 未启动或无法连接。请先启动对应的本地工作流环境。"
            )

    return {"files": uploaded_files}

@app.get("/api/comfyui/status")
async def comfyui_status():
    # The app library may run a separately managed ComfyUI on 8190.  It is
    # deliberately not added to COMFYUI_INSTANCES because that list controls
    # user-configured backends used by the general generation path.  The
    # workspace still needs to discover the managed editor, so report it here
    # after verifying the bridge identity instead of treating any process on
    # 8190 as ours.
    managed_runtime = getattr(globals().get("COMFY_APPS"), "runtime", None)
    managed_address = str(getattr(managed_runtime, "address", "") or "").strip()
    managed_root = str(getattr(managed_runtime, "root", "") or "").strip()
    managed_output = str(getattr(managed_runtime, "output", "") or "").strip()
    managed_enabled = bool(
        managed_runtime
        and managed_address
        and re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", managed_address)
        and managed_root
    )
    addresses = list(dict.fromkeys([*COMFYUI_INSTANCES, *(
        [managed_address] if managed_enabled and managed_address not in COMFYUI_INSTANCES else []
    )]))

    async def probe(addr):
        is_managed = managed_enabled and addr == managed_address

        def request_status():
            try:
                if is_managed:
                    identity = requests.get(f"http://{addr}/xiaomei/app-runtime", timeout=1.5)
                    identity.raise_for_status()
                    identity_data = identity.json() or {}
                    identity_root = str(identity_data.get("root") or "").strip()
                    if not identity_root or os.path.normcase(os.path.realpath(identity_root)) != os.path.normcase(os.path.realpath(managed_root)):
                        return False
                    if managed_output:
                        identity_output = str(identity_data.get("output") or "").strip()
                        if (not identity_output or
                                os.path.normcase(os.path.realpath(identity_output)) != os.path.normcase(os.path.realpath(managed_output))):
                            return False
                response = requests.get(f"http://{addr}/system_stats", timeout=1.5)
                return response.status_code == 200
            except Exception:
                return False
        result = {"address": addr, "online": await asyncio.to_thread(request_status)}
        if is_managed:
            result["managed"] = True
        return result

    instances = await asyncio.gather(*(probe(addr) for addr in addresses))
    return {"available": any(item["online"] for item in instances), "instances": instances}


@app.post("/api/comfyui/start")
async def start_comfyui():
    """Start the prepared isolated backend used by the local app library."""
    managed_runtime = getattr(globals().get("COMFY_APPS"), "runtime", None)
    if not managed_runtime:
        raise HTTPException(status_code=503, detail="本地应用运行环境尚未初始化")
    try:
        info = await asyncio.to_thread(managed_runtime.start_existing)
    except RuntimeError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except requests.RequestException as exc:
        raise HTTPException(status_code=503, detail=f"本地 ComfyUI 启动后检查失败：{exc}") from exc
    return {
        "address": managed_runtime.address,
        "managed": True,
        "node_count": len(info) if isinstance(info, dict) else 0,
        "message": "本地独立 ComfyUI 已启动",
    }


@app.post("/api/comfyui/inspect-workflow")
async def inspect_local_comfy_workflow(request: Request):
    from ComfyUI.integration.comfy_workflow_inspection import inspect_workflow
    raw = await request.body()
    if len(raw) > 20 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="工作流 JSON 超过 20MB")
    try:
        workflow = json.loads(raw)
    except (ValueError, UnicodeDecodeError):
        raise HTTPException(status_code=400, detail="无法解析 JSON 工作流")
    for address in COMFYUI_INSTANCES:
        if not re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", address):
            continue
        try:
            response = await asyncio.to_thread(requests.get, f"http://{address}/object_info", timeout=8)
            response.raise_for_status()
            info = response.json()
        except (requests.RequestException, ValueError):
            continue
        try:
            return inspect_workflow(workflow, info)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))
    raise HTTPException(status_code=503, detail="本地 ComfyUI 未连接，请启动后重新检查")

@app.post("/api/ai/upload")
async def upload_ai_reference(files: List[UploadFile] = File(...)):
    uploaded = []
    max_upload_bytes = AI_REFERENCE_UPLOAD_MAX_BYTES
    for file in files:
        content = await file.read()
        if not content:
            continue
        content_type = (file.content_type or "").lower()
        kind, ext = _local_upload_kind_ext(file.filename or "", content_type)
        if kind is None:
            kind = "file"
            ext = ext or mimetypes.guess_extension(content_type) or ".bin"
        display_name = file.filename or ""
        auto_compressed = None
        if len(content) > max_upload_bytes:
            if kind != "image":
                raise HTTPException(status_code=413, detail=f"{file.filename or '文件'} 超过 50MB，无法上传")
            auto_compressed, reason = await asyncio.to_thread(
                _auto_compress_oversize_reference_image,
                content,
                display_name,
                max_upload_bytes,
            )
            if not auto_compressed:
                raise HTTPException(status_code=413, detail=f"{file.filename or '图片'} 超过 50MB，且无法自动生成压缩上传副本：{reason or '请先缩小图片'}")
            content = auto_compressed["content"]
            ext = auto_compressed["extension"]
            content_type = auto_compressed["content_type"]
            display_name = _compressed_reference_upload_name(display_name, ext)
        filename = f"ai_ref_{uuid.uuid4().hex[:12]}{ext}"
        path = output_path_for(filename, "input")
        with open(path, "wb") as f:
            f.write(content)
        result = {"url": output_url_for(filename, "input"), "name": display_name or filename, "kind": kind, "mime": content_type}
        if kind == "image":
            result.update(_image_size_metadata_from_bytes(content))
        if auto_compressed:
            result["auto_compressed"] = _auto_compressed_reference_upload_meta(auto_compressed, file.filename)
        uploaded.append(result)
    return {"files": uploaded}

