def cli_version_from_text(value: str) -> str:
    """从 CLI 输出或官方元数据中提取可比较的语义版本号。"""
    match = re.search(r"(?<![\d.])v?(\d+(?:\.\d+){1,3})(?![\d.])", str(value or ""))
    return match.group(1) if match else ""


def antigravity_cli_manifest_platform() -> str:
    """返回 Antigravity 官方安装器使用的当前平台清单名称。"""
    if os.name == "nt":
        system = "windows"
        raw_arch = (
            os.getenv("PROCESSOR_ARCHITEW6432")
            or os.getenv("PROCESSOR_ARCHITECTURE")
            or platform.machine()
        )
    elif sys.platform == "darwin":
        system = "darwin"
        raw_arch = platform.machine()
    elif sys.platform.startswith("linux"):
        system = "linux"
        raw_arch = platform.machine()
    else:
        return ""

    arch = str(raw_arch or "").strip().lower()
    if arch in {"amd64", "x86_64", "x64"}:
        arch = "amd64"
    elif arch in {"arm64", "aarch64"}:
        arch = "arm64"
    else:
        return ""

    if system == "linux":
        libc_name = str(platform.libc_ver()[0] or "").lower()
        musl_paths = {
            "/lib/ld-musl-x86_64.so.1",
            "/lib/ld-musl-aarch64.so.1",
        }
        if "musl" in libc_name or any(os.path.exists(path) for path in musl_paths):
            return f"linux_{arch}_musl"
    return f"{system}_{arch}"


def cli_update_source(kind: str, exe: str = "") -> Dict[str, str]:
    """返回一个 CLI 对应的官方版本查询源，不执行安装或升级。"""
    kind = str(kind or "").strip().lower()
    if kind == "codex":
        return {
            "url": CODEX_CLI_LATEST_URL,
            "source": "OpenAI npm",
            "platform": "",
        }
    if kind == "jimeng":
        return {
            "url": JIMENG_CLI_VERSION_URL,
            "source": "即梦官方版本清单",
            "platform": "",
        }
    if kind == "gemini-cli":
        # 当前设置页默认接入 Antigravity。只有明确找到旧的 gemini 可执行文件时，
        # 才查询 Gemini CLI 的 npm 包，避免把两个 CLI 的版本混在一起。
        if not exe or is_antigravity_cli(exe):
            platform_id = antigravity_cli_manifest_platform()
            if not platform_id:
                return {
                    "url": "",
                    "source": "Antigravity 官方版本清单",
                    "platform": "",
                    "error": "当前系统或 CPU 架构不在 Antigravity CLI 支持范围内",
                }
            return {
                "url": f"{ANTIGRAVITY_CLI_MANIFEST_BASE_URL}/{platform_id}.json",
                "source": "Antigravity 官方版本清单",
                "platform": platform_id,
            }
        return {
            "url": GEMINI_CLI_LATEST_URL,
            "source": "Google Gemini CLI npm",
            "platform": "",
        }
    raise ValueError("不支持的 CLI 类型")


def fetch_cli_latest_version(kind: str, exe: str = "") -> Dict[str, str]:
    source = cli_update_source(kind, exe)
    if source.get("error"):
        raise RuntimeError(source["error"])
    url = source.get("url") or ""
    if not url:
        raise RuntimeError("未配置官方版本查询源")
    response = requests.get(
        f"{url}{'&' if '?' in url else '?'}t={int(time.time())}",
        headers={
            "Accept": "application/json",
            "User-Agent": "XiaomeiCanvas/CLIUpdate",
        },
        timeout=CLI_UPDATE_CHECK_TIMEOUT_SECONDS,
        proxies=urllib.request.getproxies() or None,
    )
    if not 200 <= response.status_code < 400:
        raise RuntimeError(f"官方版本源返回 HTTP {response.status_code}")
    try:
        payload = response.json()
    except ValueError as exc:
        raise RuntimeError("官方版本源返回的内容不是有效 JSON") from exc
    raw_version = payload.get("version") if isinstance(payload, dict) else ""
    latest_version = cli_version_from_text(raw_version)
    if not latest_version:
        raise RuntimeError("官方版本源没有返回有效版本号")
    return {
        "latest_version": latest_version,
        "source": source.get("source") or "官方版本源",
        "source_url": url,
        "platform": source.get("platform") or "",
    }


async def cli_local_version(kind: str, exe: str = "") -> Tuple[str, str]:
    if not exe:
        return "", ""
    if kind == "jimeng":
        version, raw_text = await jimeng_cli_version()
        if not version:
            raise RuntimeError("无法从 dreamina CLI 输出中识别版本号")
        return ".".join(str(part) for part in version), raw_text

    proc = await asyncio.create_subprocess_exec(
        exe,
        "--version",
        cwd=BASE_DIR,
        stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.PIPE,
    )
    stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=10)
    out_text, err_text = codex_decode_output(stdout, stderr)
    raw_text = out_text or err_text
    if proc.returncode != 0:
        raise RuntimeError((err_text or out_text or f"CLI 退出码 {proc.returncode}")[:240])
    current_version = cli_version_from_text(raw_text)
    if not current_version:
        raise RuntimeError("无法从 CLI 输出中识别版本号")
    return current_version, raw_text


@app.get("/api/cli/update-check")
async def cli_update_check(kind: str = "codex"):
    kind = str(kind or "").strip().lower()
    if kind not in CLI_UPDATE_KINDS:
        raise HTTPException(status_code=400, detail="不支持的 CLI 类型")

    if kind == "codex":
        exe = codex_cli_executable()
        label = "OpenAI Codex CLI"
    elif kind == "jimeng":
        exe = jimeng_cli_executable()
        if exe and not await jimeng_cli_binary_available(exe):
            exe = ""
        label = "即梦 CLI"
    else:
        exe = gemini_cli_executable()
        label = "Antigravity CLI" if not exe or is_antigravity_cli(exe) else "Gemini CLI"

    current_version = ""
    current_raw = ""
    current_error = ""
    if exe:
        try:
            current_version, current_raw = await cli_local_version(kind, exe)
        except Exception as exc:
            current_error = str(exc)[:240]

    source = cli_update_source(kind, exe)
    latest_info: Dict[str, str] = {}
    latest_error = str(source.get("error") or "")
    if not latest_error:
        try:
            latest_info = await asyncio.to_thread(fetch_cli_latest_version, kind, exe)
        except Exception as exc:
            latest_error = str(exc)[:240]

    latest_version = latest_info.get("latest_version") or ""
    update_available = version_gt(latest_version, current_version) if latest_version and current_version else None
    if latest_version and current_version:
        if update_available:
            action = "点击“安装 / 更新”升级。" if kind == "codex" and os.name == "nt" else "请使用现有 CLI 安装/更新脚本升级。"
            message = f"发现新版本：当前 {current_version}，最新 {latest_version}。{action}"
        elif version_gt(current_version, latest_version):
            message = f"本机版本 {current_version} 高于当前官方查询版本 {latest_version}，请确认发布源。"
        else:
            message = f"已是最新版本：{current_version}。"
    elif latest_version and exe:
        message = f"已找到 {label}，但当前版本无法识别。官方最新版本为 {latest_version}。"
    elif latest_version:
        message = f"未找到 {label}。官方最新版本为 {latest_version}。"
    else:
        message = f"无法获取 {label} 最新版本：{latest_error or '未知错误'}。"

    if current_error:
        message += f" 当前版本读取失败：{current_error}。"

    return {
        "ok": bool(latest_version),
        "kind": kind,
        "label": label,
        "installed": bool(exe),
        "path": exe or None,
        "current_version": current_version,
        "current_raw": current_raw,
        "latest_version": latest_version,
        "update_available": update_available,
        "message": message,
        "source": latest_info.get("source") or source.get("source") or "",
        "source_url": latest_info.get("source_url") or source.get("url") or "",
        "platform": latest_info.get("platform") or source.get("platform") or "",
        "current_error": current_error,
        "source_error": latest_error,
        "checked_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }

CODEX_INSTALL_STATE = {"status": "idle", "message": ""}
CODEX_INSTALL_TASK = None


def cli_install_require_local(request):
    if (not _request_host_is_loopback(getattr(request.client, "host", ""))
            or not _request_host_is_loopback(request.url.hostname)
            or _request_is_share_gateway(request)):
        raise HTTPException(status_code=403, detail="请在运行小美画布的电脑上安装 CLI。")
    origin = request.headers.get("origin")
    if origin and origin.rstrip("/") != str(request.base_url).rstrip("/"):
        raise HTTPException(status_code=403, detail="请从小美画布的 API 设置页安装 CLI。")


def run_cli_installer(command, log_path):
    with open(log_path, "wb") as log:
        proc = subprocess.Popen(
            command, cwd=BASE_DIR, stdin=subprocess.DEVNULL,
            stdout=log, stderr=subprocess.STDOUT,
            creationflags=subprocess.CREATE_NO_WINDOW,
        )
        try:
            return proc.wait(timeout=900)
        except subprocess.TimeoutExpired:
            # 安装器可能启动 npm 等子进程，超时后需要一并结束。
            subprocess.run(
                ["taskkill.exe", "/PID", str(proc.pid), "/T", "/F"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=subprocess.CREATE_NO_WINDOW, timeout=15,
            )
            proc.wait(timeout=15)
            raise RuntimeError("安装超过 15 分钟，请检查网络后重试。")


def run_codex_installer(command, log_path):
    # 保留旧函数名，兼容已有 Codex 安装任务；实际执行逻辑由所有 CLI 共用。
    return run_cli_installer(command, log_path)


async def finish_codex_install(command, log_path):
    try:
        code = await asyncio.to_thread(run_codex_installer, command, log_path)
        if code != 0:
            # 旧版包装脚本在 Codex 已安装、但当前窗口 PATH 尚未刷新时返回 2。
            # 只要本机 CLI 已能执行，就把这次安装恢复为成功状态。
            if code == 2:
                exe = codex_cli_executable()
                try:
                    version, _ = await cli_local_version("codex", exe)
                except Exception:
                    version = ""
                if version:
                    CODEX_IMAGE_CAPABILITY_CACHE.update({"expires_at": 0.0, "result": None})
                    CODEX_INSTALL_STATE.update(
                        status="succeeded",
                        message=(
                            f"Codex CLI 已安装并可用，版本 {version}。"
                            "当前安装窗口的 PATH 尚未刷新；小美画布已能直接使用，"
                            "如需在终端运行 codex，请重新打开 PowerShell。"
                        ),
                    )
                    return
            raise RuntimeError(f"安装未完成（退出码 {code}），请查看安装日志并重试。")
        exe = codex_cli_executable()
        version, _ = await cli_local_version("codex", exe)
        if not version:
            raise RuntimeError("安装脚本已结束，但未检测到可用的 Codex CLI。请查看安装日志；如设置了 CODEX_BIN，请检查该路径。")
        CODEX_IMAGE_CAPABILITY_CACHE.update({"expires_at": 0.0, "result": None})
        CODEX_INSTALL_STATE.update(status="succeeded", message=f"安装完成，版本 {version}。首次使用请运行 CLI/windows/openai/2-start_openai_codex_cli.bat 完成登录。")
    except Exception as exc:
        CODEX_INSTALL_STATE.update(status="failed", message=str(exc) or "安装失败，请查看安装日志后重试。")


@app.get("/api/codex/install")
async def codex_install_status(request: Request):
    cli_install_require_local(request)
    return {**CODEX_INSTALL_STATE, "supported": os.name == "nt"}


@app.post("/api/codex/install")
async def codex_install(request: Request):
    global CODEX_INSTALL_TASK
    cli_install_require_local(request)
    if os.name != "nt":
        raise HTTPException(status_code=400, detail="内置安装目前支持 Windows；其他系统请运行 CLI 目录下对应的安装脚本。")
    if CODEX_INSTALL_TASK and not CODEX_INSTALL_TASK.done():
        return {**CODEX_INSTALL_STATE, "supported": True}
    script = os.path.join(BASE_DIR, "CLI", "windows", "openai", "install_openai_codex_cli.ps1")
    if not os.path.isfile(script):
        raise HTTPException(status_code=404, detail="缺少内置 CLI 安装脚本，请补全项目的 CLI 目录后重试。")
    powershell = shutil.which("powershell.exe")
    if not powershell:
        raise HTTPException(status_code=400, detail="未找到 Windows PowerShell，请修复系统 PowerShell 后重试。")
    log_dir = os.path.join(BASE_DIR, "logs")
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, f"codex-install-{uuid.uuid4().hex}.log")
    command = [powershell, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script, "-NonInteractive"]
    CODEX_INSTALL_STATE.clear()
    CODEX_INSTALL_STATE.update(status="running", message="正在下载并安装 Codex CLI，请稍候…", log_path=log_path)
    CODEX_INSTALL_TASK = asyncio.create_task(finish_codex_install(command, log_path))
    return {**CODEX_INSTALL_STATE, "supported": True}


CLI_INSTALL_SPECS = {
    "gemini-cli": {
        "label": "Antigravity CLI",
        "script": ("CLI", "windows", "gemini", "install_gemini_cli.ps1"),
        "message": "正在下载并安装 Antigravity CLI，请稍候…",
        "done_message": "安装完成。首次使用请在终端运行 agy 完成登录。",
    },
    "jimeng": {
        "label": "即梦 CLI",
        "script": ("CLI", "windows", "jimeng", "jimeng_cli_install.ps1"),
        "message": "正在通过 WSL 下载并安装即梦 CLI，请稍候…",
        "done_message": "安装完成。请点击“扫码登录”连接即梦账户。",
    },
}
CLI_INSTALL_STATES = {kind: {"status": "idle", "message": ""} for kind in CLI_INSTALL_SPECS}
CLI_INSTALL_TASKS = {kind: None for kind in CLI_INSTALL_SPECS}


def cli_install_executable(kind: str) -> str:
    if kind == "gemini-cli":
        return gemini_cli_executable()
    if kind == "jimeng":
        return jimeng_cli_executable()
    return ""


async def verify_cli_install(kind: str):
    exe = cli_install_executable(kind)
    if not exe or (kind == "jimeng" and not await jimeng_cli_binary_available(exe)):
        raise RuntimeError(f"安装脚本已结束，但未检测到可用的 {CLI_INSTALL_SPECS[kind]['label']}。")

    if kind == "jimeng":
        version = ""
        try:
            version, _ = await cli_local_version(kind, exe)
        except Exception:
            version = ""
        if version:
            return exe, version
        # 即梦旧版本不一定支持 --version；帮助命令成功也能证明 CLI 已落地。
        try:
            await run_jimeng_cli(["-h"], timeout=20, raw_text=True)
        except Exception as exc:
            raise RuntimeError("安装脚本已结束，但未检测到可运行的 dreamina CLI。请查看安装日志。") from exc
        return exe, ""

    version, _ = await cli_local_version(kind, exe)
    if not version:
        raise RuntimeError(f"安装脚本已结束，但未能读取 {CLI_INSTALL_SPECS[kind]['label']} 版本。请查看安装日志。")
    return exe, version


async def finish_cli_install(kind: str, command, log_path):
    state = CLI_INSTALL_STATES[kind]
    spec = CLI_INSTALL_SPECS[kind]
    try:
        code = await asyncio.to_thread(run_cli_installer, command, log_path)
        if code != 0:
            raise RuntimeError(f"安装未完成（退出码 {code}），请查看安装日志并重试。")
        _, version = await verify_cli_install(kind)
        version_text = f"版本 {version}。" if version else ""
        state.update(status="succeeded", message=f"{spec['done_message']} {version_text}".strip())
    except Exception as exc:
        state.update(status="failed", message=str(exc) or "安装失败，请查看安装日志后重试。")


async def cli_install_status(kind: str, request: Request):
    cli_install_require_local(request)
    return {**CLI_INSTALL_STATES[kind], "supported": os.name == "nt"}


async def start_cli_install(kind: str, request: Request):
    cli_install_require_local(request)
    if os.name != "nt":
        raise HTTPException(status_code=400, detail="内置安装目前支持 Windows；其他系统请运行 CLI 目录下对应系统的安装脚本。")
    task = CLI_INSTALL_TASKS.get(kind)
    if task and not task.done():
        return {**CLI_INSTALL_STATES[kind], "supported": True}

    spec = CLI_INSTALL_SPECS[kind]
    script = os.path.join(BASE_DIR, *spec["script"])
    if not os.path.isfile(script):
        raise HTTPException(status_code=404, detail="缺少内置 CLI 安装脚本，请补全项目的 CLI 目录后重试。")
    powershell = shutil.which("powershell.exe")
    if not powershell:
        raise HTTPException(status_code=400, detail="未找到 Windows PowerShell，请修复系统 PowerShell 后重试。")

    log_dir = os.path.join(BASE_DIR, "logs")
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, f"{kind}-install-{uuid.uuid4().hex}.log")
    command = [powershell, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script, "-NonInteractive"]
    state = CLI_INSTALL_STATES[kind]
    state.clear()
    state.update(status="running", message=spec["message"], log_path=log_path)
    CLI_INSTALL_TASKS[kind] = asyncio.create_task(finish_cli_install(kind, command, log_path))
    return {**state, "supported": True}


