@app.post("/api/providers/{provider_id}/key-profiles")
async def save_provider_key_profile(provider_id: str, payload: ApiKeyProfilePayload):
    provider_id, provider = _key_profile_provider(provider_id)
    key = str(payload.key or "").replace("\r", "").replace("\n", "").strip()
    profile_name = _clean_key_profile_name(payload.name, "")
    if not key:
        if payload.create_new:
            raise HTTPException(status_code=400, detail="请输入 API Key")
        if not profile_name:
            raise HTTPException(status_code=400, detail="请输入账号名称")
    requested_id = str(payload.profile_id or "").strip()
    if requested_id and not KEY_PROFILE_ID_RE.fullmatch(requested_id):
        raise HTTPException(status_code=400, detail="Key 记录 ID 不合法")
    with GLOBAL_CONFIG_LOCK:
        store = _load_key_profile_store()
        env_updates = {}
        state = _key_profile_state(store, provider_id, migrate=True, env_updates=env_updates)
        profiles = list(state.get("profiles") or [])
        active_id = state.get("active_id") or ""
        create_new = bool(payload.create_new)
        target_id = requested_id or active_id
        target = next((profile for profile in profiles if profile.get("id") == target_id), None)
        if target_id and not create_new and not target:
            raise HTTPException(status_code=404, detail="未找到要更新的 Key 记录")
        if not key:
            if create_new or not target:
                raise HTTPException(status_code=400, detail="请输入 API Key")
            target["name"] = profile_name
            target["updated_at"] = _key_profile_timestamp()
            store.setdefault("providers", {})[provider_id] = {
                "active_id": active_id,
                "profiles": profiles,
            }
            if env_updates:
                update_env_values(env_updates)
                reload_env_globals()
            _save_key_profile_store_locked(store)
            return _key_profile_response(provider_id, store)
        if create_new or not target:
            target = {
                "id": _new_key_profile_id(),
                "name": profile_name or f"账号 {len(profiles) + 1}",
                "env_key": "",
                "created_at": _key_profile_timestamp(),
                "updated_at": _key_profile_timestamp(),
            }
            target["env_key"] = _key_profile_env_key(provider_id, target["id"])
            profiles.append(target)
        else:
            if profile_name:
                target["name"] = profile_name
            target["updated_at"] = _key_profile_timestamp()
        active_id = target["id"]
        env_updates[target["env_key"]] = key
        env_updates[provider_key_env(provider_id)] = key
        store.setdefault("providers", {})[provider_id] = {
            "active_id": active_id,
            "profiles": profiles,
        }
        update_env_values(env_updates)
        reload_env_globals()
        _save_key_profile_store_locked(store)
    return _key_profile_response(provider_id, store)


@app.post("/api/providers/{provider_id}/key-profiles/{profile_id}/activate")
async def activate_provider_key_profile(provider_id: str, profile_id: str):
    provider_id, provider = _key_profile_provider(provider_id)
    profile_id = str(profile_id or "").strip()
    if not KEY_PROFILE_ID_RE.fullmatch(profile_id):
        raise HTTPException(status_code=400, detail="Key 记录 ID 不合法")
    ensure_key_profile_store_for_providers([provider])
    with GLOBAL_CONFIG_LOCK:
        store = _load_key_profile_store()
        state = _key_profile_state(store, provider_id, migrate=False)
        target = next((profile for profile in state.get("profiles") or [] if profile.get("id") == profile_id), None)
        if not target:
            raise HTTPException(status_code=404, detail="未找到要切换的 Key 记录")
        key = _read_key_profile_value(target.get("env_key"))
        if not key and profile_id == state.get("active_id"):
            key = provider_env_key_value(provider_id)
        if not key:
            raise HTTPException(status_code=400, detail="这条 Key 记录不可用，请重新保存 Key")
        store.setdefault("providers", {})[provider_id] = {
            "active_id": profile_id,
            "profiles": state.get("profiles") or [],
        }
        update_env_values({provider_key_env(provider_id): key, target["env_key"]: key})
        reload_env_globals()
        _save_key_profile_store_locked(store)
    return _key_profile_response(provider_id, store)


@app.delete("/api/providers/{provider_id}/key-profiles/{profile_id}")
async def delete_provider_key_profile(provider_id: str, profile_id: str):
    provider_id, provider = _key_profile_provider(provider_id)
    profile_id = str(profile_id or "").strip()
    if not KEY_PROFILE_ID_RE.fullmatch(profile_id):
        raise HTTPException(status_code=400, detail="Key 记录 ID 不合法")
    ensure_key_profile_store_for_providers([provider])
    with GLOBAL_CONFIG_LOCK:
        store = _load_key_profile_store()
        state = _key_profile_state(store, provider_id, migrate=False)
        profiles = list(state.get("profiles") or [])
        target = next((profile for profile in profiles if profile.get("id") == profile_id), None)
        if not target:
            raise HTTPException(status_code=404, detail="未找到要删除的 Key 记录")
        was_active = profile_id == state.get("active_id")
        profiles = [profile for profile in profiles if profile.get("id") != profile_id]
        env_updates = {target["env_key"]: ""}
        next_profile = None
        if was_active:
            next_profile = next((profile for profile in profiles if _read_key_profile_value(profile.get("env_key"))), None)
            env_updates[provider_key_env(provider_id)] = _read_key_profile_value(next_profile.get("env_key")) if next_profile else ""
        active_id = next_profile.get("id") if next_profile else (state.get("active_id") if not was_active else "")
        if profiles:
            store.setdefault("providers", {})[provider_id] = {
                "active_id": active_id,
                "profiles": profiles,
            }
        else:
            store.setdefault("providers", {}).pop(provider_id, None)
        update_env_values(env_updates)
        reload_env_globals()
        _save_key_profile_store_locked(store)
    return _key_profile_response(provider_id, store)

# --- ModelScope Token (从 env 读取，不再支持通过 UI 修改) ---

@app.get("/api/config/token")
async def get_global_token():
    # 优先读 env，回退到 global_config.json（兼容旧数据）
    saved_token = modelscope_api_key()
    if saved_token:
        return {"token": saved_token}
    if os.path.exists(GLOBAL_CONFIG_FILE):
        try:
            with open(GLOBAL_CONFIG_FILE, 'r', encoding='utf-8') as f:
                config = json.load(f)
                return {"token": config.get("modelscope_token", "")}
        except:
            pass
    return {"token": ""}

# --- 在线生图 (COMFLY) ---

class TestConnectionPayload(BaseModel):
    base_url: str = ""
    api_key: str = ""
    provider_id: str = ""
    protocol: str = "openai"
    image_request_mode: str = "openai"

def protocol_from_payload(payload):
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    if provider_id == "volcengine":
        return "volcengine"
    if provider_id == "runninghub":
        return "runninghub"
    if provider_id == "jimeng":
        return "jimeng"
    base_url = str(getattr(payload, "base_url", "") or "").strip().lower()
    if "runninghub.cn" in base_url or "runninghub.ai" in base_url:
        return "runninghub"
    protocol = str(getattr(payload, "protocol", "") or "openai").strip().lower()
    return protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"

def api_key_from_payload(payload, protocol: str = ""):
    explicit = str(getattr(payload, "api_key", "") or "").strip()
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    protocol = str(protocol or protocol_from_payload(payload) or "").strip().lower()
    if explicit:
        return explicit
    if provider_id:
        if provider_id == "runninghub":
            value = os.getenv(runninghub_wallet_key_env(), "")
            if value:
                return value
        value = provider_env_key_value(provider_id)
        if value:
            return value
    if protocol == "volcengine":
        return volcengine_provider_api_key("")
    return ""

def upstream_models_url(base_url: str, protocol: str):
    if protocol == "gemini":
        return f"{base_url}/models" if base_url.endswith("/v1beta") else f"{base_url}/v1beta/models"
    if protocol == "volcengine":
        return f"{base_url}/models" if base_url.endswith("/api/v3") else f"{base_url}/api/v3/models"
    if protocol == "runninghub":
        return runninghub_openapi_url({"base_url": base_url}, "models")
    return f"{base_url}/models" if base_url.endswith("/v1") else f"{base_url}/v1/models"

def upstream_model_headers(api_key: str, protocol: str):
    if protocol == "gemini":
        return {"x-goog-api-key": api_key, "Accept": "application/json"}
    if protocol == "runninghub":
        return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}
    return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}

def volcengine_default_model_payload(status=200, message="", raw=None):
    return {
        "ok": True,
        "protocol": "volcengine",
        "status": status,
        "message": message or "方舟任务接口可用，模型列表接口未返回模型。请按实际方舟控制台模型名称手动填写视频模型。",
        "model_count": 0,
        "image_models": [],
        "chat_models": [],
        "video_models": [],
        "all": [],
        "raw": raw,
    }

def volcengine_task_probe_url(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    if base.endswith("/api/v3"):
        return f"{base}/contents/generations/tasks/healthcheck_probe_do_not_submit"
    return f"{base}/api/v3/contents/generations/tasks/healthcheck_probe_do_not_submit"

async def probe_volcengine_task_endpoint(client, base_url: str, api_key: str):
    probe_url = volcengine_task_probe_url(base_url)
    if not probe_url:
        return False, {"status": 0, "message": "Base URL 为空"}
    response = await client.get(probe_url, headers=upstream_model_headers(api_key, "volcengine"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "方舟 API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "任务接口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "方舟任务查询端点可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"方舟任务接口服务端错误 {response.status_code}", "raw": raw}

def openai_compat_root_for_probe(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if base.endswith("/api/v3"):
        base = base[: -len("/api/v3")]
    if base.endswith("/v1"):
        return base
    return f"{base}/v1" if base else ""

async def probe_openai_compat_bearer_endpoint(client, base_url: str, api_key: str):
    root = openai_compat_root_for_probe(base_url)
    if not root:
        return False, {"status": 0, "message": "Base URL 为空"}
    url = f"{root}/chat/completions"
    response = await client.post(
        url,
        headers={**upstream_model_headers(api_key, "openai"), "Content-Type": "application/json"},
        json={"messages": []},
    )
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI 兼容入口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "OpenAI 兼容 Bearer 鉴权入口可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI 兼容入口服务端错误 {response.status_code}", "raw": raw}

async def probe_openai_models_endpoint(client, base_url: str, api_key: str):
    url = upstream_models_url(base_url, "openai")
    response = await client.get(url, headers=upstream_model_headers(api_key, "openai"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (301, 302, 303, 307, 308):
        location = response.headers.get("Location") or response.headers.get("location") or ""
        suffix = f"：{location}" if location else ""
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址", "raw": raw}
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "OpenAI API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI /v1/models 返回网页 HTML，请检查请求地址是否为 API Base URL", "raw": raw}
    if response.status_code < 300:
        grouped, ids = parse_upstream_models(raw, "openai") if isinstance(raw, dict) else ({"image": [], "chat": [], "video": []}, [])
        grouped, ids = normalize_6789_model_lists(base_url, grouped, ids)
        grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
        grouped = apply_locked_recommended_model_rules(base_url, grouped)
        return True, {
            "status": response.status_code,
            "message": f"OpenAI 兼容模型列表端点可用{f'，找到 {len(ids)} 个模型' if ids else ''}",
            "raw": raw,
            "model_count": len(ids),
            "image_models": grouped["image"],
            "chat_models": grouped["chat"],
            "video_models": grouped["video"],
            "all": ids,
        }
    if 400 <= response.status_code < 500:
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 不可用 (HTTP {response.status_code})", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI /v1/models 服务端错误 {response.status_code}", "raw": raw}

async def probe_volcengine_auto_detect(client, base_url: str, api_key: str):
    task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
    if task_ok:
        return True, {
            "status": task_probe.get("status") or 200,
            "message": "检测到方舟/Ark 任务协议",
            "raw": {"task_probe": task_probe.get("raw")},
        }
    compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
    if compat_ok:
        return True, {
            "status": compat_probe.get("status") or 200,
            "message": "检测到方舟/Ark Bearer 鉴权入口（OpenAI 兼容透传）",
            "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
        }
    return False, {
        "status": compat_probe.get("status") or task_probe.get("status") or 0,
        "message": compat_probe.get("message") or task_probe.get("message") or "未检测到方舟/Ark 兼容入口",
        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
    }

def classify_upstream_model(mid):
    lc = str(mid or "").lower()
    # 上游 /v1/models 通常只返回模型 ID，不带能力元数据。这里优先识别已知的
    # 视频系列；例如部分兼容网关返回的是 ``seedance-2.0``、
    # ``minimax-h3-2k``，并不包含旧规则中的 ``doubao-seedance`` 或
    # ``video`` 字样，若漏掉会被错误地兜底归为聊天模型。
    video_keys = [
        "veo", "sora", "wan2", "wanx", "seedance", "doubao-1",
        "kling", "hailuo", "minimax-h3", "minimax-video", "minimax-01",
        "video", "t2v-", "i2v-", "s2v",
    ]
    if any(k in lc for k in video_keys):
        return "video"
    image_keys = ["banana", "image", "dalle", "dall-e", "imagen", "flux", "stable", "sdxl", "midjourney", "nano-banana", "ideogram", "fal-ai", "z-image", "qwen-image", "klein", "seedream", "doubao-seedream", "text-to-image", "image-to-image"]
    if any(k in lc for k in image_keys):
        return "image"
    return "chat"

# 6789API 文档中的 Seedance 模型 ID 是小写；当前 /v1/models 偶尔会把
# seedance2.5 返回成 ``Seedance2.5``。只规范这几个已由 6789 视频文档
# 明确定义的 ID，不改变其它平台或其它模型的原始名称。
VIDEO_6789_MODEL_ALIASES = {
    "seedance2.0": "seedance2.0",
    "seedance2.0fast": "seedance2.0fast",
    "seedance2.0mini": "seedance2.0mini",
    "seedance2.5": "seedance2.5",
}

def normalize_6789_model_id(value):
    text = str(value or "").strip()
    return VIDEO_6789_MODEL_ALIASES.get(text.lower(), text)

def normalize_6789_model_lists(base_url, grouped, ids):
    if not is_6789_provider({"base_url": base_url}):
        return grouped, ids
    normalized_ids = []
    for value in ids or []:
        model_id = normalize_6789_model_id(value)
        if model_id and model_id not in normalized_ids:
            normalized_ids.append(model_id)
    normalized_grouped = {"image": [], "chat": [], "video": []}
    for category, values in (grouped or {}).items():
        target = category if category in normalized_grouped else "chat"
        for value in values or []:
            model_id = normalize_6789_model_id(value)
            if model_id and model_id not in normalized_grouped[target]:
                normalized_grouped[target].append(model_id)
    for category in normalized_grouped:
        normalized_grouped[category] = sorted(normalized_grouped[category])
    return normalized_grouped, sorted(set(normalized_ids))

UPSTREAM_MODEL_UNAVAILABLE_STATES = {
    "archived",
    "decommissioned",
    "deleted",
    "disabled",
    "discontinued",
    "inactive",
    "not_found",
    "not-found",
    "offline",
    "removed",
    "retired",
    "suspended",
    "unavailable",
}

def upstream_model_flag(value):
    """Normalize availability flags without rejecting unknown vendor values."""
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    text = str(value or "").strip().lower()
    if text in {"", "unknown", "null", "none"}:
        return True
    return text not in {"0", "false", "no", "off", "disabled", "inactive", "unavailable"}

def upstream_model_is_available(item):
    """Keep only models the upstream explicitly reports as usable."""
    if not isinstance(item, dict):
        return True
    for key in ("deleted", "disabled"):
        if key in item and upstream_model_flag(item.get(key)):
            return False
    for key in ("enabled", "available", "active", "is_active"):
        if key in item and not upstream_model_flag(item.get(key)):
            return False
    for key in ("status", "state"):
        value = item.get(key)
        if isinstance(value, str) and value.strip().lower().replace(" ", "_") in UPSTREAM_MODEL_UNAVAILABLE_STATES:
            return False
    return True

def parse_upstream_models(raw, protocol="openai"):
    items = raw.get("data") if isinstance(raw, dict) else None
    if not items and isinstance(raw, dict):
        items = raw.get("models") or raw.get("list") or []
    if not isinstance(items, list):
        items = []
    ids = []
    for it in items:
        if isinstance(it, dict) and not upstream_model_is_available(it):
            continue
        if isinstance(it, str):
            mid = it
        elif isinstance(it, dict):
            mid = it.get("id") or it.get("name") or it.get("model")
        else:
            mid = ""
        if mid:
            mid = str(mid).strip()
            if protocol == "gemini" and mid.startswith("models/"):
                mid = mid[len("models/"):]
            if mid:
                ids.append(mid)
    ids = sorted(set(ids))
    grouped = {"image": [], "chat": [], "video": []}
    for mid in ids:
        grouped[classify_upstream_model(mid)].append(mid)
    return grouped, ids

def apply_agnes_model_defaults(base_url, grouped, ids):
    if "apihub.agnes-ai.com" not in str(base_url or "").strip().lower():
        return grouped, ids
    # A non-empty successful response is authoritative.  Only use the local
    # capability fallback when the endpoint returned no model records at all;
    # otherwise removed Agnes IDs would be reintroduced on every refresh.
    if ids:
        return grouped, ids
    grouped = {key: list(value or []) for key, value in (grouped or {}).items()}
    ids = list(ids or [])
    for model in AGNES_DEFAULT_VIDEO_MODELS:
        if model not in ids:
            ids.append(model)
        if model not in grouped.setdefault("video", []):
            grouped["video"].append(model)
    ids = sorted(set(ids))
    grouped["video"] = sorted(set(grouped.get("video") or []))
    return grouped, ids

@app.post("/api/providers/test-connection")
async def test_provider_connection(payload: TestConnectionPayload):
    """测试请求地址是否可用：调上游 /v1/models。验证通过时同时把模型清单按类别返回，避免再调一次拉取接口。"""
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        return await codex_live_models_payload()
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload_models = await gemini_cli_models_payload(raw={"status": status}, exe=status.get("path"))
        payload_models.update({
            "ok": bool(status.get("installed")),
            "status": 200 if status.get("installed") else 0,
            "message": status.get("message") or ("Antigravity CLI 可用" if status.get("installed") else "未找到 Antigravity CLI"),
        })
        return payload_models
    if protocol == "jimeng":
        status = await jimeng_status()
        return {
            "ok": bool(status.get("installed") and status.get("logged_in")),
            "status": 200 if status.get("logged_in") else 0,
            "message": status.get("message") or "即梦 CLI 已登录",
            "model_count": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
            "raw": status.get("raw"),
        }
    if protocol == "runninghub":
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": (payload.base_url or RUNNINGHUB_DEFAULT_BASE_URL).strip().rstrip("/"), "protocol": "runninghub", "api_key": api_key_from_payload(payload, protocol)}
        payload_models = await runninghub_models_payload(provider)
        return {
            "ok": True,
            "status": 200,
            "message": "RunningHub OpenAPI 可用，已拉取官方直连模型注册表。",
            "model_count": payload_models["total"],
            "image_models": payload_models["image_models"],
            "chat_models": payload_models["chat_models"],
            "video_models": payload_models["video_models"],
            "all": payload_models["all"],
            "protocol": "runninghub",
            "raw": payload_models.get("raw"),
        }
    base_url = (payload.base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址"}
            if looks_like_html_response(resp.text):
                endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL"}
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                return {"ok": False, "status": resp.status_code, "message": resp.text[:300]}
            data = resp.json() if resp.text else {}
            grouped, ids = parse_upstream_models(data, protocol)
            grouped, ids = normalize_6789_model_lists(base_url, grouped, ids)
            grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
            grouped = apply_locked_recommended_model_rules(base_url, grouped)
            if protocol == "volcengine" and not ids:
                detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return volcengine_default_model_payload(status=resp.status_code, raw=data)
            return {
                "ok": True,
                "status": resp.status_code,
                "model_count": len(ids),
                "image_models": grouped["image"],
                "chat_models": grouped["chat"],
                "video_models": grouped["video"],
                "all": ids,
                "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
            }
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or 0, message=message, raw={"models_error": str(e)[:300], **(probe.get("raw") or {})})
            except Exception:
                pass
        return {"ok": False, "status": 0, "message": str(e)[:300]}

@app.post("/api/providers/probe-async")
async def probe_async_endpoint(payload: TestConnectionPayload):
    """验证异步协议：用假 task_id 请求 GET /v1/tasks/{fake_id}。
    收到 400 Invalid task ID = 端点存在且 Key 有效；401/403 = Key 无效；404/连接失败 = 不支持异步端点。"""
    base_url = (payload.base_url or "").strip().rstrip("/")
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        status = await codex_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "codex",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "OpenAI Codex CLI 本机检测完成",
            "raw": status,
        }
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "gemini-cli",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "Antigravity CLI 本机检测完成",
            "raw": status,
        }
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        raise HTTPException(status_code=400, detail="请先填写或保存 API Key")
    if protocol == "volcengine":
        try:
            async with httpx.AsyncClient(timeout=15) as client:
                task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
                if task_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": task_probe.get("status") or 200,
                        "message": "方舟/Ark 任务协议可用",
                        "raw": task_probe.get("raw"),
                    }
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                if compat_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": compat_probe.get("status") or 200,
                        "message": "方舟/Ark Bearer 鉴权入口可用（OpenAI 兼容透传）",
                        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                    }
                return {
                    "ok": False,
                    "protocol": "volcengine",
                    "status_code": compat_probe.get("status") or task_probe.get("status") or 0,
                    "message": compat_probe.get("message") or task_probe.get("message") or "方舟/Ark 任务协议不可用",
                    "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                }
        except httpx.HTTPError as e:
            raise HTTPException(status_code=502, detail=str(e)[:300])
    tasks_base = base_url if base_url.endswith("/v1") else f"{base_url}/v1"
    probe_url = f"{tasks_base}/tasks/healthcheck_probe_do_not_submit"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(probe_url, headers={"Authorization": bearer_auth_value(api_key), "Accept": "application/json"})
            try:
                body = resp.json()
            except Exception:
                body = resp.text[:500]
            sc = resp.status_code
            # 判断结果
            err_msg = ""
            if isinstance(body, dict):
                err = body.get("error") or {}
                if isinstance(err, dict):
                    err_msg = str(err.get("message") or "").lower()
                else:
                    err_msg = str(err).lower()
            # 400 + "invalid task id" → 端点存在，Key 有效
            if sc == 400 and "invalid task id" in err_msg:
                return {"ok": True, "protocol": "apimart", "status_code": sc, "message": "APIMart 异步任务端点可用，API Key 已通过认证", "raw": body}

            async_probe = {"status": sc, "message": "", "raw": body}
            if sc in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                async_probe["message"] = f"/v1/tasks/ 发生跳转{f'：{location}' if location else ''}"
            elif looks_like_html_response(resp.text):
                async_probe["message"] = "/v1/tasks/ 返回网页 HTML"
            elif sc in (401, 403):
                async_probe["message"] = "/v1/tasks/ 返回鉴权失败"
            elif sc == 404:
                async_probe["message"] = "平台不支持 /v1/tasks/ 端点，可能不是 APIMart 异步协议"
            elif 400 <= sc < 500:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}"
            elif sc < 300:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}（意外成功）"
            else:
                async_probe["message"] = f"/v1/tasks/ 服务端错误 {sc}"

            if protocol == "apimart":
                return {"ok": False, "protocol": "apimart", "status_code": sc, "message": async_probe["message"], "raw": body}

            openai_ok, openai_probe = await probe_openai_models_endpoint(client, base_url, api_key)
            if not openai_ok and protocol == "openai":
                # /v1/models 不可用，先确认是不是“没实现 models 接口的 OpenAI 兼容站”：探一下 /v1/chat/completions。
                # 可达就判定为 OpenAI 兼容（很多网关不暴露 /v1/models），避免被下面的方舟探测（404 也算可达）误判成方舟。
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                # 仅当 /v1/chat/completions 确实存在（返回 2xx 或我们发空 messages 触发的 400 等，而非 404 路径不存在）
                # 才判为 OpenAI 兼容；404 说明该路径不存在，留给后面的方舟探测。
                if compat_ok and (compat_probe.get("status") or 0) != 404:
                    return {
                        "ok": True,
                        "protocol": "openai",
                        "status_code": compat_probe.get("status") or openai_probe.get("status") or sc,
                        "message": "OpenAI 兼容入口可达（该站未提供 /v1/models，模型请手动填写）",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), "openai_compat_probe": compat_probe.get("raw")},
                        "model_count": 0,
                        "image_models": [],
                        "chat_models": [],
                        "video_models": [],
                        "all": [],
                    }
                detected, volc_probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": volc_probe.get("status") or openai_probe.get("status") or sc,
                        "message": f"{volc_probe.get('message') or '检测到方舟/Ark 兼容入口'}，已自动切换为方舟/Ark 任务协议",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), **(volc_probe.get("raw") or {})},
                    }
            return {
                "ok": openai_ok,
                "protocol": "openai",
                "status_code": openai_probe.get("status") or sc,
                "message": openai_probe.get("message") or "OpenAI 兼容验证完成",
                "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw")},
                "model_count": openai_probe.get("model_count") or 0,
                "image_models": openai_probe.get("image_models") or [],
                "chat_models": openai_probe.get("chat_models") or [],
                "video_models": openai_probe.get("video_models") or [],
                "all": openai_probe.get("all") or [],
                "image_request_mode": detect_image_request_mode(base_url, openai_probe.get("all") or []) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
            }
    except httpx.HTTPError as e:
        raise HTTPException(status_code=502, detail=str(e)[:300])

async def fetch_models_from_upstream(base_url: str, api_key: str, protocol: str = "openai", image_request_mode: str = "openai"):
    """从上游模型列表端点拉取模型，并按名称做轻量分类。"""
    protocol = protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"
    if protocol == "codex":
        return await codex_live_models_payload()
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload = await gemini_cli_models_payload(raw={"status": status}, exe=status.get("path"))
        payload["message"] = status.get("message") or payload["message"]
        return payload
    if protocol == "jimeng":
        return {
            "total": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
        }
    if protocol == "runninghub":
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": base_url or RUNNINGHUB_DEFAULT_BASE_URL, "protocol": "runninghub", "api_key": api_key}
        return await runninghub_models_payload(provider)
    base_url = (base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = volcengine_provider_api_key(api_key) if protocol == "volcengine" else (api_key or "").strip()
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址")
            if looks_like_html_response(resp.text):
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL")
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                raise HTTPException(status_code=resp.status_code, detail=f"上游 {endpoint_label} 失败：{resp.text[:300]}")
            raw = resp.json()
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or 0,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": str(e)[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
            except Exception:
                pass
        raise HTTPException(status_code=502, detail=f"请求上游模型列表失败：{e}")
    grouped, ids = parse_upstream_models(raw, protocol)
    grouped, ids = normalize_6789_model_lists(base_url, grouped, ids)
    grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
    grouped = apply_locked_recommended_model_rules(base_url, grouped)
    if protocol == "volcengine" and not ids:
        payload = volcengine_default_model_payload(raw=raw)
        return {
            "total": payload["model_count"],
            "image_models": payload["image_models"],
            "chat_models": payload["chat_models"],
            "video_models": payload["video_models"],
            "all": payload["all"],
            "message": payload["message"],
            "raw": payload["raw"],
        }
    return {
        "total": len(ids),
        "image_models": grouped["image"],
        "chat_models": grouped["chat"],
        "video_models": grouped["video"],
        "all": ids,
        "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(image_request_mode),
    }

@app.post("/api/providers/fetch-models")
async def fetch_upstream_models_from_payload(payload: TestConnectionPayload, response: Response):
    """按页面当前表单值拉取模型，支持新增平台未保存时直接使用临时 Base URL / Key。"""
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    response.headers["Pragma"] = "no-cache"
    protocol = protocol_from_payload(payload)
    api_key = api_key_from_payload(payload, protocol)
    return await fetch_models_from_upstream(payload.base_url, api_key, protocol, payload.image_request_mode)

@app.get("/api/providers/{provider_id}/fetch-models")
async def fetch_upstream_models(provider_id: str, response: Response):
    """从已保存的上游 OpenAI 兼容接口拉取 /v1/models 列表，按名称智能分类为 image/chat/video。"""
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    response.headers["Pragma"] = "no-cache"
    provider = get_api_provider_exact(provider_id)
    if is_codex_provider(provider):
        return await fetch_models_from_upstream("", "", "codex", provider.get("image_request_mode") or "openai")
    if is_gemini_cli_provider(provider):
        return await fetch_models_from_upstream("", "", "gemini-cli", provider.get("image_request_mode") or "openai")
    api_key = os.getenv(runninghub_wallet_key_env(), "") if provider["id"] == "runninghub" else ""
    if not api_key:
        api_key = provider_env_key_value(provider["id"])
    if not api_key:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider_id} 未配置 API Key")
    return await fetch_models_from_upstream(provider.get("base_url") or "", api_key, provider_protocol(provider), provider.get("image_request_mode") or "openai")

async def build_online_image_result(payload: OnlineImageRequest, history_source=""):
    provider = get_api_provider(payload.provider_id)
    default_model = (provider.get("image_models") or [IMAGE_MODEL])[0]
    model = selected_model(payload.model, default_model)
    history_source = normalize_history_source(payload.history_source or history_source, "online")
    project_id = str(payload.project_id or "").strip()
    requested_size = snap_size_to_multiple(payload.size, 16)
    request_size = normalize_gpt_image_2_size(requested_size) if is_gpt_image_2_model(model) else requested_size
    request_background = normalize_gpt_image_25_background(payload.background) if is_gpt_image_2_model(model) else ""
    if request_size != requested_size:
        print(f"GPT-Image-2 任务尺寸已按上游像素上限收敛：{requested_size or 'auto'} → {request_size}")
    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    count = max(1, min(8, int(payload.n or 1)))
    operation = str(payload.operation or "").strip().lower()
    outpaint_preserve = payload.outpaint_preserve if payload.outpaint_mode else {}
    if payload.outpaint_mode:
        _outpaint_source_draw_geometry(1, 1, outpaint_preserve)
        if not str(outpaint_preserve.get("sourceUrl") or "").strip() or not image_refs:
            raise HTTPException(status_code=400, detail="扩图缺少原图或扩图底图，请重新打开扩图编辑器")
        if len(image_refs) != 1:
            raise HTTPException(status_code=400, detail="扩图需要一张已定位的底图，请重新打开扩图编辑器")
        image_refs = [{**image_refs[0], "outpaint_canvas": True}]
    if operation == "upscale":
        if not is_jimeng_provider(provider):
            raise HTTPException(status_code=400, detail="图片放大目前仅支持即梦（Dreamina）平台")
        if not image_refs:
            raise HTTPException(status_code=400, detail="请先选择要放大的图片")
        count = 1
    async def generate_one():
        seen_hashes = set()
        if operation == "upscale":
            image_data, raw_item = await generate_jimeng_upscale_image(image_refs, payload.resolution_type)
        else:
            image_data, raw_item = await generate_ai_image(
                payload.prompt,
                request_size,
                payload.quality,
                model,
                image_refs,
                provider["id"],
                payload.aspect_ratio,
                request_background,
            )
        upstream_task_id = extract_task_id(raw_item) if isinstance(raw_item, dict) else None
        try:
            try:
                image_items = extract_images(raw_item) if isinstance(raw_item, dict) else [image_data]
            except HTTPException:
                image_items = [image_data]
            local_urls = []
            local_items = []
            for item in image_items:
                local_url = await save_ai_image_to_output(item, prefix="online_", seen_hashes=seen_hashes)
                if local_url:
                    local_urls.append(local_url)
                    local_items.append(image_output_meta(local_url, item))
            if not local_urls:
                raise HTTPException(status_code=502, detail="上游任务已完成，但没有取得可保存的图片数据")
            local_urls, local_items = await preserve_outpaint_centers(
                local_urls,
                local_items,
                outpaint_preserve,
            )
            return local_urls, local_items, raw_item
        except Exception as exc:
            # 上游已成功创建任务后，即使下载/落盘失败，也要把任务 ID 交给前端继续查询，
            # 不能让某一张结果静默消失。
            if upstream_task_id:
                setattr(exc, "upstream_task_id", upstream_task_id)
            raise
    try:
        generated = await asyncio.gather(*(generate_one() for _ in range(count)))
    except httpx.HTTPStatusError as exc:
        log_net_error(f"生图 HTTP状态错误 provider={provider.get('id')} model={model} size={request_size}", exc)
        text = exc.response.text or ''
        friendly = friendly_image_error_detail(text, request_size, model)
        detail = friendly or f"上游生图接口错误：{text[:300]}"
        raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
    except httpx.HTTPError as exc:
        log_net_error(f"生图 网络/TLS错误 provider={provider.get('id')} model={model}", exc)
        raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{exc}") from exc

    local_urls = [url for urls, _items, _raw in generated for url in (urls or []) if url]
    local_items = [item for _urls, items, _raw in generated for item in (items or []) if item.get("url")]
    raw = generated[0][2] if generated else {}
    if not local_urls:
        provider_name = provider.get("name") or provider["id"]
        raw_text = json.dumps(raw, ensure_ascii=False)[:800] if isinstance(raw, (dict, list)) else str(raw)[:800]
        raise HTTPException(status_code=502, detail=f"{provider_name} 没有返回图片：{raw_text}")
    result = {
        "prompt": payload.prompt,
        "images": local_urls,
        "image_items": local_items,
        "timestamp": time.time(),
        "type": "online",
        "history_source": history_source,
        "project_id": project_id,
        "operation": operation,
        "model": model,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "task_id": extract_task_id(raw) if isinstance(raw, dict) else None,
        "request_id": raw.get("id") if isinstance(raw, dict) else None,
        "skill_id": str(payload.skill_id or "").strip(),
        "skill_name": str(payload.skill_name or "").strip(),
        "skill_applied": bool(payload.skill_applied and str(payload.skill_id or "").strip()),
        "params": {
            "provider_id": provider["id"],
            "model": model,
            "history_source": history_source,
            "project_id": project_id,
            "size": request_size,
            "requested_size": requested_size,
            "size_adjusted": request_size != requested_size,
            "aspect_ratio": payload.aspect_ratio,
            "quality": payload.quality,
            "background": request_background,
            "n": count,
            "operation": operation,
            "resolution_type": jimeng_normalize_upscale_resolution(payload.resolution_type) if operation == "upscale" else "",
            "reference_images": refs,
            "skill_id": str(payload.skill_id or "").strip(),
            "skill_name": str(payload.skill_name or "").strip(),
            "skill_applied": bool(payload.skill_applied and str(payload.skill_id or "").strip()),
        },
        "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
    }
    save_to_history(result)
    if GLOBAL_LOOP:
        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
    return result

@app.post("/api/online-image")
async def online_image(payload: OnlineImageRequest):
    return await build_online_image_result(payload)

@app.post("/api/image-task-query")
async def query_image_task(payload: ImageTaskQueryRequest):
    provider = get_api_provider(payload.provider_id)
    task_id = str(payload.task_id or "").strip()
    if is_runninghub_provider(provider):
        api_key = runninghub_api_key(provider)
        url = runninghub_endpoint_url(provider, "/task/openapi/outputs")
        try:
            async with httpx.AsyncClient(timeout=httpx.Timeout(connect=20.0, read=240.0, write=30.0, pool=20.0)) as client:
                response = await client.post(url, headers=runninghub_app_headers(True), json={"apiKey": api_key, "taskId": task_id})
                response.raise_for_status()
                raw = response.json()
                code = raw.get("code") if isinstance(raw, dict) else None
                if code in (0, "0"):
                    local_urls = []
                    local_items = []
                    for remote in runninghub_extract_outputs(raw.get("data")):
                        try:
                            local_url = await runninghub_store_remote_output(client, remote)
                        except Exception:
                            local_url = rewrite_runninghub_file_url(remote)
                        if local_url:
                            local_urls.append(local_url)
                            local_items.append(image_output_meta(local_url))
                    result = {
                        "status": "succeeded",
                        "prompt": "",
                        "images": local_urls,
                        "image_items": local_items,
                        "timestamp": time.time(),
                        "type": "online",
                        "history_source": normalize_history_source(payload.history_source, "online"),
                        "project_id": str(payload.project_id or "").strip(),
                        "model": "",
                        "provider_id": provider["id"],
                        "provider_name": provider.get("name") or provider["id"],
                        "task_id": task_id,
                        "request_id": "",
                        "params": {
                            "provider_id": provider["id"],
                            "project_id": str(payload.project_id or "").strip(),
                        },
                        "raw": raw,
                    }
                    save_to_history(result)
                    if GLOBAL_LOOP:
                        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
                    return result
                if code in (805, "805"):
                    return {
                        "status": "failed",
                        "task_id": task_id,
                        "provider_id": provider["id"],
                        "provider_name": provider.get("name") or provider["id"],
                        "error": runninghub_fail_reason(raw),
                        "raw": raw,
                    }
                return {
                    "status": "running",
                    "task_id": task_id,
                    "provider_id": provider["id"],
                    "provider_name": provider.get("name") or provider["id"],
                    "message": "RunningHub 任务仍在生成中",
                    "raw": raw,
                }
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            raise HTTPException(status_code=exc.response.status_code, detail=f"查询 RunningHub 任务失败：{text[:300]}") from exc
        except httpx.HTTPError as exc:
            raise HTTPException(status_code=502, detail=f"查询 RunningHub 任务失败：{exc}") from exc
    timeout = httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0)
    try:
        async with httpx.AsyncClient(timeout=timeout, follow_redirects=True) as client:
            raw = await fetch_image_task_payload(client, task_id, provider)
    except httpx.HTTPStatusError as exc:
        log_net_error(f"查询生图任务 HTTP状态错误 provider={provider.get('id')} task_id={task_id}", exc)
        text = exc.response.text or ""
        raise HTTPException(status_code=exc.response.status_code, detail=f"查询上游生图任务失败：{text[:300]}") from exc
    except httpx.HTTPError as exc:
        log_net_error(f"查询生图任务 网络/TLS错误 provider={provider.get('id')} task_id={task_id}", exc)
        raise HTTPException(status_code=502, detail=f"查询上游生图任务失败：{exc}") from exc

    upstream_error = image_task_error_payload(raw)
    if upstream_error is not None:
        return {
            "status": "failed",
            "task_id": task_id,
            "provider_id": provider["id"],
            "provider_name": provider.get("name") or provider["id"],
            "error": image_task_fail_reason(raw),
            "error_code": image_task_error_code(raw),
            "raw": raw,
        }

    status = image_task_status(raw)
    image_items = []
    try:
        image_items = extract_images(raw)
    except HTTPException:
        image_items = []
    if image_items:
        local_urls = []
        local_items = []
        for item in image_items:
            local_url = await save_ai_image_to_output(item, prefix="online_")
            if local_url:
                local_urls.append(local_url)
                local_items.append(image_output_meta(local_url, item))
        if not local_urls:
            return {
                "status": "failed",
                "task_id": task_id,
                "provider_id": provider["id"],
                "provider_name": provider.get("name") or provider["id"],
                "error": "上游任务已返回图片，但本地下载或保存失败，暂时没有可展示的图片。请稍后重新查询，避免重复提交。",
                "raw": raw,
            }
        result = {
            "status": "succeeded",
            "prompt": "",
            "images": local_urls,
            "image_items": local_items,
            "timestamp": time.time(),
            "type": "online",
            "history_source": normalize_history_source(payload.history_source, "online"),
            "project_id": str(payload.project_id or "").strip(),
            "model": "",
            "provider_id": provider["id"],
            "provider_name": provider.get("name") or provider["id"],
            "task_id": task_id,
            "request_id": raw.get("id") if isinstance(raw, dict) else "",
            "params": {
                "provider_id": provider["id"],
                "project_id": str(payload.project_id or "").strip(),
            },
            "raw": raw,
        }
        save_to_history(result)
        if GLOBAL_LOOP:
            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
        return result
    if status in IMAGE_TASK_FAILED_STATUSES:
        return {
            "status": "failed",
            "task_id": task_id,
            "provider_id": provider["id"],
            "provider_name": provider.get("name") or provider["id"],
            "error": image_task_fail_reason(raw),
            "raw": raw,
        }
    return {
        "status": "running",
        "task_id": task_id,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "message": "任务仍在生成中",
        "raw": raw,
    }

@app.post("/api/image-result-recovery/{recovery_id}")
async def recover_unparsed_image_result(
    recovery_id: str,
    history_source: str = "online",
    project_id: str = "",
):
    """从已保存的上游响应恢复图片，不再次请求生图模型。"""
    record = load_unparsed_image_response(recovery_id)
    if not record:
        raise HTTPException(status_code=404, detail="没有找到该恢复记录")
    try:
        image_items = extract_images(record.get("raw"))
    except HTTPException as exc:
        raise HTTPException(
            status_code=502,
            detail="恢复记录仍无法识别，请保留恢复编号并更新解析器；系统不会重新调用模型扣费。",
        ) from exc
    local_urls = []
    local_items = []
    for item in image_items:
        local_url = await save_ai_image_to_output(item, prefix="recovered_")
        if not local_url:
            continue
        local_urls.append(local_url)
        local_items.append(image_output_meta(local_url, item))
    if not local_urls:
        raise HTTPException(status_code=502, detail="已识别上游图片，但下载或保存失败；系统没有重新调用模型。")
    result = {
        "status": "succeeded",
        "prompt": "",
        "images": local_urls,
        "image_items": local_items,
        "timestamp": time.time(),
        "type": "online",
        "history_source": normalize_history_source(history_source, "online"),
        "project_id": str(project_id or "").strip(),
        "model": record.get("model") or "",
        "provider_id": record.get("provider_id") or "",
        "provider_name": record.get("provider_id") or "",
        "task_id": record.get("task_id") or "",
        "request_id": recovery_id,
        "params": {
            "provider_id": record.get("provider_id") or "",
            "recovery_id": recovery_id,
            "project_id": str(project_id or "").strip(),
        },
        "recovered_without_generation": True,
    }
    save_to_history(result)
    if GLOBAL_LOOP:
        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
    return result

async def _run_canvas_image_task(task_id: str, payload: OnlineImageRequest):
    update_canvas_task(task_id, {
        "status": "running",
        "started_at": time.time(),
        "message": "任务已开始生成",
    })
    try:
        result = await build_online_image_result(
            payload,
            history_source=normalize_history_source(payload.history_source, "canvas"),
        )
        update_canvas_task(task_id, {
            "status": "succeeded",
            "result": result,
            "error": "",
        })
    except JimengPendingError as exc:
        # 即梦云端还在排队：标记为 jimeng_pending，前端据 submit_id 持久续查（任务未丢失）
        info = jimeng_pending_payload(exc)
        update_canvas_task(task_id, {
            "status": "jimeng_pending",
            "jimeng_pending": True,
            "submit_id": exc.submit_id,
            "kind": exc.kind,
            "queue_info": exc.queue_info,
            "message": info["message"],
            "error": "",
        })
    except Exception as exc:
        detail = getattr(exc, "detail", None) or str(exc)
        status_code = getattr(exc, "status_code", 500)
        upstream_task_id = getattr(exc, "upstream_task_id", "") or extract_task_id_from_text(detail)
        recovery_id = getattr(exc, "recovery_id", "")
        update_canvas_task(task_id, {
            "status": "failed",
            "error": str(detail),
            "status_code": status_code,
            "upstream_task_id": upstream_task_id,
            "recovery_id": recovery_id,
        })


async def run_canvas_image_task(task_id: str, payload: OnlineImageRequest):
    """Run one canvas image task after it obtains a shared generation slot."""
    semaphore = canvas_image_task_semaphore()
    if semaphore is None:
        await _run_canvas_image_task(task_id, payload)
        return
    async with semaphore:
        await _run_canvas_image_task(task_id, payload)


@app.post("/api/canvas-image-tasks")
async def create_canvas_image_task(payload: OnlineImageRequest):
    client_request_id = _normalize_canvas_client_request_id(payload.client_request_id)
    if client_request_id:
        existing = _find_canvas_task_by_client_request_id(client_request_id)
        if existing:
            return {
                "task_id": existing.get("id"),
                "status": existing.get("status") or "queued",
                "recovered": True,
            }
    task_id = f"canvas_img_{uuid.uuid4().hex}"
    add_canvas_task(task_id, {
        "id": task_id,
        "type": "online-image",
        "status": "queued",
        "created_at": time.time(),
        "updated_at": time.time(),
        "result": None,
        "error": "",
        "provider_id": payload.provider_id,
        "model": payload.model,
        "client_request_id": client_request_id,
        "history_source": normalize_history_source(payload.history_source, "canvas"),
        "project_id": str(payload.project_id or "").strip(),
        "skill_id": str(payload.skill_id or "").strip(),
        "skill_name": str(payload.skill_name or "").strip(),
        "skill_applied": bool(payload.skill_applied and str(payload.skill_id or "").strip()),
        "request": {
            "size": payload.size,
            "aspect_ratio": payload.aspect_ratio,
            "quality": payload.quality,
            "background": payload.background,
            "operation": payload.operation,
            "resolution_type": payload.resolution_type,
            "outpaint_mode": bool(payload.outpaint_mode),
            "reference_count": len([ref for ref in payload.reference_images if ref.url]),
        },
    })
    asyncio.create_task(run_canvas_image_task(task_id, payload))
    return {"task_id": task_id, "status": "queued", "client_request_id": client_request_id}


@app.get("/api/canvas-image-tasks/recover")
async def recover_canvas_image_task(client_request_id: str = ""):
    """Recover a task whose POST response was lost by the browser.

    This endpoint never creates or retries a generation request.  It only
    returns the already persisted task ID for the matching opaque client ID.
    """
    request_id = _normalize_canvas_client_request_id(client_request_id)
    if not request_id:
        raise HTTPException(status_code=400, detail="缺少有效的画布任务关联 ID")
    task = _find_canvas_task_by_client_request_id(request_id)
    if not task:
        raise HTTPException(status_code=404, detail="暂未找到对应的画布任务")
    return {
        "task_id": task.get("id"),
        "status": task.get("status") or "queued",
        "recovered": True,
    }

@app.get("/api/canvas-image-tasks/{task_id}")
async def get_canvas_image_task(task_id: str):
    with CANVAS_TASK_LOCK:
        task = dict(CANVAS_TASKS.get(task_id) or {})
    if not task:
        # 兼容多进程/服务刚重启时的短暂内存空窗；不要在这里清空当前进程
        # 的任务表，以免一个旧浏览器请求影响其它正在运行的任务。
        try:
            persisted = _read_canvas_task_store_entries().get(task_id)
        except (OSError, ValueError, TypeError):
            persisted = None
        if isinstance(persisted, dict):
            task = dict(persisted)
            with CANVAS_TASK_LOCK:
                CANVAS_TASKS.setdefault(task_id, dict(task))
    if not task:
        raise HTTPException(status_code=404, detail="未找到画布任务，可能是旧版本任务记录或任务已过期，请重新生成")
    return task

def _canvas_comfy_app_for_workflow(workflow_json: str = "", app_id: str = ""):
    """Resolve a canvas workflow to its app-library manifest when possible.

    Managed app-library workflows run on the isolated ComfyUI instance owned by
    ``COMFY_APPS``. Older canvas data may not have stored ``app_id``, so the
    workflow filename remains a safe fallback lookup key.
    """
    app_library = globals().get("COMFY_APPS")
    if not app_library:
        return None
    workflow_name = str(workflow_json or "").strip().replace("\\", "/")
    requested_id = str(app_id or "").strip()
    if not requested_id and not workflow_name.startswith("custom/"):
        return None

    def read_app(identity):
        try:
            item = app_library.read(identity)
        except (HTTPException, OSError, TypeError, ValueError):
            return None
        if not isinstance(item, dict):
            return None
        item_workflow = str(item.get("workflow") or "").strip().replace("\\", "/")
        if workflow_name and item_workflow != workflow_name:
            return None
        return item

    if requested_id:
        item = read_app(requested_id)
        if item:
            return item

    root = getattr(app_library, "root", None)
    if not root or not workflow_name:
        return None
    try:
        manifests = Path(root).glob("*/app.json")
    except (OSError, TypeError):
        return None
    for manifest in manifests:
        try:
            raw = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, TypeError, ValueError):
            continue
        if not isinstance(raw, dict):
            continue
        manifest_workflow = str(raw.get("workflow") or "").strip().replace("\\", "/")
        if manifest_workflow != workflow_name:
            continue
        identity = str(raw.get("id") or manifest.parent.name).strip()
        if identity:
            item = read_app(identity)
            if item:
                return item
    return None


def _prepare_canvas_comfy_payload(payload: GenerateRequest) -> GenerateRequest:
    """Pin app-library canvas runs to the verified local backend used for uploads."""
    item = _canvas_comfy_app_for_workflow(payload.workflow_json, payload.app_id)
    if not item:
        return payload
    app_library = globals().get("COMFY_APPS")
    backend, _ = app_library.backend(item, start=True)
    backend = str(backend or "").strip()
    if not re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", backend):
        raise RuntimeError("应用工作流没有可用的本机 ComfyUI 地址，无法运行画布工作流")
    updates = {"preferred_backend": backend, "local_only": True}
    if hasattr(payload, "model_copy"):
        return payload.model_copy(update=updates)
    return payload.copy(update=updates)


async def run_canvas_comfy_task(task_id: str, payload: GenerateRequest):
    update_canvas_task(task_id, {"status": "running", "started_at": time.time()})
    try:
        result = await asyncio.to_thread(generate, payload)
        if isinstance(result, dict) and result.get("error"):
            raise RuntimeError(str(result.get("error") or "ComfyUI 生成失败"))
        update_canvas_task(task_id, {
            "status": "succeeded",
            "result": result,
            "error": "",
        })
    except Exception as exc:
        detail = getattr(exc, "detail", None) or str(exc)
        status_code = getattr(exc, "status_code", 500)
        update_canvas_task(task_id, {
            "status": "failed",
            "error": str(detail),
            "status_code": status_code,
        })

@app.post("/api/canvas-comfy-tasks")
async def create_canvas_comfy_task(payload: GenerateRequest):
    # 应用库工作流的独立 ComfyUI 端口必须在入队前解析；否则异步任务
    # 只能看到默认 8188，最终会把“连接被拒绝”保存成失败结果。
    payload = await asyncio.to_thread(_prepare_canvas_comfy_payload, payload)
    task_id = f"canvas_comfy_{uuid.uuid4().hex}"
