@app.get("/api/agent-skills")
async def get_agent_skills(response: Response):
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    with AGENT_SKILLS_LOCK:
        registry = load_agent_skill_package_registry()
