@app.put("/api/agent-skills/{skill_id}")
async def update_agent_skill_legacy(skill_id: str, payload: AgentSkillLegacyRequest):
    """Keep the legacy editor contract while writing through the canonical store."""

    cleaned_id = agent_skill_id(skill_id)
    path = agent_skill_path(cleaned_id)
    with AGENT_SKILLS_LOCK:
        if not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="Skill 不存在")
        existing, _ = read_skill_text(path)
        has_frontmatter = bool(re.match(r"^\s*---\s*\r?\n", existing.lstrip("\ufeff")))
        document = render_skill_document(
            str(payload.name or "").strip() or cleaned_id,
            payload.description,
            payload.instructions,
            frontmatter=has_frontmatter,
        )
        write_skill_text(path, document)
        skill = load_agent_skill_record(cleaned_id)
    return {"skill": _agent_skill_public_record(skill)}

@app.delete("/api/agent-skills/{skill_id}")
async def delete_agent_skill_legacy(skill_id: str):
    cleaned_id = agent_skill_id(skill_id)
    path = agent_skill_path(cleaned_id)
    with AGENT_SKILLS_LOCK:
        if not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="Skill 不存在")
        os.remove(path)
    return {"ok": True}

@app.post("/api/agent-skills/upload")
async def upload_agent_skill_legacy(file: UploadFile = File(...)):
    raw = await file.read()
    if len(raw) > 1024 * 1024:
        raise HTTPException(status_code=400, detail="Skill 文件不能超过 1 MB")
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise HTTPException(status_code=400, detail="Skill 文件必须为 UTF-8 Markdown") from exc

    with AGENT_SKILLS_LOCK:
        os.makedirs(AGENT_SKILLS_DIR, exist_ok=True)
        base_id = agent_skill_slug(os.path.splitext(str(file.filename or "skill"))[0])
        skill_id = base_id
        suffix = 2
        packages = load_agent_skill_package_registry().get("packages", {})
        while os.path.exists(agent_skill_path(skill_id)) or skill_id in packages:
            skill_id = f"{base_id}-{suffix}"
            suffix += 1
        path = agent_skill_path(skill_id)
        write_skill_text(path, content)
        skill = load_agent_skill_record(skill_id)
    return {"skill": _agent_skill_public_record(skill)}

@app.post("/api/agent-skills/create")
async def create_agent_skill(payload: AgentSkillCreateRequest):
    name = str(payload.name or "").strip()
    description = str(payload.description or "").strip().replace("\r", " ").replace("\n", " ")
    instructions = str(payload.instructions or "").strip()
    if not name or not instructions:
        raise HTTPException(status_code=400, detail="Skill 名称和指令不能为空")
    with AGENT_SKILLS_LOCK:
        os.makedirs(AGENT_SKILLS_DIR, exist_ok=True)
        base_id = agent_skill_slug(name)
        skill_id = base_id
        suffix = 2
        while os.path.exists(agent_skill_path(skill_id)) or skill_id in load_agent_skill_package_registry().get("packages", {}):
            skill_id = f"{base_id}-{suffix}"
            suffix += 1
        path = agent_skill_path(skill_id)
        write_skill_text(
            path,
            render_skill_document(
                name,
                description,
                instructions,
                frontmatter=True,
            ),
        )
        skill = load_agent_skill_record(skill_id)
    return {"skill": _agent_skill_public_record(skill)}

