@app.get("/share/{share_id}")
async def enter_canvas_share(share_id: str, request: Request, token: str = ""):
    share = _canvas_share_by_token(share_id, token)
    if not share:
        raise HTTPException(status_code=404, detail="分享链接无效、已过期或已停止")
    canvas = load_canvas(str(share.get("canvas_id") or ""))
    kind = normalize_canvas_kind(canvas.get("kind"))
    page = "/static/smart-canvas.html" if kind == "smart" else "/static/canvas.html"
    query = urllib.parse.urlencode({
        "id": canvas.get("id") or share.get("canvas_id"),
        "project": canvas.get("project") or DEFAULT_PROJECT_ID,
        "shared": "1",
        # 保留 bearer 凭证，便于用户直接复制浏览器重定向后的地址；
        # 首次加载由中间件/分享会话接口换成 HttpOnly cookie。
        "share_id": share.get("id"),
        "token": token,
    })
    response = RedirectResponse(url=f"{page}?{query}", status_code=307)
    response.set_cookie(
        CANVAS_SHARE_COOKIE,
        f"{share.get('id')}.{token}",
        max_age=_share_remaining_seconds(share),
        httponly=True,
        samesite="lax",
        secure=request.url.scheme == "https" or str(request.headers.get("x-forwarded-proto") or "").lower() == "https",
        path="/",
    )
    response.headers["Cache-Control"] = "no-store"
    response.headers["Referrer-Policy"] = "no-referrer"
    return response


