@app.get("/api/commerce-analysis/agent/sessions/{session_id}/export")
async def commerce_analysis_agent_export(session_id: str, format: str = "json"):
    session = await asyncio.to_thread(_commerce_agent_get_session, session_id, True)
    if not session:
        raise HTTPException(status_code=404, detail="网页智能体会话不存在")
    export_format = str(format or "json").strip().lower()
    if export_format == "json":
        return session
    if export_format not in {"csv", "markdown", "md"}:
        raise HTTPException(status_code=400, detail="只支持 json、csv 或 markdown 导出")
    events = session.get("events") or []
    if export_format == "csv":
        buffer = StringIO()
        writer = csv.writer(buffer, lineterminator="\r\n")
        writer.writerow(["时间", "动作", "模块", "目标", "状态", "结果摘要"])
        for event in events:
            result = event.get("result") if isinstance(event.get("result"), dict) else {}
            writer.writerow([
                event.get("created_at") or "",
                event.get("action") or "",
                event.get("module") or "",
                event.get("target") or "",
                event.get("status") or "",
                json.dumps(result, ensure_ascii=False, separators=(",", ":"))[:2000],
            ])
        filename = f"商品分析智能体-{session_id[:12]}.csv"
        return Response(
            content=buffer.getvalue().encode("utf-8-sig"),
            media_type="text/csv; charset=utf-8",
            headers={"Content-Disposition": f"attachment; filename*=UTF-8''{urllib.parse.quote(filename)}"},
        )
    lines = [
        "# 商品分析智能体操作记录",
        "",
        f"- 会话：`{session_id}`",
        f"- 商品页：{session.get('url') or '未返回'}",
        f"- 状态：{session.get('status') or 'unknown'}",
        f"- 目标：{session.get('goal') or '未返回'}",
        "",
        "## 操作事件",
        "",
    ]
    for index, event in enumerate(events, 1):
        result = event.get("result") if isinstance(event.get("result"), dict) else {}
        summary = json.dumps(result, ensure_ascii=False, separators=(",", ":"))[:2000]
        lines.append(f"{index}. `{event.get('action') or ''}` / `{event.get('module') or ''}` / `{event.get('target') or ''}` — {event.get('status') or ''}")
        if summary and summary != "{}":
            lines.append(f"   - 结果：{summary}")
    filename = f"商品分析智能体-{session_id[:12]}.md"
    return Response(
        content="\n".join(lines).encode("utf-8"),
        media_type="text/markdown; charset=utf-8",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{urllib.parse.quote(filename)}"},
    )


