def _commerce_analysis_csv_value(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return str(value)


def _commerce_analysis_sku_export_price(value: Any) -> str:
    """按规格列表 CSV 的 ¥0.00 格式输出价格，不用商品当前价填充原价。"""
    raw = str(value or "").strip().replace(",", "")
    if not raw:
        return ""
    match = re.search(r"-?\d+(?:\.\d+)?", raw)
    if not match:
        return raw
    try:
        number = float(match.group(0))
        if number >= 1000 and re.fullmatch(r"\d+", match.group(0)):
            number /= 100
        return f"¥{number:.2f}"
    except (TypeError, ValueError):
        return raw


def _commerce_analysis_sku_export_specs(sku: Dict[str, Any], item: Dict[str, Any]) -> List[Dict[str, str]]:
    """把不同淘宝页面返回的规格表示统一成“名称:值”明细。"""
    group_names = [
        _clean_link_text(group.get("name") or group.get("title") or "", 100)
        for group in (sku.get("specs") or [])
        if isinstance(group, dict) and _clean_link_text(group.get("name") or group.get("title") or "", 100)
    ]
    raw_specs = item.get("specs")
    if isinstance(raw_specs, dict):
        raw_specs = [{"name": key, "value": value} for key, value in raw_specs.items()]
    pairs: List[Dict[str, str]] = []
    if isinstance(raw_specs, list):
        for raw_spec in raw_specs:
            if isinstance(raw_spec, dict):
                name = _clean_link_text(raw_spec.get("name") or raw_spec.get("propName") or raw_spec.get("label") or raw_spec.get("propertyName") or "", 100)
                value = _clean_link_text(raw_spec.get("value") or raw_spec.get("nameValue") or raw_spec.get("valueName") or raw_spec.get("text") or raw_spec.get("option") or "", 180)
            else:
                name, value = "", _clean_link_text(raw_spec, 180)
            if value:
                pairs.append({"name": name, "value": value})
    elif isinstance(raw_specs, str):
        for token in re.split(r"[;；|｜]+", raw_specs):
            token = _clean_link_text(token, 260)
            if not token:
                continue
            match = re.match(r"^([^:：;,，]+)\s*[:：]\s*(.+)$", token)
            pairs.append({"name": _clean_link_text(match.group(1), 100) if match else "", "value": _clean_link_text(match.group(2) if match else token, 180)})
    if not pairs:
        raw_text = _clean_link_text(item.get("specText") or item.get("propertyText") or "", 1000)
        for token in re.split(r"[;；|｜,，]+", raw_text):
            token = _clean_link_text(token, 220)
            if token:
                match = re.match(r"^([^:：;,，]+)\s*[:：]\s*(.+)$", token)
                pairs.append({"name": _clean_link_text(match.group(1), 100) if match else "", "value": _clean_link_text(match.group(2) if match else token, 180)})
    # 旧版初始化状态有时只返回 “颜色值, 尺码值”；用真实规格组名补齐，
    # 但不从尺寸表的肩宽/胸围等字段猜测可选尺码。
    expanded: List[Dict[str, str]] = []
    for pair in pairs:
        values = [value for value in re.split(r"\s*,\s*|\s*，\s*", pair["value"]) if value]
        if not pair["name"] and len(values) > 1:
            for value in values:
                expanded.append({"name": "", "value": value})
        else:
            expanded.append(pair)
    pairs = expanded
    for index, pair in enumerate(pairs):
        if not pair["name"] and index < len(group_names):
            pair["name"] = group_names[index]
    return [pair for pair in pairs if pair.get("value")]


def _commerce_analysis_sku_export_rows(sku: Dict[str, Any]) -> List[List[str]]:
    rows: List[List[str]] = []
    seen: set = set()
    for item in sku.get("items") or []:
        if not isinstance(item, dict):
            continue
        sku_id = _clean_link_text(item.get("id") or item.get("skuId") or item.get("sku_id") or "", 120)
        specs = _commerce_analysis_sku_export_specs(sku, item)
        if not sku_id or not specs:
            continue
        key = (sku_id, _clean_link_text(item.get("propPath") or item.get("prop_path") or "", 800), tuple((pair["name"], pair["value"]) for pair in specs))
        if key in seen:
            continue
        seen.add(key)
        values = [pair["value"] for pair in specs]
        sku_name = _clean_link_text(item.get("sku_name") or item.get("skuName") or item.get("name") or " ".join(values), 500)
        price = _commerce_analysis_sku_export_price(item.get("price") or item.get("salePrice") or item.get("currentPrice") or "")
        original = _commerce_analysis_sku_export_price(item.get("original_price") or item.get("originalPrice") or item.get("originPrice") or item.get("marketPrice") or "")
        promo = _commerce_analysis_sku_export_price(item.get("promo_price") or item.get("promoPrice") or item.get("promotionPrice") or item.get("discountPrice") or "") or price
        quantity = item.get("quantity")
        if quantity in (None, ""):
            quantity = item.get("stock") if re.fullmatch(r"\s*\d+(?:\.\d+)?\s*", str(item.get("stock") or "")) else ""
        quantity_text = _clean_link_text(quantity, 80)
        stock_status = _clean_link_text(item.get("stock_status") or item.get("stockStatus") or "", 40)
        if not stock_status:
            numeric_quantity = re.fullmatch(r"\s*\d+(?:\.\d+)?\s*", quantity_text or "")
            stock_status = "有货" if numeric_quantity and float(quantity_text) > 0 else "缺货" if numeric_quantity else _clean_link_text(item.get("stock") or "", 40)
        image = _clean_link_text(item.get("image") or item.get("imageUrl") or item.get("pic") or item.get("picUrl") or "", 2000)
        detail = "; ".join(f"{pair['name']}:{pair['value']}" if pair["name"] else pair["value"] for pair in specs)
        rows.append([
            str(len(rows) + 1), sku_id, sku_name, price, original, promo,
            quantity_text, stock_status, image, detail,
        ])
    return rows[:500]


def _commerce_analysis_verification_payload(result: Dict[str, Any], job_id: str = "") -> Dict[str, Any]:
    """Return a download-safe audit manifest; never include raw response bodies."""
    result = _commerce_analysis_attach_contract(
        result if isinstance(result, dict) else {},
        job_id=job_id,
        mode=str((result or {}).get("source") or "import") if isinstance(result, dict) else "import",
    )
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    collection = result.get("collection") if isinstance(result.get("collection"), dict) else {}
    product_id = result.get("productId") or collection.get("productId") or product.get("id") or ""
    normalized_url = result.get("normalizedUrl") or collection.get("normalizedUrl") or _commerce_analysis_normalized_url(
        result.get("finalUrl") or result.get("originalUrl") or "",
        str(product_id or ""),
    )
    source_steps = collection.get("sourceSteps") if isinstance(collection.get("sourceSteps"), list) else []
    modules = []
    module_labels = {
        "product": "商品信息", "images": "主图", "detail": "详情页", "reviews": "用户评价",
        "questions": "问大家", "sku": "SKU / 规格", "videos": "主图视频",
    }
    arrays = {"reviews": result.get("reviews") or [], "questions": result.get("questions") or []}
    for key in ("product", "images", "detail", "reviews", "questions", "sku", "videos"):
        state = result.get("moduleStatus", {}).get(key) if isinstance(result.get("moduleStatus"), dict) else {}
        state = state if isinstance(state, dict) else {}
        sample_count = _commerce_analysis_safe_int(state.get("sampleCount"))
        real_sample_count = _commerce_analysis_safe_int(state.get("realResponseSampleCount"))
        visible_sample_count = len(arrays.get(key, [])) if key in arrays else sample_count
        modules.append({
            "module": key,
            "label": module_labels.get(key, key),
            "status": state.get("status") or "missing",
            "totalCount": state.get("totalCount"),
            "totalCountSource": state.get("totalCountSource") or state.get("source") or "未返回",
            "sampleCount": sample_count,
            "visibleSampleCount": visible_sample_count,
            "realResponseSampleCount": real_sample_count,
            "responseCount": _commerce_analysis_safe_int(state.get("responseCount")),
            "source": state.get("source") or collection.get("source") or result.get("source") or "",
            "sourceStepIds": list(state.get("sourceStepIds") or [])[:30],
            "sourceSteps": list(state.get("sourceSteps") or [])[:30],
            "evidenceIds": list(state.get("evidenceIds") or [])[:30],
            "reason": state.get("reason") or "未返回该模块；未使用演示数据",
            "productId": product_id,
            "normalizedUrl": normalized_url,
            "collectedAt": result.get("collectedAt") or collection.get("collectedAt") or collection.get("receivedAt") or "",
        })
    review_state = next(item for item in modules if item["module"] == "reviews")
    question_state = next(item for item in modules if item["module"] == "questions")
    identity_check = collection.get("identityCheck") if isinstance(collection.get("identityCheck"), dict) else {}
    return {
        "schemaVersion": 1,
        "kind": "commerce-analysis-verification",
        "jobId": job_id or result.get("jobId") or "",
        "status": result.get("status") or "unknown",
        "message": result.get("message") or "",
        "productId": product_id,
        "productTitle": product.get("title") or "",
        "normalizedUrl": normalized_url,
        "collectedAt": result.get("collectedAt") or collection.get("collectedAt") or collection.get("receivedAt") or "",
        "identityCheck": identity_check,
        "modules": modules,
        "sourceSteps": source_steps[:80],
        "privacy": collection.get("privacy") or {"cookiesSaved": False, "tokensSaved": False, "rawResponsesSaved": False},
        "checks": {
            "productIdentityBound": not identity_check or identity_check.get("status") != "mismatch",
            "reviews": {
                "pageTotalCount": review_state.get("totalCount"),
                "normalizedSampleCount": review_state.get("sampleCount", 0),
                "realResponseSampleCount": review_state.get("realResponseSampleCount", 0),
                "responseCount": review_state.get("responseCount", 0),
                "sampleCountMatchesDisplayed": review_state.get("visibleSampleCount", 0) == review_state.get("sampleCount", 0),
            },
            "questions": {
                "pageTotalCount": question_state.get("totalCount"),
                "normalizedSampleCount": question_state.get("sampleCount", 0),
                "realResponseSampleCount": question_state.get("realResponseSampleCount", 0),
                "responseCount": question_state.get("responseCount", 0),
                "sampleCountMatchesDisplayed": question_state.get("visibleSampleCount", 0) == question_state.get("sampleCount", 0),
            },
        },
        "note": "核验文件只包含商品身份、模块状态、计数、证据定位和来源步骤；不包含 Cookie、Token 或原始响应。",
    }


def _commerce_analysis_verification_csv(payload: Dict[str, Any]) -> str:
    headers = [
        "任务ID", "商品ID", "规范化链接", "采集时间", "模块", "模块状态", "页面显示总量",
        "总量来源", "规范化样本数", "真实响应样本数", "真实响应数", "来源", "来源步骤", "证据ID", "缺失原因",
    ]
    rows = []
    for item in payload.get("modules") or []:
        if not isinstance(item, dict):
            continue
        step_ids = item.get("sourceStepIds") or []
        rows.append([
            payload.get("jobId", ""), payload.get("productId", ""), payload.get("normalizedUrl", ""), payload.get("collectedAt", ""),
            item.get("label") or item.get("module") or "", item.get("status") or "", item.get("totalCount") if item.get("totalCount") is not None else "",
            item.get("totalCountSource") or "", item.get("sampleCount", 0), item.get("realResponseSampleCount", 0), item.get("responseCount", 0),
            item.get("source") or "", " | ".join(str(value) for value in step_ids), " | ".join(str(value) for value in (item.get("evidenceIds") or [])), item.get("reason") or "",
        ])
    buffer = StringIO()
    writer = csv.writer(buffer, lineterminator="\r\n")
    writer.writerow(headers)
    writer.writerows(rows)
    return "\ufeff" + buffer.getvalue()


def _commerce_analysis_report_from_result(result: Dict[str, Any], kind: str) -> Dict[str, Any]:
    if kind == "operations":
        operations = result.get("operations") if isinstance(result.get("operations"), dict) else {}
        for item in operations.get("items") or []:
            if isinstance(item, dict) and isinstance(item.get("report"), dict):
                return item["report"]
        report = result.get("operationsReport")
        return report if isinstance(report, dict) else {}
    people = result.get("peopleStructure") or result.get("audience") or result.get("people") or {}
    if isinstance(people, dict):
        return people
    return {}


def _commerce_analysis_report_filename_part(value: Any, fallback: str) -> str:
    raw = _clean_link_text(value, 120)
    raw = re.sub(r"[\\/:*?\"<>|\s]+", "_", raw).strip("._")
    return raw or fallback


def _commerce_analysis_report_flow_csv_rows(report: Dict[str, Any], group: str) -> List[List[str]]:
    flow = [item for item in (report.get("flow") or []) if isinstance(item, dict)]
    selected = []
    for item in flow:
        item_group = str(item.get("group") or "unknown").lower()
        if item_group == group or (item_group == "unknown" and _commerce_analysis_report_channel_group(item.get("channelType")) == group):
            selected.append(item)
    total_clicks = sum(_commerce_analysis_report_number(item.get("clicks")) or 0 for item in flow)
    total_paid = sum(_commerce_analysis_report_number(item.get("paidCount")) or 0 for item in flow)
    rows: List[List[str]] = []
    for item in selected:
        clicks = _commerce_analysis_report_number(item.get("clicks"))
        paid_count = _commerce_analysis_report_number(item.get("paidCount"))
        rows.append([
            _commerce_analysis_report_channel_label(item.get("channelType")),
            _commerce_analysis_report_cell(item.get("name"), 500),
            _commerce_analysis_report_count(item.get("clicks")),
            _commerce_analysis_report_percent(item.get("clickShare"), clicks / total_clicks if clicks is not None and total_clicks > 0 else None),
            _commerce_analysis_report_count(item.get("paidCount")),
            _commerce_analysis_report_percent(item.get("paidShare"), paid_count / total_paid if paid_count is not None and total_paid > 0 else None),
            _commerce_analysis_report_percent(item.get("cartRate")),
            _commerce_analysis_report_percent(item.get("payRate")),
        ])
    return rows


def _commerce_analysis_operations_report_matrix(result: Dict[str, Any]) -> Tuple[List[List[str]], str]:
    report = _commerce_analysis_report_from_result(result, "operations")
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    product_name = _commerce_analysis_report_cell(report.get("productName") or product.get("title"), 240)
    product_id = _commerce_analysis_report_cell(report.get("productId") or result.get("productId") or product.get("id"), 120)
    period_label = _commerce_analysis_report_cell(report.get("periodLabel") or "最近30天", 40)
    time_range = _commerce_analysis_report_cell(report.get("timeRange"), 120)
    data_date = _commerce_analysis_report_cell(report.get("dataDate"), 40)
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    summary_value = lambda field: _commerce_analysis_report_cell(summary.get(field), 120)
    matrix: List[List[str]] = [
        [f"商品运营数据 - {period_label}"],
        ["商品名", product_name, "商品ID", product_id, "统计时间", period_label, "时间", time_range, "数据日期", data_date],
        [],
        ["1. 经营汇总"],
        ["统计时间", "时间", "曝光次数", "点击率", "访客数", "加购人数", "加购率", "支付转化率", "支付买家数"],
        [
            period_label,
            time_range,
            _commerce_analysis_report_count(summary_value("impressions")),
            _commerce_analysis_report_percent(summary_value("clickRate")),
            _commerce_analysis_report_count(summary_value("visitors")),
            _commerce_analysis_report_count(summary_value("cartUsers")),
            _commerce_analysis_report_percent(summary_value("cartRate")),
            _commerce_analysis_report_percent(summary_value("payRate")),
            _commerce_analysis_report_count(summary_value("paidBuyers")),
        ],
        [],
        ["2. 流量来源"],
        [],
        ["自然流量"],
        ["来源类型", "分析对象", "点击量", "点击量占比", "成交笔数", "成交笔数占比", "加购率", "支付转化率"],
    ]
    organic_rows = _commerce_analysis_report_flow_csv_rows(report, "organic")
    matrix.extend(organic_rows or [["无自然流量来源数据"]])
    matrix.extend([
        [],
        ["付费流量"],
        ["来源类型", "分析对象", "点击量", "点击量占比", "成交笔数", "成交笔数占比", "加购率", "支付转化率"],
    ])
    paid_rows = _commerce_analysis_report_flow_csv_rows(report, "paid")
    matrix.extend(paid_rows or [["无付费流量来源数据"]])
    matrix.extend([
        [],
        ["3. 推广花费细分"],
        ["说明", _commerce_analysis_report_cell(report.get("promotionNote") or "当前可见页面/官方导出未返回推广花费字段，花费列留空。", 300)],
        ["推广类型", "推广渠道", "点击量", "推广点击占比", "成交笔数", "推广成交占比", "加购率", "支付转化率", "花费"],
    ])
    promotion = report.get("promotion") if isinstance(report.get("promotion"), list) else []
    promotion_report = dict(report)
    promotion_report["flow"] = promotion
    promotion_rows = _commerce_analysis_report_flow_csv_rows(promotion_report, "paid")
    # 推广明细的分母只取付费流量；最后一列只有在官方
    # 页面明确返回花费时才填入，不从其它指标推算。
    for index, row in enumerate(promotion_rows):
        item = promotion[index] if index < len(promotion) and isinstance(promotion[index], dict) else {}
        row[1] = _commerce_analysis_report_cell(item.get("name"), 500)
        row.append(_commerce_analysis_report_cell(item.get("spend"), 80))
    matrix.extend(promotion_rows or [["无推广来源数据"]])
    raw_rows = report.get("rawRows") if isinstance(report.get("rawRows"), list) else []
    if raw_rows:
        matrix.extend([[], ["页面可见数据（未匹配标准字段）"], *raw_rows[:300]])
    width = max(10, max((len(row) for row in matrix), default=1))
    matrix = [list(row)[:width] + [""] * max(0, width - len(row)) for row in matrix]
    filename = f"商品运营数据_{period_label}_{_commerce_analysis_report_filename_part(product_id, 'report')}.csv"
    return matrix, filename


def _commerce_analysis_people_report_matrix(result: Dict[str, Any]) -> Tuple[List[List[str]], str]:
    report = _commerce_analysis_report_from_result(result, "people")
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    product_name = _commerce_analysis_report_cell(report.get("productName") or product.get("title"), 240)
    product_id = _commerce_analysis_report_cell(report.get("productId") or result.get("productId") or product.get("id"), 120)
    period_label = _commerce_analysis_report_cell(report.get("periodLabel") or "最近30天", 40)
    time_range = _commerce_analysis_report_cell(report.get("timeRange"), 120)
    data_date = _commerce_analysis_report_cell(report.get("dataDate"), 40)
    matrix: List[List[str]] = [
        [f"商品人群结构数据 - {period_label}"],
        ["商品名", product_name, "商品ID", product_id, "统计时间", period_label, "时间", time_range, "数据日期", data_date],
        [" "],
    ]
    groups = report.get("groups") if isinstance(report.get("groups"), list) else []
    if not groups and isinstance(report.get("items"), list) and report.get("items"):
        groups = [{"tagName": "页面可见人群", "rows": report.get("items")}]
    for index, group in enumerate(groups):
        if index:
            matrix.append([" "])
        tag_name = _commerce_analysis_report_cell(group.get("tagName") or f"人群维度{index + 1}", 160) if isinstance(group, dict) else f"人群维度{index + 1}"
        matrix.extend([[f"{index + 1}. {tag_name}"], ["选项名称", "人数", "占比"]])
        values = group.get("rows") if isinstance(group, dict) and isinstance(group.get("rows"), list) else []
        for item in values[:1000]:
            if not isinstance(item, dict):
                continue
            matrix.append([
                "未知" if str(item.get("optionName") or "") == "unknown" else _commerce_analysis_report_cell(item.get("optionName"), 180),
                _commerce_analysis_report_count(item.get("optionNum")),
                _commerce_analysis_report_percent(item.get("rate")),
            ])
    raw_rows = report.get("rawRows") if isinstance(report.get("rawRows"), list) else []
    if raw_rows:
        matrix.extend([[" "], ["页面可见数据（未匹配标准字段）"], *raw_rows[:300]])
    width = max(10, max((len(row) for row in matrix), default=1))
    matrix = [list(row)[:width] + [""] * max(0, width - len(row)) for row in matrix]
    filename = f"商品人群结构数据_{period_label}_{_commerce_analysis_report_filename_part(product_id, 'report')}.csv"
    return matrix, filename


def _commerce_analysis_resource_rows(result: Dict[str, Any], resource_id: str) -> Tuple[List[str], List[List[str]]]:
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    if resource_id == "product":
        headers = ["字段", "值", "来源"]
        parameters = product.get("parameters") if isinstance(product.get("parameters"), dict) else {}
        core_parameters = _commerce_analysis_parameter_rows(product.get("coreParams") or parameters.get("core"))
        detail_parameters = _commerce_analysis_parameter_rows(product.get("detailParams") or parameters.get("detail"))
        product_title = product.get("title") or ""
        product_price = product.get("priceRange") or product.get("price") or ""
        product_sales = product.get("sales") or (result.get("metrics", {}).get("salesSignal") if isinstance(result.get("metrics"), dict) else "")
        product_reviews = product.get("reviewCount") or (result.get("metrics", {}).get("reviewCount") if isinstance(result.get("metrics"), dict) else "")
        fields = (
            ("商品ID", product.get("id") or product.get("itemId") or ""),
            ("商品名称", product_title),
            ("商品类目", product.get("category") or product.get("categoryPath") or ""),
            ("商品价格", product_price),
            ("商品销量", product_sales),
            ("评价数量", product_reviews),
            ("标题", product_title),
            ("类目", product.get("category") or product.get("categoryPath") or ""),
            ("店铺", product.get("store") or ""),
            ("价格", product_price),
            ("销量", product_sales),
            ("评价数", product_reviews),
            ("商品链接", result.get("finalUrl") or result.get("originalUrl") or ""),
        )
        rows = [[field, _commerce_analysis_csv_value(value), "商品页可见信息"] for field, value in fields if value not in (None, "")]
        rows.extend([["核心参数", f"{row['value']}：{row['name']}", "商品页参数信息"] for row in core_parameters])
        rows.extend([["详细参数", f"{row['name']}：{row['value']}", "商品页参数信息"] for row in detail_parameters])
        return headers, rows
    if resource_id == "images":
        values = result.get("mainImages") or result.get("images") or []
        return ["序号", "主图URL", "来源"], [[str(index), _commerce_analysis_csv_value(value), "商品画廊"] for index, value in enumerate(values, 1) if value]
    if resource_id in {"detail", "detail_more"}:
        detail = result.get("detail") if isinstance(result.get("detail"), dict) else {}
        rows = [[str(index), _commerce_analysis_csv_value(value), "详情页图片"] for index, value in enumerate(detail.get("images") or result.get("detailImages") or [], 1) if value]
        for index, section in enumerate(detail.get("sections") or [], 1):
            if isinstance(section, dict) and (section.get("text") or section.get("title")):
                rows.append([f"文字-{index}", _commerce_analysis_csv_value(section.get("text") or ""), _commerce_analysis_csv_value(section.get("title") or "详情段落")])
        if detail.get("text") and not rows:
            rows.append(["文字-1", _commerce_analysis_csv_value(detail.get("text")), "详情页可见文字"])
        return ["序号", "内容", "来源"], rows
    if resource_id == "sku_images":
        sku = result.get("sku") if isinstance(result.get("sku"), dict) else {}
        rows = []
        for index, item in enumerate(sku.get("items") or [], 1):
            if not isinstance(item, dict):
                continue
            image = item.get("image") or item.get("imageUrl") or item.get("pic") or ""
            if image:
                rows.append([str(index), _commerce_analysis_csv_value(image), _commerce_analysis_csv_value(item.get("specs") or item.get("id") or "")])
        for spec in sku.get("specs") or []:
            if not isinstance(spec, dict):
                continue
            for value in spec.get("values") or []:
                if not isinstance(value, dict):
                    continue
                image = value.get("image") or value.get("imageUrl") or value.get("pic") or ""
                if image:
                    rows.append([str(len(rows) + 1), _commerce_analysis_csv_value(image), _commerce_analysis_csv_value(value.get("name") or spec.get("name") or "")])
        return ["序号", "SKU图URL", "规格或SKU"], rows
    if resource_id == "sku_list":
        sku = result.get("sku") if isinstance(result.get("sku"), dict) else {}
        return ["序号", "SKU ID", "SKU名称", "价格", "原价", "促销价", "库存", "库存状态", "图片", "规格明细"], _commerce_analysis_sku_export_rows(sku)
    if resource_id == "sku":
        sku = result.get("sku") if isinstance(result.get("sku"), dict) else {}
        rows = []
        for index, spec in enumerate(sku.get("specs") or [], 1):
            if isinstance(spec, dict):
                rows.append(["规格", _commerce_analysis_csv_value(spec.get("name") or spec.get("title") or f"规格{index}"), _commerce_analysis_csv_value(spec.get("values") or spec.get("options") or [])])
            else:
                rows.append(["规格", str(index), _commerce_analysis_csv_value(spec)])
        for index, item in enumerate(sku.get("items") or [], 1):
            rows.append(["SKU组合", str(index), _commerce_analysis_csv_value(item)])
        if not rows and sku.get("text"):
            rows.append(["规格文字", "", _commerce_analysis_csv_value(sku.get("text"))])
        return ["类型", "名称/序号", "选项或内容"], rows
    if resource_id == "reviews":
        review_state = result.get("moduleStatus", {}).get("reviews") if isinstance(result.get("moduleStatus"), dict) else {}
        review_state = review_state if isinstance(review_state, dict) else {}
        audit_product_id = result.get("productId") or (product.get("id") if isinstance(product, dict) else "") or ""
        audit_url = result.get("normalizedUrl") or (result.get("collection", {}).get("normalizedUrl") if isinstance(result.get("collection"), dict) else "") or ""
        audit_time = result.get("collectedAt") or (result.get("collection", {}).get("collectedAt") if isinstance(result.get("collection"), dict) else "") or ""
        audit_source = review_state.get("source") or result.get("source") or ""
        audit_steps = " | ".join(str(item) for item in (review_state.get("sourceStepIds") or []))
        rows = []
        for index, review in enumerate(result.get("reviews") or [], 1):
            if isinstance(review, dict):
                rows.append([
                    _commerce_analysis_csv_value(audit_product_id),
                    _commerce_analysis_csv_value(audit_url),
                    _commerce_analysis_csv_value(audit_time),
                    "用户评价",
                    _commerce_analysis_csv_value(audit_source),
                    _commerce_analysis_csv_value(audit_steps),
                    _commerce_analysis_csv_value(review.get("evidenceId") or f"reviews:{index}"),
                    str(index),
                    _commerce_analysis_csv_value(review.get("content") or review.get("text") or ""),
                    _commerce_analysis_csv_value(review.get("rating") or ""),
                    _commerce_analysis_csv_value(review.get("author") or review.get("user") or ""),
                    _commerce_analysis_csv_value(review.get("date") or review.get("time") or ""),
                    _commerce_analysis_csv_value(review.get("images") or review.get("hasImages") or ""),
                ])
            elif review:
                rows.append([audit_product_id, audit_url, audit_time, "用户评价", audit_source, audit_steps, f"reviews:{index}", str(index), str(review), "", "", "", ""])
        return ["商品ID", "规范化链接", "采集时间", "模块", "来源", "来源步骤", "证据ID", "序号", "评价内容", "评分", "用户", "时间", "图片/带图"], rows
    if resource_id == "questions":
        question_state = result.get("moduleStatus", {}).get("questions") if isinstance(result.get("moduleStatus"), dict) else {}
        question_state = question_state if isinstance(question_state, dict) else {}
        audit_product_id = result.get("productId") or (product.get("id") if isinstance(product, dict) else "") or ""
        audit_url = result.get("normalizedUrl") or (result.get("collection", {}).get("normalizedUrl") if isinstance(result.get("collection"), dict) else "") or ""
        audit_time = result.get("collectedAt") or (result.get("collection", {}).get("collectedAt") if isinstance(result.get("collection"), dict) else "") or ""
        audit_source = question_state.get("source") or result.get("source") or ""
        audit_steps = " | ".join(str(item) for item in (question_state.get("sourceStepIds") or []))
        rows = []
        for index, question in enumerate(result.get("questions") or [], 1):
            if isinstance(question, dict):
                rows.append([
                    _commerce_analysis_csv_value(audit_product_id),
                    _commerce_analysis_csv_value(audit_url),
                    _commerce_analysis_csv_value(audit_time),
                    "问大家",
                    _commerce_analysis_csv_value(audit_source),
                    _commerce_analysis_csv_value(audit_steps),
                    _commerce_analysis_csv_value(question.get("evidenceId") or f"questions:{index}"),
                    str(index),
                    _commerce_analysis_csv_value(question.get("question") or question.get("content") or question.get("text") or ""),
                    _commerce_analysis_csv_value(question.get("answer") or question.get("answers") or ""),
                    _commerce_analysis_csv_value(question.get("author") or question.get("user") or ""),
                    _commerce_analysis_csv_value(question.get("date") or question.get("time") or ""),
                ])
            elif question:
                rows.append([audit_product_id, audit_url, audit_time, "问大家", audit_source, audit_steps, f"questions:{index}", str(index), str(question), "", "", ""])
        return ["商品ID", "规范化链接", "采集时间", "模块", "来源", "来源步骤", "证据ID", "序号", "问题", "回答", "用户", "时间"], rows
    if resource_id == "videos":
        rows = []
        for index, video in enumerate(result.get("videos") or [], 1):
            if isinstance(video, dict):
                rows.append([str(index), _commerce_analysis_csv_value(video.get("url") or video.get("src") or ""), _commerce_analysis_csv_value(video.get("type") or "video"), _commerce_analysis_csv_value(video.get("source") or "visible-page")])
            elif video:
                rows.append([str(index), str(video), "video", "visible-page"])
        return ["序号", "视频URL", "类型", "来源"], rows
    if resource_id == "operations":
        operations = result.get("operations") if isinstance(result.get("operations"), dict) else {}
        rows = []
        for index, item in enumerate(operations.get("items") or [], 1):
            if isinstance(item, dict):
                rows.append([str(index), _commerce_analysis_csv_value(item.get("title") or item.get("name") or ""), _commerce_analysis_csv_value(item.get("text") or item.get("content") or ""), _commerce_analysis_csv_value(item.get("metrics") or item.get("value") or ""), _commerce_analysis_csv_value(item.get("url") or ""), _commerce_analysis_csv_value(item.get("capturedAt") or operations.get("capturedAt") or "")])
            elif item:
                rows.append([str(index), "", str(item), "", "", _commerce_analysis_csv_value(operations.get("capturedAt") or "")])
        return ["序号", "标题", "内容", "指标", "链接", "采集时间"], rows
    if resource_id == "people":
        people = result.get("peopleStructure") or result.get("audience") or result.get("people") or []
        items = people if isinstance(people, list) else people.get("items") if isinstance(people, dict) and isinstance(people.get("items"), list) else ([people] if isinstance(people, dict) and people else [])
        rows = []
        for index, item in enumerate(items, 1):
            if isinstance(item, dict):
                rows.append([
                    str(index),
                    _commerce_analysis_csv_value(item.get("name") or item.get("label") or item.get("dimension") or ""),
                    _commerce_analysis_csv_value(item.get("value") or item.get("content") or item.get("text") or ""),
                    _commerce_analysis_csv_value(item.get("ratio") or item.get("percent") or item.get("metrics") or ""),
                ])
            elif item not in (None, ""):
                rows.append([str(index), "", _commerce_analysis_csv_value(item), ""])
        return ["序号", "人群维度", "内容", "占比/指标"], rows
    return [], []


def _commerce_analysis_product_text(result: Dict[str, Any]) -> str:
    """生成商品信息.txt，同时复用结构化快照中的真实字段。"""
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    title = _clean_link_text(product.get("title"), 240)
    title = re.sub(r"\s*[-－—]\s*(?:淘宝网|天猫)\s*$", "", title, flags=re.IGNORECASE).strip()
    product_id = _clean_link_text(product.get("id") or product.get("itemId") or result.get("productId"), 120)
    category = _clean_link_text(product.get("category") or product.get("categoryPath"), 240)
    price = _clean_link_text(product.get("priceRange") or product.get("price"), 120)
    if price and not re.search(r"[¥￥]", price):
        numbers = re.findall(r"\d+(?:\.\d+)?", price)
        if len(numbers) >= 2:
            price = f"¥{float(numbers[0]):.2f}～¥{float(numbers[-1]):.2f}"
        elif numbers:
            price = f"¥{float(numbers[0]):.2f}"
    sales = _clean_link_text(product.get("sales") or (result.get("metrics", {}).get("salesSignal") if isinstance(result.get("metrics"), dict) else ""), 80)
    if sales and not re.search(r"已售|销量", sales):
        sales = f"已售 {sales}"
    review_count = _clean_link_text(product.get("reviewCount") or (result.get("metrics", {}).get("reviewCount") if isinstance(result.get("metrics"), dict) else ""), 80)
    parameters = product.get("parameters") if isinstance(product.get("parameters"), dict) else {}
    core = _commerce_analysis_parameter_rows(product.get("coreParams") or parameters.get("core"))
    detail = _commerce_analysis_parameter_rows(product.get("detailParams") or parameters.get("detail"))
    lines = [
        "商品信息",
        "========",
        "",
        f"商品名称：{title}",
        f"商品ID：{product_id}",
        f"商品类目：{category}",
        f"商品价格：{price}",
        f"商品销量：{sales}",
        f"评价数量：{review_count}",
        "",
        "【核心参数】",
        "",
    ]
    lines.extend(f"{row['value']}：{row['name']}" for row in core)
    lines.extend(["", "【详细参数】", ""])
    lines.extend(f"{row['name']}：{row['value']}" for row in detail)
    return "\n".join(lines).rstrip() + "\n"


COMMERCE_ANALYSIS_MEDIA_RESOURCE_IDS = {"images", "detail", "detail_more", "sku_images", "videos"}


def _commerce_analysis_media_value_url(value: Any) -> str:
    if isinstance(value, dict):
        for key in ("url", "src", "imageUrl", "image", "videoUrl", "contentUrl", "thumbnailUrl", "pic", "picUrl", "skuImage", "skuImageUrl"):
            candidate = value.get(key)
            if candidate:
                return _commerce_agent_media_url(candidate)
        return ""
    return _commerce_agent_media_url(value)


def _commerce_analysis_sku_media_label(value: Any, group_name: str = "") -> str:
    if not isinstance(value, dict):
        return _clean_link_text(value, 220)
    specs = value.get("specs")
    if isinstance(specs, list):
        parts = []
        for item in specs:
            if isinstance(item, dict):
                part = item.get("value") or item.get("name") or ""
            else:
                part = item
            part = _clean_link_text(part, 180)
            if part and part not in {"…", "..."}:
                parts.append(part)
        if parts:
            return "+".join(dict.fromkeys(parts))
    for key in ("skuName", "specText", "propertyText", "name", "title"):
        label = _clean_link_text(value.get(key), 220)
        if label and label not in {"…", "..."}:
            return label
    return _clean_link_text(group_name, 120)


def _commerce_analysis_resource_media_items(result: Dict[str, Any], resource_id: str) -> List[Dict[str, str]]:
    values: List[Tuple[Any, str]] = []
    if resource_id == "images":
        values = [(value, "") for value in (result.get("mainImages") or result.get("images") or [])]
    elif resource_id in {"detail", "detail_more"}:
        detail = result.get("detail") if isinstance(result.get("detail"), dict) else {}
        values = [(value, "") for value in (detail.get("images") or result.get("detailImages") or [])]
    elif resource_id == "sku_images":
        sku = result.get("sku") if isinstance(result.get("sku"), dict) else {}
        values = [
            (item, _commerce_analysis_sku_media_label(item))
            for item in (sku.get("items") or [])
            if isinstance(item, dict) and (item.get("image") or item.get("imageUrl") or item.get("pic") or item.get("picUrl") or item.get("skuImage") or item.get("skuImageUrl"))
        ]
        for spec in sku.get("specs") or []:
            if not isinstance(spec, dict):
                continue
            values.extend(
                (value, _commerce_analysis_sku_media_label(value, spec.get("name") or "")) for value in (spec.get("values") or [])
                if isinstance(value, dict) and (value.get("image") or value.get("imageUrl") or value.get("pic") or value.get("picUrl") or value.get("skuImage") or value.get("skuImageUrl"))
            )
    elif resource_id == "videos":
        values = [(value, "") for value in (result.get("videos") or result.get("videoUrls") or [])]
    seen = set()
    items: List[Dict[str, str]] = []
    for value, label in values if isinstance(values, list) else [(values, "")]:
        url = _commerce_analysis_media_value_url(value)
        if (
            not url
            or url in seen
            or resource_id in {"detail", "detail_more"}
            and _commerce_analysis_detail_url_is_platform_asset(url)
        ):
            continue
        seen.add(url)
        items.append({"url": url, "label": _clean_link_text(label, 220)})
    return items


def _commerce_analysis_media_filename(url: str, resource_id: str, index: int, content_type: str = "", label: str = "") -> str:
    prefixes = {
        "images": "主图",
        "detail_more": "详情图",
        "sku_images": "SKU图",
        "videos": "商品视频",
    }
    fallback = f"{prefixes.get(resource_id, resource_id)}-{index:03d}"
    name = filename_from_media_url(url, fallback)
    if resource_id == "sku_images" and label:
        extension = os.path.splitext(name)[1].lower()
        if not extension:
            extension = mimetypes.guess_extension(str(content_type or "").split(";", 1)[0].strip().lower()) or ".jpg"
        name = f"SKU图-{sanitize_export_filename(label, f'SKU图-{index:03d}')}{extension}"
    extension = os.path.splitext(name)[1].lower()
    allowed_extensions = {
        ".jpg", ".jpeg", ".png", ".webp", ".gif", ".avif", ".bmp", ".tif", ".tiff",
        ".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv", ".m3u8", ".ts", ".bin",
    }
    if extension not in allowed_extensions:
        guessed = mimetypes.guess_extension(str(content_type or "").split(";", 1)[0].strip().lower()) or ".bin"
        name = f"{os.path.splitext(name)[0]}{guessed}"
    return sanitize_export_filename(name, fallback + ".bin")


def _commerce_analysis_unique_media_filename(name: str, used: set) -> str:
    safe = sanitize_export_filename(name, "resource.bin")
    stem, extension = os.path.splitext(safe)
    candidate = safe
    index = 2
    while candidate in used:
        candidate = f"{stem}-{index}{extension}"
        index += 1
    used.add(candidate)
    return candidate


def _commerce_analysis_download_stem(result: Dict[str, Any], job_id: str) -> str:
    product = result.get("product") if isinstance(result.get("product"), dict) else {}
    title = sanitize_export_filename(str(product.get("title") or "商品分析").strip(), "商品分析")
    title = os.path.splitext(title)[0][:60] or "商品分析"
    return f"商品分析-{title}-{str(job_id or '')[:12]}"


def _commerce_analysis_detail_url_is_noise(url: str) -> bool:
    text = str(url or "").lower()
    if not text:
        return True
    return bool(
        re.search(
            r"(?:s\.gif|(?:^|[-_/])(?:avatar|headimg|favicon|logo|icon|qrcode|qr-code|loading|placeholder|recommend|guess|rate|review|comment)(?:[-_.?/]|$)|(?:[-_/])(?:2|30|80)x(?:2|30|80)(?:[-_.?/]|$))",
            text,
            re.IGNORECASE,
        )
    )


def _commerce_analysis_detail_url_is_platform_asset(url: str) -> bool:
    """Identify Taobao platform assets that may sit after the seller detail."""
    text = str(url or "").lower()
    return bool(re.search(r"(?:^|[-_/])tps(?:[-_.?/]|$)", text))


def _commerce_analysis_detail_asset_keys(url: str) -> set:
    base = str(url or "").split("?", 1)[0].lower()
    tokens = set(re.findall(r"o1cn[0-9a-z]+", base, re.IGNORECASE))
    return tokens or {base}


def _commerce_analysis_detail_long_items(result: Dict[str, Any]) -> List[Dict[str, str]]:
    """Return detail candidates without gallery/review chrome images."""
    main_keys = set()
    for value in result.get("mainImages") or result.get("images") or []:
        url = _commerce_analysis_media_value_url(value)
        if url:
            main_keys.update(_commerce_analysis_detail_asset_keys(url))
    items = []
    seen = set()
    for item in _commerce_analysis_resource_media_items(result, "detail"):
        url = str(item.get("url") or "").strip()
        base_url = url.split("?", 1)[0]
        if (
            not url
            or _commerce_analysis_detail_asset_keys(base_url) & main_keys
            or _commerce_analysis_detail_url_is_noise(url)
            or _commerce_analysis_detail_url_is_platform_asset(url)
            or url in seen
        ):
            continue
        seen.add(url)
        items.append(item)
    return items


def _commerce_analysis_detail_order_is_trusted(result: Dict[str, Any]) -> bool:
    """Whether the source already scoped the list to the seller detail module.

    Electron 页面采集器读取的是限定详情容器或 ``detail.getdesc`` 状态；这类
    结果可以保留原始顺序和不同 CDN 输出宽度。旧版导入快照没有这个来源信号，
    仍走下面的重复宽度启发式，避免把页面其它图片拼进长图。
    """
    detail = result.get("detail") if isinstance(result.get("detail"), dict) else {}
    collection = result.get("collection") if isinstance(result.get("collection"), dict) else {}
    signals = " ".join(
        str(value or "").strip().lower()
        for value in (
            detail.get("source"),
            collection.get("source"),
            collection.get("strategy"),
            collection.get("mode"),
        )
    )
    return any(
        marker in signals
        for marker in (
            "commerce",
            "detail.getdesc",
            "product-page-state",
            "visible-detail-dom",
            "page-state-network",
            "page-state",
        )
    )


def _commerce_analysis_detail_fallback_parts(parts: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Choose a contiguous detail-image run when no repeated-width block exists.

    Import/page-DOM snapshots can contain gallery, recommendation and chrome
    assets in one flat list. Returning every image as a fallback creates a
    plausible-looking but incorrect long image, so only sizeable content images
    are eligible here. Taobao platform assets remain available as layout
    boundary markers, but are never concatenated.
    """
    if not parts:
        return []

    def is_candidate(part: Dict[str, Any]) -> bool:
        width = int(part.get("width") or 0)
        height = int(part.get("height") or 0)
        url = str(part.get("url") or "").lower()
        return (
            width >= 240
            and height >= 80
            and not _commerce_analysis_detail_url_is_noise(url)
            and not _commerce_analysis_detail_url_is_platform_asset(url)
        )

    candidates = [part for part in parts if is_candidate(part)]
    if not candidates:
        return []

    candidate_ids = {id(part) for part in candidates}
    runs: List[List[Dict[str, Any]]] = []
    current: List[Dict[str, Any]] = []
    previous_index = None
    for part in parts:
        if id(part) not in candidate_ids:
            if current:
                runs.append(current)
                current = []
            previous_index = None
            continue
        index = int(part.get("index") or 0)
        if current and previous_index is not None and index - previous_index > 2:
            runs.append(current)
            current = []
        current.append(part)
        previous_index = index
    if current:
        runs.append(current)

    best = max(
        runs,
        key=lambda run: (
            len(run),
            sum(int(part.get("width") or 0) * int(part.get("height") or 0) for part in run),
            -int(run[0].get("index") or 0),
        ),
    )
    if len(best) >= 2:
        return sorted(best, key=lambda part: int(part.get("index") or 0))

    # A genuine detail response may contain only one image. Keep the largest
    # eligible content image rather than an arbitrary first DOM asset.
    return [max(candidates, key=lambda part: int(part.get("width") or 0) * int(part.get("height") or 0))]


def _commerce_analysis_select_detail_long_parts(
    parts: List[Dict[str, Any]],
    include_seller_photo_strip: bool = False,
    preserve_detail_order: bool = False,
) -> List[Dict[str, Any]]:
    """Keep the ordered detail layout and seller photo strip.

    Taobao's page DOM often exposes gallery/review/recommendation images next to
    the actual detail response. For a trusted detail-container/getdesc result,
    keep every eligible item in its supplied order: the CDN may return part of
    the same detail layout at 790px and part at 1440px, and treating the width
    change as a boundary drops the rest of the long image. Legacy page-wide DOM
    snapshots still use a repeated-width block as a safer signal than URL order
    alone; wide header/promo images immediately before it and the large
    seller-photo strip immediately after it are retained. Taobao platform
    ``-tps-`` assets are kept only as a boundary marker and are never added to
    the preview. The seller-photo strip is kept only when the source is an
    authoritative detail response rather than a historical page-wide DOM
    snapshot.
    """
    if not parts:
        return []
    eligible = [
        part for part in parts
        if int(part.get("width") or 0) >= 240
        and int(part.get("height") or 0) >= 80
        and not _commerce_analysis_detail_url_is_platform_asset(str(part.get("url") or ""))
    ]
    if preserve_detail_order:
        return sorted(eligible, key=lambda part: int(part.get("index") or 0))

    buckets: Dict[int, List[Dict[str, Any]]] = {}
    for part in eligible:
        width = int(part.get("width") or 0)
        bucket = max(16, round(width / 8) * 8)
        buckets.setdefault(bucket, []).append(part)
    dominant = max(
        (entry for entry in buckets.items() if len(entry[1]) >= 4),
        key=lambda entry: (len(entry[1]), -entry[0]),
        default=None,
    )
    if not dominant:
        return _commerce_analysis_detail_fallback_parts(parts)

    dominant_width, anchor_parts = dominant
    # Use the repeated width as an anchor, then allow a little post-crop
    # variation for tables/product sheets (for example 587px after balanced
    # side-margin trimming). Recommendation cards before the anchor are often
    # 658px ``-tps-`` assets and must not be absorbed into the detail block.
    anchor_tolerance = max(12, round(dominant_width * 0.02))
    anchor_parts = [
        part for part in parts
        if abs(int(part.get("width") or 0) - dominant_width) <= anchor_tolerance
        and int(part.get("height") or 0) >= 80
        and not _commerce_analysis_detail_url_is_platform_asset(str(part.get("url") or ""))
    ]
    if len(anchor_parts) < 4:
        return _commerce_analysis_detail_fallback_parts(parts)
    first_index = min(int(part.get("index") or 0) for part in anchor_parts)
    expanded_tolerance = max(42, round(dominant_width * 0.08))
    cluster_parts = [
        part for part in parts
        if int(part.get("index") or 0) >= first_index
        and abs(int(part.get("width") or 0) - dominant_width) <= expanded_tolerance
        and int(part.get("height") or 0) >= 80
        and not _commerce_analysis_detail_url_is_platform_asset(str(part.get("url") or ""))
    ]
    last_index = max(int(part.get("index") or 0) for part in cluster_parts)
    # Keep heterogeneous assets between the first and last repeated-width
    # image. A GIF or a cropped slice can legitimately be part of the same
    # detail layout even when the CDN serves it at another width.
    selected = [
        part for part in eligible
        if first_index <= int(part.get("index") or 0) <= last_index
    ]
    selected_ids = {id(part) for part in selected}

    # Detail pages commonly put a seller header and a promotion banner right
    # before the repeated 629/750px image block.
    for part in parts:
        index = int(part.get("index") or 0)
        if index >= first_index or first_index - index > 4:
            continue
        width = int(part.get("width") or 0)
        height = int(part.get("height") or 0)
        ratio = width / max(1, height)
        if (
            width >= dominant_width * 1.15
            and ratio >= 1.45
            and height >= 80
            and not _commerce_analysis_detail_url_is_platform_asset(str(part.get("url") or ""))
            and id(part) not in selected_ids
        ):
            selected.append(part)
            selected_ids.add(id(part))

    # The detail response may continue with large seller photos before the
    # official platform/certification assets. Keep that bounded run, but skip
    # tiny controls and thin atmosphere banners that are adjacent in the DOM.
    footer_start = None
    if include_seller_photo_strip:
        footer_start = min(
            (
                int(part.get("index") or 0)
                for part in parts
                if int(part.get("index") or 0) > last_index
                and _commerce_analysis_detail_url_is_platform_asset(str(part.get("url") or ""))
                and min(int(part.get("width") or 0), int(part.get("height") or 0)) >= 20
                and int(part.get("width") or 0) * int(part.get("height") or 0) >= 3_000
            ),
            default=None,
        )
    if include_seller_photo_strip and footer_start is not None:
        for part in parts:
            index = int(part.get("index") or 0)
            width = int(part.get("width") or 0)
            height = int(part.get("height") or 0)
            if index <= last_index or index >= footer_start or id(part) in selected_ids:
                continue
            if max(width, height) >= 1_000 and min(width, height) >= 300:
                selected.append(part)
                selected_ids.add(id(part))

    return sorted(selected, key=lambda part: int(part.get("index") or 0))


def _commerce_analysis_detail_long_cache_signature(result: Dict[str, Any]) -> str:
    urls = [item.get("url") for item in _commerce_analysis_detail_long_items(result) if item.get("url")]
    return hashlib.sha1(
        json.dumps(
            {"version": COMMERCE_ANALYSIS_DETAIL_CACHE_VERSION, "urls": urls},
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8", "ignore")
    ).hexdigest()[:20]


def _commerce_analysis_detail_long_cache_path(result: Dict[str, Any], job_id: str) -> str:
    """Return one cache path for one detail-image input, across all jobs.

    ``job_id`` remains in the signature for callers and old saved tasks, but it
    is deliberately not part of the new cache filename.  The old job-specific
    path is checked below so existing caches continue to work while new jobs
    stop creating one copy per task.
    """
    signature = _commerce_analysis_detail_long_cache_signature(result)
    return os.path.join(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR, f"{signature}.png")


def _commerce_analysis_legacy_detail_long_cache_path(result: Dict[str, Any], job_id: str) -> str:
    """Return the pre-deduplication job-specific cache path."""
    signature = _commerce_analysis_detail_long_cache_signature(result)
    safe_job_id = re.sub(r"[^a-zA-Z0-9_-]", "", str(job_id or ""))[:80] or "detail"
    return os.path.join(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR, f"{safe_job_id}-{signature}.png")


def _commerce_analysis_find_legacy_detail_long_cache(result: Dict[str, Any]) -> Optional[str]:
    """Find any old job-specific cache for the same detail input."""
    suffix = f"-{_commerce_analysis_detail_long_cache_signature(result)}.png"
    if not os.path.isdir(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR):
        return None
    try:
        entries = sorted(os.scandir(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR), key=lambda item: item.name)
    except OSError:
        return None
    for entry in entries:
        if not entry.is_file() or not entry.name.endswith(suffix):
            continue
        try:
            if entry.stat().st_size > 0:
                return entry.path
        except OSError:
            continue
    return None


def _commerce_analysis_find_cached_detail_long_content(content: bytes, exclude_path: str = "") -> Optional[str]:
    """Find an existing detail PNG with identical bytes.

    This catches equivalent output produced from different URL signatures. The
    directory is a derived cache, so comparing only files with the same size
    keeps the check bounded without changing the source result or its identity.
    """
    if not content or not os.path.isdir(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR):
        return None
    digest = hashlib.sha256(content).hexdigest()
    expected_size = len(content)
    excluded = os.path.normcase(os.path.abspath(exclude_path)) if exclude_path else ""
    try:
        entries = list(os.scandir(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR))
    except OSError:
        return None
    for entry in entries:
        if not entry.is_file() or not entry.name.lower().endswith(".png"):
            continue
        candidate = os.path.normcase(os.path.abspath(entry.path))
        if excluded and candidate == excluded:
            continue
        try:
            if entry.stat().st_size != expected_size:
                continue
            with open(entry.path, "rb") as handle:
                candidate_hash = hashlib.sha256()
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    candidate_hash.update(chunk)
                candidate_digest = candidate_hash.hexdigest()
            if candidate_digest == digest:
                return entry.path
        except (OSError, ValueError):
            continue
    return None


def _commerce_analysis_detail_content_crop(image: Image.Image) -> Tuple[int, int]:
    """Return a conservative horizontal crop that removes only balanced blank margins."""
    width, height = image.size
    if width < 32 or height < 32:
        return 0, width
    resampling = getattr(Image, "Resampling", Image)
    scale = min(1.0, 512 / max(1, width), 1024 / max(1, height))
    sample_width = max(1, round(width * scale))
    sample_height = max(1, round(height * scale))
    sample = image.resize((sample_width, sample_height), resampling.BILINEAR)
    try:
        pixels = sample.load()
        threshold = max(1, round(sample_height * 0.01))
        occupied = []
        for x in range(sample_width):
            count = 0
            for y in range(sample_height):
                red, green, blue = pixels[x, y][:3]
                if red < 246 or green < 246 or blue < 246:
                    count += 1
            if count >= threshold:
                occupied.append(x)
        if not occupied:
            return 0, width
        left = occupied[0]
        right = occupied[-1]
        content_ratio = (right - left + 1) / max(1, sample_width)
        left_gap = left / max(1, sample_width)
        right_gap = (sample_width - right - 1) / max(1, sample_width)
        # Only trim large, roughly symmetrical blank margins. This keeps
        # intentional left/right whitespace in product banners intact.
        if content_ratio >= 0.94 or min(left_gap, right_gap) < 0.03 or abs(left_gap - right_gap) >= 0.12:
            return 0, width
        padding = max(2, round(width * 0.025))
        crop_left = max(0, math.floor(left / max(1, sample_width) * width) - padding)
        crop_right = min(width, math.ceil((right + 1) / max(1, sample_width) * width) + padding)
        if crop_right - crop_left < max(32, round(width * 0.25)):
            return 0, width
        return crop_left, crop_right
    finally:
        sample.close()


def _commerce_analysis_choose_detail_target_width(parts: List[Dict[str, Any]]) -> int:
    widths = [max(1, int(part.get("width") or 0)) for part in parts if part.get("width")]
    if not widths:
        return 1
    buckets: Dict[int, int] = {}
    for width in widths:
        bucket = max(16, round(width / 16) * 16)
        buckets[bucket] = buckets.get(bucket, 0) + 1
    dominant = max(buckets.items(), key=lambda entry: (entry[1], entry[0]))
    if dominant[1] > 1:
        return dominant[0]
    ordered = sorted(widths)
    middle = len(ordered) // 2
    return ordered[middle] if len(ordered) % 2 else round((ordered[middle - 1] + ordered[middle]) / 2)


def _commerce_analysis_fit_detail_target_width(parts: List[Dict[str, Any]], preferred_width: int) -> int:
    max_pixels = COMMERCE_ANALYSIS_DETAIL_MAX_OUTPUT_PIXELS

    def output_height(width: int) -> int:
        return sum(max(1, round(int(part["height"]) * width / max(1, int(part["width"])))) for part in parts)

    preferred_width = max(1, int(preferred_width))
    if preferred_width * output_height(preferred_width) <= max_pixels:
        return preferred_width
    low, high = 1, preferred_width
    for _ in range(24):
        middle = (low + high) // 2
        if middle * output_height(middle) <= max_pixels:
            low = middle
        else:
            high = middle - 1
    return max(1, low)


def _commerce_analysis_build_detail_long_image(result: Dict[str, Any]) -> bytes:
    parts: List[Dict[str, Any]] = []
    errors = []
    max_input_bytes = 80 * 1024 * 1024
    max_input_pixels = 120_000_000
    detail_items = [
        (index, item)
        for index, item in enumerate(
            _commerce_analysis_detail_long_items(result)[:COMMERCE_ANALYSIS_DETAIL_COMPOSER_MAX_IMAGES],
            1,
        )
        if not re.search(
            r"/(?:s|spacer|blank)(?:\.[a-z0-9]+)?(?:$|[?#])",
            str(item.get("url") or ""),
            re.IGNORECASE,
        )
    ]
    if detail_items:
        # 详情页通常由多张 CDN 切片组成。过去这里逐张串行下载，任意一张
        # 慢图都会把整个下载按钮卡住；每个 worker 只拥有自己的 PIL 对象，
        # 最终仍按原始序号汇总，因而不改变长图内容顺序。
        remote_bytes = {"value": 0}
        remote_bytes_lock = Lock()
        referer = str(result.get("finalUrl") or result.get("originalUrl") or "")

        def load_detail_part(entry: Tuple[int, Dict[str, str]]):
            index, item = entry
            url = str(item.get("url") or "")
            source = None
            normalized = None
            try:
                path = output_file_from_url(url)
                if not path:
                    local_name = filename_from_media_url(url, "")
                    path = local_media_file_by_basename(local_name) if local_name else None
                if path and os.path.isfile(path):
                    if os.path.getsize(path) > max_input_bytes:
                        raise ValueError("单张详情图片超过 80 MB")
                    source = Image.open(path)
                else:
                    remote = fetch_remote_media_bytes(
                        url,
                        timeout=45,
                        max_bytes=max_input_bytes,
                        referer=referer,
                    )
                    if not remote:
                        raise ValueError("远程资源不可用")
                    data = remote[0]
                    with remote_bytes_lock:
                        if remote_bytes["value"] + len(data) > 512 * 1024 * 1024:
                            raise ValueError("详情图片总大小超过 512 MB")
                        remote_bytes["value"] += len(data)
                    source = Image.open(BytesIO(data))
                with source:
                    transposed = ImageOps.exif_transpose(source)
                    try:
                        if transposed.width < 3 or transposed.height < 3:
                            return None, ""
                        if transposed.width * transposed.height > max_input_pixels:
                            raise ValueError("图片像素超过 120 MP")
                        transposed.load()
                        if transposed.mode in ("RGBA", "LA") or (transposed.mode == "P" and "transparency" in transposed.info):
                            rgba = transposed.convert("RGBA")
                            white = Image.new("RGBA", rgba.size, "white")
                            white.alpha_composite(rgba)
                            rgba.close()
                            normalized = white.convert("RGB")
                            white.close()
                        else:
                            normalized = transposed.convert("RGB")
                    finally:
                        if transposed is not source:
                            transposed.close()
                crop_left, crop_right = _commerce_analysis_detail_content_crop(normalized)
                if crop_left or crop_right < normalized.width:
                    cropped = normalized.crop((crop_left, 0, crop_right, normalized.height))
                    normalized.close()
                    normalized = cropped
                return {
                    "image": normalized,
                    "width": normalized.width,
                    "height": normalized.height,
                    "url": url,
                    "index": index,
                }, ""
            except Exception as exc:
                if normalized is not None:
                    try:
                        normalized.close()
                    except Exception:
                        pass
                if source is not None:
                    try:
                        source.close()
                    except Exception:
                        pass
                return None, f"第 {index} 张：{type(exc).__name__}"

        with ThreadPoolExecutor(max_workers=min(6, len(detail_items))) as executor:
            for part, error in executor.map(load_detail_part, detail_items):
                if part is not None:
                    parts.append(part)
                if error:
                    errors.append(error)
    if not parts:
        detail = "；".join(errors[:3]) or "没有可读取的详情图片"
        raise ValueError(detail)
    try:
        detail_state = result.get("detail") if isinstance(result.get("detail"), dict) else {}
        collection_state = result.get("collection") if isinstance(result.get("collection"), dict) else {}
        network_modules = collection_state.get("networkModules") if isinstance(collection_state.get("networkModules"), dict) else {}
        detail_source = str(detail_state.get("source") or "").lower()
        has_authoritative_detail_response = (
            "detail.getdesc" in detail_source
            or "mtop-detail" in detail_source
            or int(network_modules.get("detail") or 0) > 0
        )
        selected_parts = _commerce_analysis_select_detail_long_parts(
            parts,
            include_seller_photo_strip=has_authoritative_detail_response,
            preserve_detail_order=_commerce_analysis_detail_order_is_trusted(result),
        )
        selected_ids = {id(part) for part in selected_parts}
        for part in parts:
            if id(part) not in selected_ids:
                try:
                    part["image"].close()
                except Exception:
                    pass
        parts = selected_parts
        preferred_width = _commerce_analysis_choose_detail_target_width(parts)
        target_width = min(1200, max(320, preferred_width))
        target_width = _commerce_analysis_fit_detail_target_width(parts, target_width)
        scaled_heights = [max(1, round(part["height"] * target_width / part["width"])) for part in parts]
        total_height = sum(scaled_heights)
        canvas = Image.new("RGB", (target_width, total_height), "white")
        y = 0
        resampling = getattr(Image, "Resampling", Image).LANCZOS
        for part, height in zip(parts, scaled_heights):
            image = part["image"]
            resized = image.resize((target_width, height), resampling)
            canvas.paste(resized, (0, y))
            y += height
            resized.close()
        output = BytesIO()
        canvas.save(output, format="PNG", compress_level=6)
        canvas.close()
        return output.getvalue()
    finally:
        for part in parts:
            try:
                part["image"].close()
            except Exception:
                pass


def _commerce_analysis_get_detail_long_image_payload(
    result: Dict[str, Any],
    job_id: str,
) -> Tuple[str, Optional[bytes]]:
    """Return the cached long-image path, or bytes when the cache cannot be written."""
    cache_path = _commerce_analysis_detail_long_cache_path(result, job_id)
    legacy_cache_path = _commerce_analysis_legacy_detail_long_cache_path(result, job_id)
    any_legacy_cache_path = _commerce_analysis_find_legacy_detail_long_cache(result)
    try:
        if os.path.isfile(cache_path) and os.path.getsize(cache_path) > 0:
            return cache_path, None
        if legacy_cache_path != cache_path and os.path.isfile(legacy_cache_path) and os.path.getsize(legacy_cache_path) > 0:
            return legacy_cache_path, None
        if any_legacy_cache_path and any_legacy_cache_path != cache_path:
            return any_legacy_cache_path, None
    except OSError:
        pass
    with COMMERCE_ANALYSIS_DETAIL_CACHE_LOCK:
        try:
            if os.path.isfile(cache_path) and os.path.getsize(cache_path) > 0:
                return cache_path, None
            if legacy_cache_path != cache_path and os.path.isfile(legacy_cache_path) and os.path.getsize(legacy_cache_path) > 0:
                return legacy_cache_path, None
            if any_legacy_cache_path and any_legacy_cache_path != cache_path and os.path.isfile(any_legacy_cache_path):
                return any_legacy_cache_path, None
        except OSError:
            pass
        content = _commerce_analysis_build_detail_long_image(result)
        existing_path = _commerce_analysis_find_cached_detail_long_content(content, exclude_path=cache_path)
        if existing_path:
            return existing_path, None
        temp_path = ""
        try:
            os.makedirs(COMMERCE_ANALYSIS_DETAIL_CACHE_DIR, exist_ok=True)
            temp_path = f"{cache_path}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
            with open(temp_path, "wb") as handle:
                handle.write(content)
            os.replace(temp_path, cache_path)
            return cache_path, None
        except OSError:
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass
        # 缓存目录不可写时仍保留原有的直接响应能力，避免把下载功能
        # 变成对本地缓存权限的硬依赖。
        return "", content


def _commerce_analysis_get_detail_long_image(result: Dict[str, Any], job_id: str) -> bytes:
    """Build the long image once per result and reuse it for preview/download."""
    cache_path, content = _commerce_analysis_get_detail_long_image_payload(result, job_id)
    if content is not None:
        return content
    with open(cache_path, "rb") as handle:
        return handle.read()


async def _commerce_analysis_prewarm_detail_cache(result: Dict[str, Any], job_id: str):
    """Prepare the detail PNG after collection so the user's first download is immediate."""
    try:
        await asyncio.to_thread(_commerce_analysis_get_detail_long_image_payload, result, job_id)
    except Exception as exc:
        logging.getLogger("commerce-analysis").debug(
            "详情页长图预热失败（任务 %s）：%s",
            str(job_id or "")[:80],
            str(exc)[:240],
        )


def _commerce_analysis_schedule_detail_cache_prewarm(result: Dict[str, Any], job_id: str):
    """Start one non-blocking detail-image build for a completed product snapshot."""
    if not job_id or not _commerce_analysis_detail_long_items(result):
        return
    key = str(job_id)
    previous = COMMERCE_ANALYSIS_DETAIL_PREWARM_TASKS.get(key)
    if previous and not previous.done():
        return
    try:
        task = asyncio.create_task(_commerce_analysis_prewarm_detail_cache(result, key))
    except RuntimeError:
        # Sync/unit-test callers have no running event loop; the normal HTTP
        # routes always run inside one and will schedule the prewarm.
        return
    COMMERCE_ANALYSIS_DETAIL_PREWARM_TASKS[key] = task

    def cleanup(done_task, task_key=key, scheduled_task=task):
        if COMMERCE_ANALYSIS_DETAIL_PREWARM_TASKS.get(task_key) is scheduled_task:
            COMMERCE_ANALYSIS_DETAIL_PREWARM_TASKS.pop(task_key, None)

    task.add_done_callback(cleanup)


def _commerce_analysis_detail_screen_count(width: int, height: int) -> int:
    """Estimate the number of 9:16 screenfuls represented by a detail long image."""
    width = max(1, int(width or 0))
    height = max(1, int(height or 0))
    screen_height = width * 16 / 9
    return max(1, min(24, int(round(height / max(1.0, screen_height)))))


def _commerce_analysis_detail_reference_indices(screen_count: int, max_references: int) -> List[int]:
    """Return evenly distributed detail-screen indexes within a bounded budget."""
    try:
        screen_count = max(0, int(screen_count or 0))
    except (TypeError, ValueError):
        screen_count = 0
    try:
        max_references = max(1, int(max_references or 1))
    except (TypeError, ValueError):
        max_references = 1
    if not screen_count:
        return []
    limit = min(screen_count, max_references)
    if limit == screen_count:
        return list(range(screen_count))
    if limit == 1:
        return [0]
    indexes: List[int] = []
    for position in range(limit):
        index = int(round(position * (screen_count - 1) / (limit - 1)))
        if index not in indexes:
            indexes.append(index)
    return indexes


def _commerce_analysis_detail_long_reference_images(
    result: Dict[str, Any],
    job_id: str,
    max_references: Optional[int] = None,
) -> Tuple[List[str], int]:
    """Create bounded visual references for detail analysis from the canonical long image.

    The seller detail is often delivered as many narrow image slices. Sending those
    source slices directly makes the model mistake a slice (or a Taobao platform
    banner) for a complete screen. The preview builder already has the authoritative
    filtering and ordering, so split that same output into screen-sized references.
    """
    content = _commerce_analysis_get_detail_long_image(result, job_id)
    references: List[str] = []
    with Image.open(BytesIO(content)) as image:
        image.load()
        screen_count = _commerce_analysis_detail_screen_count(image.width, image.height)
        reference_indexes = _commerce_analysis_detail_reference_indices(
            screen_count,
            max_references or COMMERCE_CHAT_DETAIL_REFERENCE_MAX,
        )
        for index in reference_indexes:
            top = round(index * image.height / screen_count)
            bottom = round((index + 1) * image.height / screen_count)
            if bottom <= top:
                continue
            crop = image.crop((0, top, image.width, bottom))
            source = BytesIO()
            try:
                crop.save(source, format="PNG", optimize=True)
                source.seek(0)
                reference = vision_image_data_url(
                    source,
                    max_size=VISION_INPUT_MAX_EDGE,
                    max_bytes=VISION_INPUT_MAX_BYTES,
                )
                if reference:
                    references.append(reference)
            finally:
                source.close()
                crop.close()
    return references, screen_count


def _commerce_analysis_build_resource_media_download(result: Dict[str, Any], job_id: str, resource_id: str):
    if resource_id == "detail":
        content = _commerce_analysis_get_detail_long_image(result, job_id)
        return content, "image/png", f"{_commerce_analysis_download_stem(result, job_id)}-详情页长图.png"
    items = _commerce_analysis_resource_media_items(result, resource_id)
    if not items:
        raise ValueError("当前资源没有可下载的媒体文件")
    max_file_bytes = 160 * 1024 * 1024 if resource_id == "videos" else 32 * 1024 * 1024
    max_archive_bytes = 512 * 1024 * 1024
    errors = []
    used_names = set()
    success_count = 0
    total_bytes = 0
    archive = BytesIO()
    with zipfile.ZipFile(archive, "w", zipfile.ZIP_DEFLATED) as zf:
        for index, item in enumerate(items, 1):
            url = item["url"]
            try:
                remote = fetch_remote_media_bytes(
                    url,
                    timeout=60 if resource_id == "videos" else 45,
                    max_bytes=max_file_bytes,
                    referer=str(result.get("finalUrl") or result.get("originalUrl") or ""),
                )
                if not remote:
                    raise ValueError("远程资源不可用")
                data, content_type = remote
                total_bytes += len(data)
                if total_bytes > max_archive_bytes:
                    raise ValueError("下载内容总大小超过 512 MB")
                name = _commerce_analysis_media_filename(url, resource_id, index, content_type, item.get("label") or "")
                name = _commerce_analysis_unique_media_filename(name, used_names)
                zf.writestr(name, data)
                success_count += 1
            except Exception as exc:
                errors.append(f"第 {index} 个文件：{str(exc)[:120] or type(exc).__name__}")
        if errors:
            note = [f"成功下载 {success_count} 个文件，失败 {len(errors)} 个。", *errors[:30]]
            zf.writestr("下载说明.txt", "\n".join(note))
    if not success_count:
        raise ValueError(errors[0] if errors else "没有可下载的媒体文件")
    label = {"images": "主图", "detail_more": "详情页多图", "sku_images": "SKU图", "videos": "主图视频"}.get(resource_id, resource_id)
    filename = f"{_commerce_analysis_download_stem(result, job_id)}-{label}.zip"
    return archive.getvalue(), "application/zip", filename


@app.get("/api/commerce-analysis/jobs/{job_id}/verification.json")
async def commerce_analysis_download_verification_json(job_id: str):
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    if not result:
        raise HTTPException(status_code=409, detail="该任务尚未生成核验快照")
    manifest = _commerce_analysis_verification_payload(result, job_id)
    filename = f"商品分析核验-{str(job_id or '')[:12]}.json"
    return Response(
        content=json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"),
        media_type="application/json",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{urllib.parse.quote(filename)}"},
    )


@app.get("/api/commerce-analysis/jobs/{job_id}/verification.csv")
async def commerce_analysis_download_verification_csv(job_id: str):
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    if not result:
        raise HTTPException(status_code=409, detail="该任务尚未生成核验快照")
    manifest = _commerce_analysis_verification_payload(result, job_id)
    filename = f"商品分析核验-{str(job_id or '')[:12]}.csv"
    return Response(
        content=_commerce_analysis_verification_csv(manifest).encode("utf-8"),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{urllib.parse.quote(filename)}"},
    )


@app.get("/api/commerce-analysis/jobs/{job_id}/resources/{resource_id}/media")
async def commerce_analysis_download_media_resource(job_id: str, resource_id: str, preview: bool = False):
    resource_id = str(resource_id or "").strip().lower()
    if resource_id not in COMMERCE_ANALYSIS_MEDIA_RESOURCE_IDS:
        raise HTTPException(status_code=404, detail="该资源不支持媒体下载")
    job = await asyncio.to_thread(_commerce_analysis_get_job, job_id)
    if not job:
        raise HTTPException(status_code=404, detail="商品分析任务不存在")
    result = job.get("result") if isinstance(job.get("result"), dict) else {}
    if not result:
        raise HTTPException(status_code=409, detail="该资源尚未准备完成")
    result = _commerce_analysis_attach_contract(result, job_id=job_id, mode=str(result.get("source") or "import"))
    resource = next((item for item in result.get("resources") or [] if item.get("id") == resource_id), None)
    if not resource or not resource.get("downloadable"):
        raise HTTPException(status_code=409, detail=(resource or {}).get("reason") or "该数据模块当前没有可下载内容")
    try:
        if resource_id == "detail":
            cache_path, content = await asyncio.to_thread(
                _commerce_analysis_get_detail_long_image_payload, result, job_id
            )
            media_type = "image/png"
            filename = f"{_commerce_analysis_download_stem(result, job_id)}-详情页长图.png"
        else:
            cache_path = ""
            content, media_type, filename = await asyncio.to_thread(
                _commerce_analysis_build_resource_media_download, result, job_id, resource_id
            )
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"媒体下载失败：{str(exc)[:240]}") from exc
    encoded = urllib.parse.quote(sanitize_export_filename(filename, "商品分析资源.bin"))
    disposition = "inline" if resource_id == "detail" and preview else "attachment"
    response_headers = {
        "Content-Disposition": f"{disposition}; filename*=UTF-8''{encoded}",
        # 预览和下载共用同一份不可变缓存文件；短期缓存避免用户重复点击
        # 时再次等待本地服务生成长图。
        "Cache-Control": "private, max-age=3600",
    }
    if resource_id == "detail" and cache_path:
        return FileResponse(cache_path, media_type=media_type, headers=response_headers)
    return Response(
        content=content,
        media_type=media_type,
        headers=response_headers,
    )


