@app.get("/api/assets/trash")
async def list_trashed_assets(q: str = "", offset: int = 0, limit: int = 100):
    phrase = str(q or "").strip().lower()
    records = []
    for item in ASSET_REGISTRY.records():
        if not int(item.get("deleted_at") or 0):
            continue
        if phrase and phrase not in " ".join(
            [str(item.get("id") or ""), str(item.get("name") or ""), str(item.get("canonical_url") or "")]
        ).lower():
            continue
        records.append(item)
    records.sort(key=lambda item: -int(item.get("deleted_at") or 0))
    offset = max(0, int(offset or 0))
    limit = max(1, min(500, int(limit or 100)))
    return {
        "items": [_asset_registry_public_record(item) for item in records[offset:offset + limit]],
        "total": len(records),
        "offset": offset,
        "limit": limit,
        "has_more": offset + limit < len(records),
    }


