@app.post("/api/assets/{asset_id}/restore")
async def restore_registered_asset(asset_id: str, request: Request):
    ensure_same_origin_request(request)
    record = ASSET_REGISTRY.get(asset_id)
    if not record:
        raise HTTPException(status_code=404, detail="素材不存在")
    metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
    context = metadata.get("restore_context") if isinstance(metadata.get("restore_context"), dict) else {}
    library_context = context.get("asset_library") if isinstance(context.get("asset_library"), dict) else None
    lib = None
    target_library = None
    target_category = None
    saved_item = None
    recreated_category = False
    if library_context:
        lib = load_asset_library()
        target_library = find_asset_library(lib, library_context.get("library_id") or "")
        target_category = find_asset_category_in_library(
            lib,
            library_context.get("category_id") or "",
            library_context.get("library_id") or "",
        )
        saved_item = library_context.get("item") if isinstance(library_context.get("item"), dict) else None
        if not saved_item:
            raise HTTPException(status_code=409, detail="原素材库或分类已不存在，无法恢复到原位置")
        if not target_category:
            category_context = library_context.get("category") if isinstance(library_context.get("category"), dict) else {}
            category_id = str(category_context.get("id") or library_context.get("category_id") or "").strip()
            if not target_library or not category_id:
                raise HTTPException(status_code=409, detail="原素材库已不存在，无法恢复到原位置")
            target_category = {
                "id": category_id,
                "name": sanitize_asset_name(category_context.get("name") or "已恢复素材", "已恢复素材"),
                "type": str(category_context.get("type") or "image") or "image",
                "dir": str(category_context.get("dir") or "").strip("/\\"),
                "items": [],
            }
            target_library.setdefault("categories", []).append(target_category)
            recreated_category = True
    restored = _asset_registry_restore_media(asset_id)
    if target_category and saved_item:
        existing_ids = {str(item.get("id") or "") for item in target_category.get("items", []) if isinstance(item, dict)}
        if str(saved_item.get("id") or "") not in existing_ids:
            target_category.setdefault("items", []).append(saved_item)
        try:
            save_asset_library(lib)
        except Exception as exc:
            try:
                _asset_registry_trash_media(asset_id, reason="restore_rollback", restore_context=context)
            except Exception:
                pass
            raise HTTPException(status_code=500, detail=f"恢复素材库记录失败：{exc}") from exc
    return {
        "ok": True,
        "asset": _asset_registry_public_record(restored),
        "restored_category": recreated_category,
    }


