@app.patch("/api/image-space/classification")
async def edit_image_space_classification(payload: ImageSpaceClassificationRequest):
    lib = None
    sidecar = None
    if payload.source == "assets":
        lib = load_asset_library()
        item = find_asset_item_in_library(lib, payload.id)
        if item is None:
            raise HTTPException(status_code=404, detail="素材不存在")
        previous = item.get("classification") or {}
    else:
        if payload.source == "local":
            filename, path = _local_upload_safe_path(payload.id)
            sidecar = _local_upload_classification_path(filename)
            previous = _read_local_upload_classification(filename) or {}
        else:
            path = storage_file_path("generated", payload.id.removeprefix("generated:"))
            if not path or not os.path.isfile(path):
                raise HTTPException(status_code=404, detail="素材不存在")
            sidecar = path + ".classification.json"
            previous = image_space_read_generated_classification(path) or {}
        if not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="素材不存在")
    manual = payload.manual or {}
    if set(manual) - {"summary", "tags", "categories"}:
        raise HTTPException(status_code=400, detail="分类仅支持说明、标签和分类维度")
    if ("summary" in manual and not isinstance(manual["summary"], str)) or ("tags" in manual and (not isinstance(manual["tags"], list) or any(not isinstance(t, str) for t in manual["tags"]))):
        raise HTTPException(status_code=400, detail="说明须为文字，标签须为文字列表")
    categories = manual.get("categories", {})
    if not isinstance(categories, dict) or any(not isinstance(v, list) or any(not isinstance(t, str) for t in v) for v in categories.values()):
        raise HTTPException(status_code=400, detail="每个分类维度须为标签列表")
    clean = _normalize_asset_classification_fields(manual)
    normalized_manual = {k: clean[k] for k in ("summary", "tags") if k in manual}
    if "categories" in manual:
        normalized_manual["categories"] = {k: clean["categories"].get(k, []) for k in categories if k in ASSET_CLASSIFICATION_DIMENSION_NAMES}
    value = merge_classification({"ai": previous.get("ai", previous), "manual": normalized_manual}, _normalize_asset_classification_fields)
    if lib is not None:
        item["classification"] = value
        save_asset_library(lib)
    else:
        _atomic_write_json_locked(sidecar, value)
    return {"classification": value}

