@app.post("/api/asset-url-library/items")
async def add_asset_url_library_item(payload: AssetUrlLibraryItemRequest):
    url = str(payload.url or "").strip()
    if not valid_asset_url(url):
        raise HTTPException(status_code=400, detail="URL 只支持有效的 http(s) 或 asset:// 地址")
    lib = load_asset_url_library()
    existing = next((item for item in lib.get("items", []) if item.get("url") == url), None)
    if existing:
        existing["name"] = re.sub("\\s+", " ", str(payload.name or existing.get("name") or filename_from_media_url(url, "") or url).strip())[:160]
        existing["kind"] = infer_asset_url_kind(url, payload.kind or existing.get("kind") or "image")
        existing["note"] = str(payload.note or existing.get("note") or "").strip()[:1000]
        existing["updated_at"] = now_ms()
        lib = save_asset_url_library(lib)
        return {"library": lib, "item": existing, "existing": True}
    now = now_ms()
    kind = infer_asset_url_kind(url, payload.kind or "image")
    item = {
        "id": f"url_{uuid.uuid4().hex[:12]}",
        "url": url,
        "name": re.sub("\\s+", " ", str(payload.name or filename_from_media_url(url, "") or url).strip())[:160],
        "kind": kind,
        "note": str(payload.note or "").strip()[:1000],
        "created_at": now,
        "updated_at": now,
    }
    if not item["name"]:
        item["name"] = "视频 URL" if kind == "video" else "音频 URL" if kind == "audio" else "图片 URL"
    lib.setdefault("items", []).insert(0, item)
    lib = save_asset_url_library(lib)
    return {"library": lib, "item": item}

