@app.get("/api/prompt-cases")
async def get_prompt_cases(response: Response, q: str = "", category: str = "", sort: str = "recent", limit: int = 200, offset: int = 0):
    set_prompt_case_no_cache(response)
    with PROMPT_CASES_LOCK:
        data = load_prompt_cases()
        cases = list(data.get("cases") or [])
    query = re.sub(r"\s+", " ", str(q or "").strip()).lower()
    category = normalize_prompt_case_category_id(category) if str(category or "").strip() else ""
    if category:
        cases = [item for item in cases if item.get("category") == category]
    if query:
        def searchable(item):
            settings = item.get("settings") if isinstance(item.get("settings"), dict) else {}
            source = item.get("source") if isinstance(item.get("source"), dict) else {}
            prompt = item.get("prompt") if isinstance(item.get("prompt"), dict) else {}
            values = [
                item.get("title"), item.get("note"), prompt.get("display"), prompt.get("request"),
                settings.get("model"), settings.get("provider_id"), source.get("canvas_title"),
                " ".join(item.get("tags") or []),
            ]
            return " ".join(str(value or "") for value in values).lower()
        cases = [item for item in cases if query in searchable(item)]
    if sort == "used":
        cases.sort(key=lambda item: (int(item.get("use_count") or 0), int(item.get("last_used_at") or 0), int(item.get("created_at") or 0)), reverse=True)
    elif sort == "title":
        cases.sort(key=lambda item: str(item.get("title") or "").lower())
    else:
        cases.sort(key=lambda item: int(item.get("created_at") or 0), reverse=True)
    try:
        offset = max(0, int(offset))
    except (TypeError, ValueError):
        offset = 0
    try:
        limit = max(1, min(500, int(limit)))
    except (TypeError, ValueError):
        limit = 200
    return {
        "cases": cases[offset:offset + limit],
        "categories": data.get("categories") or [],
        "total": len(cases),
        "offset": offset,
        "limit": limit,
        "updated_at": data.get("updated_at") or now_ms(),
    }

@app.get("/api/prompt-cases/index")
async def get_prompt_case_index(response: Response):
    set_prompt_case_no_cache(response)
    with PROMPT_CASES_LOCK:
        data = load_prompt_cases()
        entries = []
        by_media_url = {}
        for case in data.get("cases") or []:
            source_urls = sorted(prompt_case_source_urls(case))
            entry = {
                "id": case.get("id"),
                "media_urls": source_urls,
                "cover_url": (case.get("cover") or {}).get("url") or "",
            }
            entries.append(entry)
            for source_url in source_urls:
                by_media_url[source_url] = case.get("id")
        return {"cases": entries, "by_media_url": by_media_url, "updated_at": data.get("updated_at") or now_ms()}

@app.get("/api/prompt-cases/{case_id}")
async def get_prompt_case(response: Response, case_id: str):
    set_prompt_case_no_cache(response)
    with PROMPT_CASES_LOCK:
        data = load_prompt_cases()
        case = next((item for item in data.get("cases") or [] if item.get("id") == case_id), None)
