@app.delete("/api/prompt-cases/categories/{category_id}")
async def delete_prompt_case_category(category_id: str):
    with PROMPT_CASES_LOCK:
        data = load_prompt_cases()
        categories = data.get("categories") or []
        target = next((item for item in categories if item.get("id") == category_id), None)
        if not target:
            # 兼容旧页面：后端规范化时可能已经移除了旧的“未分类”，此时删除请求视为已完成。
            if category_id == "uncategorized":
                return {"categories": categories, "cases": data.get("cases") or [], "deleted": category_id}
            raise HTTPException(status_code=404, detail="分类不存在")
        data["categories"] = [item for item in categories if item.get("id") != category_id]
        fallback_category = next((str(item.get("id") or "") for item in data["categories"] if item.get("id")), "")
        for case in data.get("cases") or []:
            if case.get("category") == category_id:
                case["category"] = fallback_category
                case["updated_at"] = now_ms()
        data = save_prompt_cases(data)
    return {"categories": data.get("categories") or [], "cases": data.get("cases") or [], "deleted": category_id}

