@app.post("/api/chat")
async def chat(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    link_context = await _prepare_link_context(payload.message, [], payload.link_job_ids, payload.link_resource_ids, payload.page_context)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    remove_failed_chat_message(conversation, payload)
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    page_context_source = str((link_context.get("page_context") or {}).get("source") or "").strip()
    link_image_refs = [
        {"url": url, "name": f"商品链接参考图 {index + 1}", "kind": "image", "role": "link"}
        for index, url in enumerate(link_context.get("images") or [])
        if _commerce_analysis_is_chat_image_reference(url)
    ]
    image_refs = (image_references(refs) + link_image_refs)[:CHAT_ATTACHMENT_MAX]
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": payload.mode,
    }
    if link_context.get("context_text") or link_context.get("job_ids"):
        user_message.update({
            "link_job_ids": link_context.get("job_ids", []),
            "link_resource_ids": link_context.get("resource_ids", []),
            "link_urls": [
                str(item.get("original_url") or item.get("final_url") or "").strip()
                for item in (link_context.get("links") or [])
                if str(item.get("original_url") or item.get("final_url") or "").strip()
            ],
            "link_context": link_context.get("context_text") or "",
            "link_images": link_context.get("images", [])[:CHAT_ATTACHMENT_MAX],
            "link_page_context_source": page_context_source,
        })
    skill_meta = public_agent_skill(payload)
    if skill_meta:
        user_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    history_record = None
    if payload.mode == "image":
        image_provider_id = payload.provider if payload.provider not in {"modelscope"} else "comfly"
        provider = get_api_provider(image_provider_id)
        default_model = (provider.get("image_models") or [IMAGE_MODEL])[0]
        model = selected_model(payload.image_model or payload.model, default_model)
        image_size = chat_prompt_size_override(payload.message, payload.size) or payload.size
        try:
            image_data, raw = await generate_ai_image(payload.message, image_size, payload.quality, model, image_refs, provider["id"], "", payload.background)
            local_url = await save_ai_image_to_output(image_data, prefix="chat_")
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
            raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
        except httpx.HTTPError as exc:
            log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
            raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{exc}") from exc
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "type": "image",
            "content": payload.message,
            "image_url": local_url,
            "created_at": now_ms(),
            "model": model,
            "size": image_size,
            "background": payload.background,
            "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
        }
        history_record = chat_image_history_record(
            payload.message,
            [local_url],
            model,
            provider,
            image_size,
            payload.quality,
            image_refs,
            "generate_image",
            raw,
            payload.background,
        )
    else:
        _codex_provider = get_api_provider(payload.provider)
        if is_codex_provider(_codex_provider):
            model = selected_model(payload.model, (_codex_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
            payload.model = model
            text, raw = await codex_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            return {"conversation": conversation, "message": assistant_message}
        if is_gemini_cli_provider(_codex_provider):
            model = selected_model(payload.model, (_codex_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
            payload.model = model
            text, raw = await gemini_cli_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            return {"conversation": conversation, "message": assistant_message}
        chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
        _conv_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
        _conv_is_apimart = is_apimart_provider(_conv_provider)
        history = conversation["messages"][-MAX_HISTORY_MESSAGES:]
        upstream_messages = [{"role": "system", "content": chat_system_prompt(payload)}]
        for item in history:
            msg = upstream_message_from_record(item)
            if msg:
                upstream_messages.append(msg)
        try:
            async with httpx.AsyncClient(timeout=chat_agent_http_timeout(CHAT_AGENT_REPLY_TIMEOUT)) as client:
                conv_req_body = {"model": model, "messages": upstream_messages}
                if _conv_is_apimart:
                    conv_req_body["stream"] = False
                response = await client.post(
                    f"{chat_base}/chat/completions",
                    headers=chat_hdrs,
                    json=conv_req_body,
                )
                response.raise_for_status()
                raw = response.json()
        except httpx.HTTPStatusError as exc:
            body = exc.response.text or ""
            friendly = friendly_chat_error_detail(body, model, _conv_provider)
            raise HTTPException(status_code=exc.response.status_code, detail=friendly or f"上游接口错误：{body}") from exc
        except httpx.TimeoutException as exc:
            raise HTTPException(
                status_code=504,
                detail=f"聊天模型响应超过 {CHAT_AGENT_REPLY_TIMEOUT:g} 秒，已自动停止；请重试或切换聊天模型",
            ) from exc
        except httpx.HTTPError as exc:
            raise HTTPException(status_code=502, detail=f"请求上游接口失败：{exc}") from exc
        raw_data = unwrap_apimart_response(raw) if isinstance(raw, dict) else raw
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": text_from_chat_response(raw).strip() or "接口返回了空回复。",
            "created_at": now_ms(),
            "model": model,
            "raw_usage": raw_data.get("usage") if isinstance(raw_data, dict) else None,
        }

    conversation["messages"].append(assistant_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)
    if history_record:
        save_to_history(history_record)
        if GLOBAL_LOOP:
            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(history_record), GLOBAL_LOOP)
    return {"conversation": conversation, "message": assistant_message}

@app.post("/api/chat/agent")
async def chat_agent(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    link_context = await _prepare_link_context(payload.message, [], payload.link_job_ids, payload.link_resource_ids, payload.page_context)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    remove_failed_chat_message(conversation, payload)
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    requested_confirmation = bool(payload.confirm_image_generation) or chat_agent_confirmation_message(payload.message)
    confirmed_draft = latest_chat_image_draft(conversation, payload.generation_draft_id) if requested_confirmation else None
    if payload.confirm_image_generation and not confirmed_draft:
        raise HTTPException(status_code=404, detail="待确认的生图文案不存在或已被清理，请重新整理")
    if confirmed_draft and confirmed_draft.get("draft_status") == "generated":
        raise HTTPException(status_code=409, detail="这份文案已经确认并生成过图片；如需再次生成，请发起新的生图请求")

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    page_context_source = str((link_context.get("page_context") or {}).get("source") or "").strip()
    link_image_refs = [
        {"url": url, "name": f"商品链接参考图 {index + 1}", "kind": "image", "role": "link"}
        for index, url in enumerate(link_context.get("images") or [])
        if _commerce_analysis_is_chat_image_reference(url)
    ]
    if confirmed_draft:
        draft_refs = [item for item in (confirmed_draft.get("used_references") or []) if isinstance(item, dict) and item.get("url")]
        image_refs = image_references(draft_refs)[:CHAT_ATTACHMENT_MAX]
    else:
        image_refs = (image_references(refs) + link_image_refs)[:CHAT_ATTACHMENT_MAX]
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": "agent",
    }
    if confirmed_draft:
        user_message.update({
            "generation_draft_id": str(confirmed_draft.get("id") or ""),
            "generation_confirmed": True,
            "generation_prompt": str(payload.generation_prompt or confirmed_draft.get("draft_prompt") or payload.message).strip(),
        })
    if link_context.get("context_text") or link_context.get("job_ids"):
        user_message.update({
            "link_job_ids": link_context.get("job_ids", []),
            "link_resource_ids": link_context.get("resource_ids", []),
            "link_urls": [
                str(item.get("original_url") or item.get("final_url") or "").strip()
                for item in (link_context.get("links") or [])
                if str(item.get("original_url") or item.get("final_url") or "").strip()
            ],
            "link_context": link_context.get("context_text") or "",
            "link_images": link_context.get("images", [])[:CHAT_ATTACHMENT_MAX],
            "link_page_context_source": page_context_source,
        })
    skill_meta = public_agent_skill(payload)
    if skill_meta:
        user_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    if confirmed_draft:
        action = str(confirmed_draft.get("draft_action") or "generate_image")
        if action not in {"generate_image", "edit_image"}:
            action = "edit_image" if image_refs else "generate_image"
        confirmed_prompt = str(payload.generation_prompt or confirmed_draft.get("draft_prompt") or payload.message or "").strip()
        if not confirmed_prompt:
            raise HTTPException(status_code=400, detail="生图文案不能为空，请修改后再确认")
        decision = {
            "action": action,
            "prompt": confirmed_prompt,
            "reply": "已按你确认的文案生成。",
            "confirmed_draft_id": str(confirmed_draft.get("id") or ""),
        }
    else:
        decision = await decide_chat_agent_action(payload, conversation, image_refs)
        action = decision.get("action") or "chat"
    tool_refs = image_refs[:]
    inherited_size = ""
    if action == "edit_image" and not tool_refs:
        tool_refs = latest_chat_image_refs(conversation, 1)
        inherited_size = image_size_from_reference(tool_refs[0]) if tool_refs else ""
    if action == "edit_image" and not tool_refs:
        action = "generate_image"

    history_record = None
    if action in {"generate_image", "edit_image"}:
        draft_provider_id = str(confirmed_draft.get("image_provider") or "") if confirmed_draft else ""
        image_provider = pick_chat_image_provider(draft_provider_id or payload.image_provider or payload.provider, payload.provider)
        default_model = (image_provider.get("image_models") or [IMAGE_MODEL])[0]
        draft_model = str(confirmed_draft.get("image_model") or confirmed_draft.get("model") or "") if confirmed_draft else ""
        model = selected_model(draft_model or payload.image_model or default_model, default_model)
        prompt = decision.get("prompt") or payload.message
        base_size = str(confirmed_draft.get("size") or payload.size) if confirmed_draft else payload.size
        prompt_size = chat_prompt_size_override(payload.message, base_size) or chat_prompt_size_override(prompt, base_size)
        image_size = snap_size_to_multiple(prompt_size or inherited_size or payload.size, 16)
        if confirmed_draft:
            requested_count = max(1, min(4, int(confirmed_draft.get("image_count") or 1)))
        else:
            requested_count = 1 if action == "edit_image" else chat_requested_image_count(payload.message)
        prompts = chat_split_parallel_prompts(prompt, requested_count)
        if not confirmed_draft:
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "image_draft",
                "content": "我先把生图文案整理成可编辑草稿。请修改下面的内容；只有点击“确认生图”后才会调用图片模型。",
                "draft_prompt": prompt,
                "draft_action": action,
                "draft_status": "pending",
                "created_at": now_ms(),
                "model": model,
                "image_model": model,
                "image_provider": image_provider["id"],
                "size": image_size,
                "quality": payload.quality,
                "background": payload.background,
                "image_count": requested_count,
                "used_references": tool_refs,
                "agent_action": "image_draft",
            }
            if skill_meta:
                assistant_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
        else:
            local_urls = []
            raw_items = []
            try:
                for item_prompt in prompts:
                    image_data, raw = await generate_ai_image(item_prompt, image_size, payload.quality, model, tool_refs, image_provider["id"], "", payload.background)
                    local_urls.append(await save_ai_image_to_output(image_data, prefix="chat_"))
                    raw_items.append(raw)
            except httpx.HTTPStatusError as exc:
                text = exc.response.text or ""
                detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
                raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
            except httpx.HTTPError as exc:
                log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
                raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{exc}") from exc
            local_url = local_urls[0] if local_urls else ""
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "image",
                "content": prompt,
                "image_url": local_url,
                "image_urls": local_urls,
                "created_at": now_ms(),
                "model": model,
                "provider": image_provider["id"],
                "size": image_size,
                "background": payload.background,
                "image_count": len(local_urls),
                "prompts": prompts,
                "agent_action": action,
                "agent_reply": decision.get("reply") or "已按你确认的文案生成。",
                "used_references": tool_refs,
                "generation_draft_id": str(confirmed_draft.get("id") or ""),
                "raw_usage": raw_items[0].get("usage") if raw_items and isinstance(raw_items[0], dict) else None,
            }
            confirmed_draft.update({
                "draft_status": "generated",
                "confirmed_prompt": prompt,
                "confirmed_at": now_ms(),
            })
            history_record = chat_image_history_record(
                prompt,
                local_urls,
                model,
                image_provider,
                image_size,
                payload.quality,
                tool_refs,
                action,
                raw_items,
                payload.background,
            )
    else:
        assistant_message = await build_chat_text_reply(payload, conversation)
        assistant_message["agent_action"] = "chat"

    conversation["messages"].append(assistant_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)
    if history_record:
        save_to_history(history_record)
        if GLOBAL_LOOP:
            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(history_record), GLOBAL_LOOP)
    return {"conversation": conversation, "message": assistant_message, "agent": {"action": action, "decision": decision}}

def _merchant_require_change_conversation(change: Dict[str, Any], user_id: str) -> None:
    conversation_id = _merchant_clean_text(change.get("conversation_id"), 120)
    if not conversation_id:
        raise HTTPException(status_code=409, detail="变更缺少对话归属，无法继续操作")
    # Conversations are stored under the browser user directory.  This check
    # prevents a guessed change ID from being approved by another local user.
    load_conversation(user_id, conversation_id)


def _merchant_check_change_source(change: Dict[str, Any]) -> Tuple[bool, str]:
    job_id = str(change.get("job_id") or "").strip()
    job = _commerce_analysis_get_job(job_id) if job_id else None
    if not job or not isinstance(job.get("result"), dict):
        return False, "关联的商品快照不存在或已清理"
    current_digest = _merchant_source_digest_for_job(job)
    if not hmac.compare_digest(str(change.get("source_digest") or ""), current_digest):
        return False, "商品快照已更新，原批准已失效；请重新生成方案"
    return True, ""


def _merchant_invalidate_change(change: Dict[str, Any], reason: str) -> Dict[str, Any]:
    guardrail = dict(change.get("guardrail") if isinstance(change.get("guardrail"), dict) else {})
    guardrail["invalidated_at"] = _commerce_analysis_now()
    guardrail["invalidated_reason"] = _merchant_clean_text(reason, 300)
    return _merchant_update_change(
        change.get("id"),
        status="pending",
        approved_at=None,
        guardrail_json=_commerce_analysis_json(guardrail),
        error=_merchant_clean_text(reason, 500),
    ) or change


def _merchant_invalidate_approved_changes_for_job(job_id: str) -> int:
    """Invalidate approvals as soon as a persisted product snapshot changes."""
    safe_job_id = _merchant_job_id(job_id)
    invalidated = 0
    for change in _merchant_list_changes(job_id=safe_job_id, status="approved", limit=100):
        fresh, reason = _merchant_check_change_source(change)
        if fresh:
            continue
        _merchant_invalidate_change(change, reason)
        invalidated += 1
    return invalidated


def _merchant_apply_change(change: Dict[str, Any]) -> Dict[str, Any]:
    # Never trust a caller-held row: a recapture may have invalidated approval
    # after the caller loaded the card but before it pressed “apply”.
    stored = _merchant_get_change(change.get("id")) if isinstance(change, dict) and change.get("id") else None
    if stored:
        change = stored
    if str(change.get("status") or "") != "approved":
        raise HTTPException(status_code=409, detail="请先通过界面按钮批准该变更")
    fresh, reason = _merchant_check_change_source(change)
    if not fresh:
        _merchant_invalidate_change(change, reason)
        raise HTTPException(status_code=409, detail=reason)
    kind = str(change.get("kind") or "")
    if kind not in MERCHANT_CHANGE_KINDS:
        raise HTTPException(status_code=409, detail="变更类型不支持应用")
    updated = _merchant_update_change(change.get("id"), status="applied", applied_at=_commerce_analysis_now(), error="")
    if not updated:
        raise HTTPException(status_code=404, detail="变更不存在")
    after = updated.get("after") if isinstance(updated.get("after"), dict) else {}
    if kind == "listing_copy":
        return {"change": updated, "export": {"file_name": "小美经营助手-商品文案.md", "content": after}}
    # No platform operation is performed here.  The browser only receives a
    # small change ID and the destination fetches the approved ledger row.
    target = "commerce"
    return {"change": updated, "handoff": {"target": target, "change_id": updated.get("id"), "kind": kind}}


@app.get("/api/merchant-agent/changes")
async def merchant_agent_changes(
    request: Request,
    conversation_id: str = "",
    job_id: str = "",
    status: str = "",
    limit: int = 50,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    safe_conversation = _merchant_clean_text(conversation_id, 120)
    if safe_conversation:
        load_conversation(user_id, safe_conversation)
    changes = await asyncio.to_thread(_merchant_list_changes, safe_conversation, job_id, status, limit)
    # A list without a conversation filter is retained for the single-local-user
    # history view; mutation endpoints always verify the conversation owner.
    return {"changes": changes}


@app.get("/api/merchant-agent/changes/{change_id}")
async def merchant_agent_change(change_id: str, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    return {"change": change}


@app.post("/api/merchant-agent/changes/{change_id}/approve")
async def merchant_agent_approve_change(
    change_id: str,
    payload: MerchantChangeApprovalRequest,
    request: Request,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    if change.get("status") == "approved":
        return {"change": change}
    if change.get("status") != "pending":
        raise HTTPException(status_code=409, detail="只有待确认变更可以批准")
    fresh, reason = await asyncio.to_thread(_merchant_check_change_source, change)
    if not fresh:
        await asyncio.to_thread(_merchant_invalidate_change, change, reason)
        raise HTTPException(status_code=409, detail=reason)
    guardrail = dict(change.get("guardrail") if isinstance(change.get("guardrail"), dict) else {})
    note = _merchant_clean_text(payload.note, 1000)
    if note:
        guardrail["approval_note"] = note
    guardrail["approved_via"] = "ui_button"
    updated = await asyncio.to_thread(
        _merchant_update_change,
        change.get("id"),
        status="approved",
        approved_at=_commerce_analysis_now(),
        guardrail_json=_commerce_analysis_json(guardrail),
        error="",
    )
    return {"change": updated}


@app.post("/api/merchant-agent/changes/{change_id}/apply")
async def merchant_agent_apply_change(change_id: str, request: Request, x_user_id: str = Header(default="")):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    return await asyncio.to_thread(_merchant_apply_change, change)


@app.post("/api/merchant-agent/changes/{change_id}/discard")
async def merchant_agent_discard_change(
    change_id: str,
    payload: MerchantChangeDiscardRequest,
    request: Request,
    x_user_id: str = Header(default=""),
):
    user_id = safe_user_id(x_user_id, request)
    change = await asyncio.to_thread(_merchant_get_change, change_id)
    if not change:
        raise HTTPException(status_code=404, detail="变更不存在")
    _merchant_require_change_conversation(change, user_id)
    if change.get("status") not in {"pending", "approved"}:
        raise HTTPException(status_code=409, detail="当前变更不能丢弃")
    reason = _merchant_clean_text(payload.reason, 1000)
    updated = await asyncio.to_thread(
        _merchant_update_change,
        change.get("id"),
        status="discarded",
        error=reason,
    )
    return {"change": updated}


@app.post("/api/chat/stream")
async def chat_stream(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    if payload.mode == "image":
        raise HTTPException(status_code=400, detail="图片模式请使用 /api/chat")

    user_id = safe_user_id(x_user_id, request)
    merchant_mode = str(payload.mode or "").strip().lower() == "merchant-agent"
    if merchant_mode:
        # Accept the human-facing aliases in the Merchant contract while
        # preserving the existing product-analysis resource IDs internally.
        payload.link_resource_ids = sorted(_merchant_resource_ids(payload.link_resource_ids))
    # Merchant Agent is intentionally local-snapshot only.  Do not let a URL
    # pasted into chat trigger the generic public-web reader on this route.
    context_message = re.sub(r"https?://[^\s<>]+", "", payload.message) if merchant_mode else payload.message
    link_context = await _prepare_link_context(
        context_message,
        [],
        payload.link_job_ids,
        payload.link_resource_ids,
        {} if merchant_mode else payload.page_context,
    )
    if merchant_mode and not link_context.get("job_ids"):
        raise HTTPException(status_code=409, detail="经营助手需要先完成并关联一个商品分析任务")
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    remove_failed_chat_message(conversation, payload)
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    page_context_source = str((link_context.get("page_context") or {}).get("source") or "").strip()
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": payload.mode,
    }
    if merchant_mode and link_context.get("job_ids"):
        # Merchant Agent never receives the full product snapshot through the
        # chat prompt.  It can only fetch bounded pieces through the server's
        # audited read-tool layer below.
        user_message.update({
            "link_job_ids": link_context.get("job_ids", []),
            "link_resource_ids": link_context.get("resource_ids", []),
            "merchant_agent": True,
        })
    elif link_context.get("context_text") or link_context.get("job_ids"):
        user_message.update({
            "link_job_ids": link_context.get("job_ids", []),
            "link_resource_ids": link_context.get("resource_ids", []),
            "link_urls": [
                str(item.get("original_url") or item.get("final_url") or "").strip()
                for item in (link_context.get("links") or [])
                if str(item.get("original_url") or item.get("final_url") or "").strip()
            ],
            "link_context": link_context.get("context_text") or "",
            "link_images": link_context.get("images", [])[:CHAT_ATTACHMENT_MAX],
            "link_page_context_source": page_context_source,
        })
    skill_meta = public_agent_skill(payload)
    if skill_meta:
        user_message.update({"skill_id": skill_meta["id"], "skill_name": skill_meta["name"]})
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    if merchant_mode:
        async def merchant_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                result = await _run_merchant_agent_turn(payload, conversation, link_context)
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            except httpx.HTTPStatusError as exc:
                body = exc.response.text or ""
                provider_cfg = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
                yield sse_event({"type": "error", "detail": friendly_chat_error_detail(body, payload.model, provider_cfg, exc.response.status_code) or f"上游接口错误：{body[:500]}"})
                return
            except httpx.TimeoutException:
                yield sse_event({"type": "error", "detail": "经营助手的模型响应超时，请重试或切换聊天模型"})
                return
            except httpx.HTTPError as exc:
                yield sse_event({"type": "error", "detail": f"经营助手请求上游接口失败：{str(exc)[:300]}"})
                return
            for event in result.get("events") if isinstance(result.get("events"), list) else []:
                yield sse_event(event)
            content = str(result.get("content") or "已完成本次经营分析。")
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "merchant_agent",
                "content": content,
                "created_at": now_ms(),
                "model": result.get("model") or payload.model,
                "raw_usage": result.get("raw_usage"),
                "merchant_changes": result.get("changes") if isinstance(result.get("changes"), list) else [],
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": content})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(merchant_stream(), media_type="text/event-stream")

    _codex_provider = get_api_provider(payload.provider)
    if is_codex_provider(_codex_provider):
        model = selected_model(payload.model, (_codex_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        payload.model = model

        async def codex_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                text, raw = await codex_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": text})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(codex_stream(), media_type="text/event-stream")

    if is_gemini_cli_provider(_codex_provider):
        model = selected_model(payload.model, (_codex_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        payload.model = model

        async def gemini_cli_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                text, raw = await gemini_cli_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": text})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(gemini_cli_stream(), media_type="text/event-stream")

    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    _stream_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    history = conversation["messages"][-MAX_HISTORY_MESSAGES:]
    upstream_messages = [{"role": "system", "content": chat_system_prompt(payload)}]
    for item in history:
        msg = upstream_message_from_record(item)
        if msg:
            upstream_messages.append(msg)
    stream_timeout = chat_stream_timeout_for_payload(payload)

    async def stream():
        yield sse_event({"type": "meta", "conversation": conversation})
        stream_deadline = time.monotonic() + stream_timeout
        commerce_chat_mode = str(payload.mode or "").strip().lower() == "commerce-analysis"
        first_token_deadline = (
            time.monotonic() + COMMERCE_CHAT_FIRST_TOKEN_TIMEOUT
            if commerce_chat_mode
            else None
        )
        max_retries = CHAT_AGENT_RETRIES
        attempt = 0
        content_parts = []
        raw_usage = None
        upstream_completed = False
        while True:
            attempt_parts = []
            attempt_usage = None
            attempt_completed = False
            retry_requested = False
            try:
                async with httpx.AsyncClient(timeout=chat_agent_http_timeout(stream_timeout)) as client:
                    async with client.stream(
                        "POST",
                        f"{chat_base}/chat/completions",
                        headers=chat_hdrs,
                        json={"model": model, "messages": upstream_messages, "stream": True},
                    ) as response:
                        if response.status_code >= 400:
                            detail = await response.aread()
                            body = detail.decode("utf-8", errors="ignore")
                            if (
                                not content_parts
                                and is_transient_chat_error(body, response.status_code)
                                and attempt < max_retries
                            ):
                                retry_requested = True
                            else:
                                friendly = friendly_chat_error_detail(body, model, _stream_provider, response.status_code)
                                yield sse_event({"type": "error", "detail": friendly or f"上游接口错误：{body}"})
                                return
                        else:
                            line_iterator = response.aiter_lines().__aiter__()
                            while True:
                                waiting_for_first_token = False
                                if first_token_deadline is not None and not content_parts:
                                    first_token_remaining = first_token_deadline - time.monotonic()
                                    if first_token_remaining <= 0:
                                        raise CommerceChatFirstTokenTimeout
                                    waiting_for_first_token = True
                                remaining = stream_deadline - time.monotonic()
                                if remaining <= 0:
                                    raise asyncio.TimeoutError
                                if waiting_for_first_token:
                                    remaining = min(remaining, first_token_remaining)
                                try:
                                    line = await asyncio.wait_for(line_iterator.__anext__(), timeout=remaining)
                                except asyncio.TimeoutError as exc:
                                    if waiting_for_first_token and not content_parts:
                                        raise CommerceChatFirstTokenTimeout from exc
                                    raise
                                except StopAsyncIteration:
                                    # 兼容部分代理在完整内容后直接关闭 SSE，而不发送 [DONE]。
                                    # 有内容时按正常结束处理；空流仍会在下面显示明确错误。
                                    attempt_completed = True
                                    break
                                if not line:
                                    continue
                                if line.startswith("data:"):
                                    line = line[5:].strip()
                                if line == "[DONE]":
                                    attempt_completed = True
                                    break
                                try:
                                    chunk = json.loads(line)
                                except json.JSONDecodeError:
                                    # 少数中转在 200 响应的 SSE 中直接写入 "network error"；
                                    # 不要把它静默丢弃后误报成空回复。
                                    if line and is_transient_chat_error(line, response.status_code):
                                        retry_requested = not content_parts and attempt < max_retries
                                        if not retry_requested:
                                            yield sse_event({"type": "error", "detail": line[:500]})
                                            return
                                    continue
                                if isinstance(chunk, dict) and chunk.get("usage"):
                                    attempt_usage = chunk.get("usage")
                                if isinstance(chunk, dict) and chunk.get("error"):
                                    error_body = json.dumps(chunk, ensure_ascii=False)
                                    if not content_parts and is_transient_chat_error(error_body, response.status_code) and attempt < max_retries:
                                        retry_requested = True
                                        break
                                    error = chunk.get("error")
                                    detail = error.get("message") if isinstance(error, dict) else str(error)
                                    yield sse_event({"type": "error", "detail": detail or "上游接口返回了错误"})
                                    return
                                delta = text_delta_from_chat_chunk(chunk)
                                if delta:
                                    attempt_parts.append(delta)
                                    content_parts.append(delta)
                                    yield sse_event({"type": "delta", "delta": delta})
                            if not retry_requested and not attempt_completed:
                                upstream_completed = False
            except CommerceChatFirstTokenTimeout:
                yield sse_event({
                    "type": "error",
                    "detail": f"聊天模型在 {COMMERCE_CHAT_FIRST_TOKEN_TIMEOUT:g} 秒内没有返回首段文字，已自动停止；请减少详情图片引用或切换聊天模型后重试",
                })
                return
            except asyncio.TimeoutError:
                yield sse_event({
                    "type": "error",
                    "detail": f"聊天模型在 {stream_timeout:g} 秒内没有完成回复，已自动停止；请重试或切换聊天模型",
                })
                return
            except httpx.TimeoutException as exc:
                log_net_error("对话(流式) 超时", exc)
                if (
                    commerce_chat_mode
                    and first_token_deadline is not None
                    and not content_parts
                    and time.monotonic() >= first_token_deadline
                ):
                    detail = f"聊天模型在 {COMMERCE_CHAT_FIRST_TOKEN_TIMEOUT:g} 秒内没有返回首段文字，已自动停止；请减少详情图片引用或切换聊天模型后重试"
                else:
                    detail = f"聊天模型响应超过 {stream_timeout:g} 秒，已自动停止；请重试或切换聊天模型"
                yield sse_event({
                    "type": "error",
                    "detail": detail,
                })
                return
            except httpx.HTTPError as exc:
                # 只有尚未向浏览器发出任何文字时才重试，避免重复拼接半截回复。
                if not content_parts and attempt < max_retries and time.monotonic() < stream_deadline:
                    retry_requested = True
                    log_net_error(
                        f"对话(流式) 临时网络/TLS错误，准备重试 {attempt + 1}/{max_retries}",
                        exc,
                    )
                else:
                    log_net_error("对话(流式) 网络/TLS错误", exc)
                    yield sse_event({"type": "error", "detail": f"请求上游接口失败：{exc}"})
                    return

            if retry_requested:
                delay = min(8.0, CHAT_AGENT_RETRY_DELAY * (attempt + 1))
                remaining = stream_deadline - time.monotonic()
                if remaining <= delay:
                    yield sse_event({
                        "type": "error",
                        "detail": f"聊天模型在 {stream_timeout:g} 秒内没有完成回复，已自动停止；请重试或切换聊天模型",
                    })
                    return
                print(
                    f"[chat-stream] retry provider={payload.provider} model={model} "
                    f"attempt={attempt + 1}/{max_retries} delay={delay:g}s",
                    flush=True,
                )
                await asyncio.sleep(delay)
                attempt += 1
                continue

            if attempt_parts:
                raw_usage = attempt_usage or raw_usage
            upstream_completed = attempt_completed
            break

        if not upstream_completed:
            yield sse_event({"type": "error", "detail": "上游接口在回复完成前结束了连接，请重试或切换聊天模型"})
            return
        if not content_parts:
            yield sse_event({"type": "error", "detail": "上游接口在返回文字前结束了连接，请重试或切换聊天模型"})
            return

        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": "".join(content_parts).strip() or "接口返回了空回复。",
            "created_at": now_ms(),
            "model": model,
            "raw_usage": raw_usage,
        }
        conversation["messages"].append(assistant_message)
        conversation["updated_at"] = now_ms()
        save_conversation(user_id, conversation)
        yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

    return StreamingResponse(stream(), media_type="text/event-stream")

# --- 历史记录 ---

def _history_values(value):
    if isinstance(value, list):
        return value
    return [value] if value else []


def _history_media_url(value):
    if isinstance(value, dict):
        return str(value.get("url") or value.get("src") or value.get("path") or value.get("uri") or "").strip()
    return str(value or "").strip()


def history_record_has_display_media(record):
    if not isinstance(record, dict):
        return False
    for key in ("images", "videos", "outputs"):
        if any(_history_media_url(value) for value in _history_values(record.get(key))):
            return True
    for key in ("image_items", "video_items", "items", "media_items"):
        for item in _history_values(record.get(key)):
            if _history_media_url(item):
                return True
    return False


def history_record_media_urls(record):
    if not isinstance(record, dict):
        return []
    urls = []
    seen = set()

    def add(value):
        url = _history_media_url(value)
        if url and url not in seen:
            seen.add(url)
            urls.append(url)

    for key in ("images", "videos", "outputs"):
        for value in _history_values(record.get(key)):
            add(value)
    for key in ("image_items", "video_items", "items", "media_items"):
        for value in _history_values(record.get(key)):
            if isinstance(value, dict):
                add(value)
    return urls


def _history_media_key(value):
    """Normalize a media URL enough to match history rows to canvas nodes."""
    text = _history_media_url(value).replace("\\", "/")
    if not text:
        return ""
    try:
        parsed = urllib.parse.urlsplit(text)
        # A local browser may persist an absolute loopback URL while the canvas
        # stores the same file as a relative route.  Keep external URLs
        # host-qualified so two providers cannot collide on a path alone.
        if parsed.scheme and parsed.netloc and parsed.hostname in {"127.0.0.1", "localhost", "::1"}:
            text = parsed.path or "/"
        else:
            text = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path, "", ""))
    except Exception:
        text = text.split("?", 1)[0].split("#", 1)[0]
    return text.rstrip("/") or "/"


def _history_project_ids_from_value(value):
    if isinstance(value, (list, tuple, set)):
        values = value
    else:
        values = [value]
    result = set()
    for item in values:
        project_id = str(item or "").strip()
        if project_id:
            result.add(project_id)
    return result


def _history_project_ids(record, canvas_media_index=None):
    """Return explicit and legacy-inferred project IDs for one history row."""
    if not isinstance(record, dict):
        return set()
    params = record.get("params") if isinstance(record.get("params"), dict) else {}
    project_ids = set()
    for value in (
        record.get("project_id"),
        record.get("project"),
        params.get("project_id"),
        params.get("project"),
    ):
        project_ids.update(_history_project_ids_from_value(value))
    if isinstance(canvas_media_index, dict):
        for url in history_record_media_urls(record):
            project_ids.update(canvas_media_index.get(_history_media_key(url), set()))
    return project_ids


def _history_canvas_project_media_index():
    """Build a read-only URL -> project index for history rows from old builds."""
    index = {}
    if not os.path.isdir(CANVAS_DIR):
        return index
    try:
        filenames = os.listdir(CANVAS_DIR)
    except OSError:
        return index
    for filename in filenames:
        if not str(filename).endswith(".json"):
            continue
        try:
            with open(os.path.join(CANVAS_DIR, filename), "r", encoding="utf-8") as f:
                canvas = json.load(f)
        except Exception:
            continue
        if not isinstance(canvas, dict) or canvas.get("deleted_at"):
            continue
        project_id = str(canvas.get("project") or DEFAULT_PROJECT_ID).strip() or DEFAULT_PROJECT_ID
        values = (
            canvas.get("nodes"),
            canvas.get("logs"),
            canvas.get("history"),
            canvas.get("assets"),
            canvas.get("outputs"),
        )
        for value in values:
            for _path, _raw, url in iter_canvas_asset_values(value):
                key = _history_media_key(url)
                if key:
                    index.setdefault(key, set()).add(project_id)
    return index


def _history_listing_media(record):
    """Return the small, normalized media shape used by the history manager.

    The persisted history rows also contain provider payloads, usage details and
    compatibility fields.  The manager only needs a URL, media kind and an
    optional filename; keeping that boundary here prevents the large history
    file from being sent to the browser just to render thumbnails.
    """
    if not isinstance(record, dict):
        return []
    entries = []
    seen = set()
    video_exts = {ext.lower() for ext in STORAGE_VIDEO_EXTS}

    def add(value, fallback="image"):
        if isinstance(value, list):
            for item in value:
                add(item, fallback)
            return
        if isinstance(value, dict):
            url = _history_media_url(value)
            hinted = str(value.get("kind") or value.get("mediaKind") or value.get("type") or "").strip().lower()
            name = str(value.get("name") or value.get("filename") or "").strip()
        else:
            url = _history_media_url(value)
            hinted = ""
            name = ""
        if not url or url in seen:
            return
        seen.add(url)
        is_video = "video" in hinted or os.path.splitext(url.split("?", 1)[0])[1].lower() in video_exts
        entries.append({"url": url, "kind": "video" if is_video else (fallback or "image"), **({"name": name} if name else {})})

    # Keep the same ordering as history.html so old and compact responses are
    # interchangeable while duplicate URL fields collapse to one entry.
    add(record.get("video_items"), "video")
    add(record.get("videos"), "video")
    add(record.get("items"), "")
    add(record.get("media_items"), "")
    add(record.get("image_items"), "image")
    add(record.get("images"), "image")
    add(record.get("outputs"), "")
    return entries


def _history_listing_group(record, media):
    if not isinstance(record, dict):
        return "other"
    if any(item.get("kind") == "video" for item in media):
        return "video"
    raw_type = str(record.get("type") or "").strip().lower()
    source = str(
        record.get("history_source")
        or record.get("source")
        or ((record.get("params") or {}).get("history_source") if isinstance(record.get("params"), dict) else "")
        or ((record.get("params") or {}).get("source") if isinstance(record.get("params"), dict) else "")
        or ""
    ).strip().lower().replace("-", "_").replace(" ", "_")
    if source in {"comfyui", "comfy_ui", "comfy_app", "comfyui_workbench"} or raw_type in {
        "comfyui", "comfy_ui", "comfy_app", "comfy-app"
    }:
        return "comfyui"
    if source in {"online", "online_image"} or raw_type == "online":
        return "online"
    if source in {"chat", "gpt_chat", "gpt"} or raw_type in {"chat", "gpt-chat", "gpt_chat"}:
        return "chat"
    if source in {"canvas", "smart_canvas"} or raw_type == "canvas" or "canvas" in raw_type:
        return "canvas"
    if source in {"commerce", "commerce_workbench", "ecommerce"} or raw_type == "commerce" or "commerce" in raw_type:
        return "commerce"
    if record.get("workflow_json") or record.get("prompt_id") or record.get("backend"):
        return "canvas"
    return "other"


def _history_listing_item(record, canvas_media_index=None):
    media = _history_listing_media(record)
    params = record.get("params") if isinstance(record.get("params"), dict) else {}
    source = str(record.get("history_source") or record.get("source") or "").strip()
    project_ids = sorted(_history_project_ids(record, canvas_media_index))
    history_group = _history_listing_group(record, media)
    if history_group == "comfyui":
        source = "comfyui"
    compact = {
        "prompt": str(record.get("prompt") or ""),
        "timestamp": record.get("timestamp", 0),
        "type": str(record.get("type") or ""),
        "history_source": source,
        "model": str(record.get("model") or params.get("model") or ""),
        "provider_name": str(record.get("provider_name") or ""),
        "status": str(record.get("status") or ""),
        "state": str(record.get("state") or ""),
        "result": str(record.get("result") or ""),
        "error": str(record.get("error") or ""),
        "error_message": str(record.get("error_message") or ""),
        "message": str(record.get("message") or ""),
        "media_items": media,
        "media_count": len(media),
        "has_video": any(item.get("kind") == "video" for item in media),
        "project_id": project_ids[0] if len(project_ids) == 1 else "",
        "project_ids": project_ids,
    }
    compact["history_group"] = history_group
    compact["params"] = {
        "source": str(params.get("source") or params.get("history_source") or "").strip(),
        "model": str(params.get("model") or "").strip(),
        "project_id": project_ids[0] if len(project_ids) == 1 else "",
    }
    return compact


@app.get("/api/history")
async def get_history_api(type: str = None, view: str = "", project_id: str = ""):
    requested_project_id = str(project_id or "").strip()
    if os.path.exists(HISTORY_FILE):
        try:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
                if not isinstance(data, list):
                    data = []
                data = [item for item in data if isinstance(item, dict)]
                if type:
                    data = [item for item in data if item.get("type", "zimage") == type]
                data = [item for item in data if history_record_has_display_media(item)]
                manager_view = str(view or "").strip().lower() == "manager"
                canvas_media_index = _history_canvas_project_media_index() if (manager_view or requested_project_id) else None
                if requested_project_id:
                    data = [
                        item for item in data
                        if requested_project_id in _history_project_ids(item, canvas_media_index)
                    ]

                def sort_key(item):
                    ts = item.get("timestamp", 0)
                    if isinstance(ts, (int, float)):
                        return float(ts)
                    return 0

                data.sort(key=sort_key, reverse=True)
                if manager_view:
                    return [_history_listing_item(item, canvas_media_index) for item in data]
                return data
        except Exception as e:
            print(f"读取历史文件失败: {e}")
            return []
    return []

@app.get("/api/queue_status")
async def get_queue_status(client_id: str):
    with QUEUE_LOCK:
        total = len(QUEUE)
        positions = [i + 1 for i, t in enumerate(QUEUE) if t["client_id"] == client_id]
        position = positions[0] if positions else 0
    return {"total": total, "position": position}

@app.post("/api/history/delete")
async def delete_history(req: DeleteHistoryRequest):
    if not os.path.exists(HISTORY_FILE):
        return {"success": False, "message": "历史记录文件不存在"}
    try:
        with HISTORY_LOCK:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                history = json.load(f)
            target_record = None
            new_history = []
            for item in history:
                is_match = False
                item_ts = item.get("timestamp", 0)
                if isinstance(req.timestamp, (int, float)) and isinstance(item_ts, (int, float)):
                    if abs(float(item_ts) - float(req.timestamp)) < 0.001:
                        is_match = True
                elif str(item_ts) == str(req.timestamp):
                    is_match = True
                if is_match:
                    target_record = item
                else:
                    new_history.append(item)
            if target_record:
                # Register legacy media before removing its only history row.
                # The reference check below then sees the remaining canvases
                # and history records rather than deleting a shared file.
                asset_registry_register_history_record(target_record)
                with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
                    json.dump(new_history, f, ensure_ascii=False, indent=4)

        if target_record:
            trashed_asset_ids = []
            retained_asset_ids = []
            seen_asset_ids = set()
            for ref in target_record.get("asset_refs") if isinstance(target_record.get("asset_refs"), list) else []:
                if not isinstance(ref, dict):
                    continue
                asset_id = str(ref.get("asset_id") or "")
                if not registry_is_asset_id(asset_id) or asset_id in seen_asset_ids:
                    continue
                seen_asset_ids.add(asset_id)
                try:
                    if asset_registry_reference_summary(asset_id)["total"]:
                        retained_asset_ids.append(asset_id)
                    else:
                        _asset_registry_trash_media(asset_id, reason="history_delete")
                        trashed_asset_ids.append(asset_id)
                except Exception as exc:
                    # The history entry is already gone.  Keep the source file
                    # if its registry transition fails so deletion remains
                    # recoverable instead of becoming an accidental purge.
                    print(f"历史素材回收处理失败 ({asset_id}): {exc}")
                    retained_asset_ids.append(asset_id)
            return {
                "success": True,
                "trashed_asset_ids": trashed_asset_ids,
                "retained_asset_ids": retained_asset_ids,
                "message": "历史记录已删除；仍被引用的素材已保留" if retained_asset_ids else "历史记录及未引用素材已移入回收站",
            }
        else:
            return {"success": False, "message": "未找到对应的历史记录"}
    except Exception as e:
        print(f"Delete history error: {e}")
        return {"success": False, "message": str(e)}


def _delete_history_batch_sync(raw_timestamps):
    """Delete selected history rows with one history-file rewrite.

    The manager can select thousands of rows.  Sending one request per row
    would make every request parse and rewrite the same multi-megabyte JSON
    file, so batch the file mutation while preserving the existing asset
    reference/recycle-bin checks for each removed row.
    """
    raw_timestamps = list(raw_timestamps or [])
    if not raw_timestamps:
        return {"success": False, "message": "未选择历史记录"}
    if len(raw_timestamps) > 5000:
        raise HTTPException(status_code=400, detail="一次最多删除 5000 条历史记录")
    targets = {float(value) for value in raw_timestamps}
    if not os.path.exists(HISTORY_FILE):
        return {"success": False, "message": "历史记录文件不存在"}
    try:
        target_records = []
        with HISTORY_LOCK:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                history = json.load(f)
            new_history = []
            for item in history if isinstance(history, list) else []:
                item_ts = item.get("timestamp", 0) if isinstance(item, dict) else 0
                matched = False
                try:
                    matched = any(abs(float(item_ts) - timestamp) < 0.001 for timestamp in targets)
                except (TypeError, ValueError):
                    matched = False
                if matched:
                    target_records.append(item)
                else:
                    new_history.append(item)
            if not target_records:
                return {"success": False, "message": "未找到对应的历史记录"}
            for target_record in target_records:
                asset_registry_register_history_record(target_record)
            with open(HISTORY_FILE, 'w', encoding='utf-8') as f:
                json.dump(new_history, f, ensure_ascii=False, indent=4)

        trashed_asset_ids = []
        retained_asset_ids = []
        seen_asset_ids = set()
        for target_record in target_records:
            refs = target_record.get("asset_refs") if isinstance(target_record, dict) else []
            for ref in refs if isinstance(refs, list) else []:
                if not isinstance(ref, dict):
                    continue
                asset_id = str(ref.get("asset_id") or "")
                if not registry_is_asset_id(asset_id) or asset_id in seen_asset_ids:
                    continue
                seen_asset_ids.add(asset_id)
                try:
                    if asset_registry_reference_summary(asset_id)["total"]:
                        retained_asset_ids.append(asset_id)
                    else:
                        _asset_registry_trash_media(asset_id, reason="history_delete")
                        trashed_asset_ids.append(asset_id)
                except Exception as exc:
                    print(f"历史素材回收处理失败 ({asset_id}): {exc}")
                    retained_asset_ids.append(asset_id)
        return {
            "success": True,
            "deleted": len(target_records),
            "trashed_asset_ids": trashed_asset_ids,
            "retained_asset_ids": retained_asset_ids,
            "message": f"已删除 {len(target_records)} 条历史记录",
        }
    except HTTPException:
        raise
    except Exception as e:
        print(f"Batch delete history error: {e}")
        return {"success": False, "message": str(e)}


@app.post("/api/history/delete-batch")
async def delete_history_batch(req: DeleteHistoryBatchRequest):
    # File and asset-registry operations are synchronous. Keep large batches
    # off the event loop so the rest of the local app can still load and respond.
    return await asyncio.to_thread(_delete_history_batch_sync, req.timestamps)

# --- ModelScope 角度控制 ---

@app.post("/api/angle/poll_status")
async def poll_angle_cloud(req: CloudPollRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    task_id = req.task_id
    print(f"Resuming polling for Angle Task: {task_id}")

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            for i in range(300):
                await asyncio.sleep(2)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient() as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                local_path, _path = save_generated_image_bytes(
                                    img_res.content,
                                    prefix="cloud_angle_",
                                    fallback_extension=image_fallback_extension(
                                        img_url,
                                        img_res.headers.get("Content-Type", ""),
                                    ),
                                )
                            else:
                                local_path = img_url
                    except Exception:
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": f"Resumed {task_id}", "images": [local_path], "type": "angle"}
                    save_to_history(record)
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "SUCCEED", "task_id": task_id}, req.client_id)
                    return {"url": local_path}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "FAILED", "task_id": task_id}, req.client_id)
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

                if req.client_id:
                    await manager.send_personal_message({
                        "type": "cloud_status", "status": f"{status} ({i}/300)",
                        "task_id": task_id, "progress": i, "total": 300
                    }, req.client_id)

            if req.client_id:
                await manager.send_personal_message({"type": "cloud_status", "status": "TIMEOUT", "task_id": task_id}, req.client_id)
            return {"status": "timeout", "task_id": task_id, "message": "Task still pending"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Angle polling error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

@app.post("/api/angle/generate")
async def generate_angle_cloud(req: CloudGenRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    model = selected_model(req.model, "Qwen/Qwen-Image-Edit-2511")
    payload = {
        "model": model,
        "prompt": req.prompt.strip(),
        "image_url": [modelscope_image_url(url, max_size=1536) for url in req.image_urls]
    }
    if req.resolution:
        payload["size"] = modelscope_size(req.resolution)
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            submit_res = await client.post(f"{api_root}/images/generations", headers=headers, json=payload)
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"Angle Task submitted, ID: {task_id}")

            for i in range(300):
                await asyncio.sleep(2)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient() as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                local_path, _path = save_generated_image_bytes(
                                    img_res.content,
                                    prefix="cloud_angle_",
                                    fallback_extension=image_fallback_extension(
                                        img_url,
                                        img_res.headers.get("Content-Type", ""),
                                    ),
                                )
                            else:
                                local_path = img_url
                    except Exception:
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": req.prompt, "images": [local_path], "type": "angle"}
                    save_to_history(record)
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "SUCCEED", "task_id": task_id}, req.client_id)
                    if GLOBAL_LOOP:
                        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(record), GLOBAL_LOOP)
                    return {"url": local_path, "task_id": task_id}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "FAILED", "task_id": task_id}, req.client_id)
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

                if req.client_id:
                    await manager.send_personal_message({
                        "type": "cloud_status", "status": f"{status} ({i}/300)",
                        "task_id": task_id, "progress": i, "total": 300
                    }, req.client_id)

            if req.client_id:
                await manager.send_personal_message({"type": "cloud_status", "status": "TIMEOUT", "task_id": task_id}, req.client_id)
            return {"status": "timeout", "task_id": task_id, "message": "Task still pending"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Angle generation error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- ModelScope Z-Image 云端生图 ---

@app.post("/generate")
async def generate_cloud(req: CloudGenRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "Tongyi-MAI/Z-Image-Turbo",
        "prompt": req.prompt.strip(),
        "size": modelscope_size(req.resolution),
        "n": 1
    }
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            submit_res = await client.post(
                f"{api_root}/images/generations",
                headers={**headers, "X-ModelScope-Async-Mode": "true"},
                json=payload
            )
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"Z-Image Task submitted, ID: {task_id}")

            for i in range(200):
                await asyncio.sleep(3)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if i % 5 == 0:
                    print(f"Task {task_id} status check {i}: {status}")

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient() as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                local_path, _path = save_generated_image_bytes(
                                    img_res.content,
                                    prefix="cloud_",
                                    fallback_extension=image_fallback_extension(
                                        img_url,
                                        img_res.headers.get("Content-Type", ""),
                                    ),
                                )
                            else:
                                local_path = img_url
                    except Exception as dl_e:
                        print(f"Download error: {dl_e}")
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": req.prompt, "images": [local_path], "type": "cloud"}
                    save_to_history(record)
                    try:
                        await manager.broadcast_new_image(record)
                    except Exception:
                        pass
                    return {"url": local_path}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

            raise Exception("Cloud generation timeout")

    except HTTPException:
        raise
    except Exception as e:
        print(f"Cloud generation error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- ModelScope 通用图片生成（支持图生图） ---

@app.post("/api/ms/generate")
async def ms_generate(req: MsGenerateRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未配置 ModelScope API Key，请在 API 设置中填写，或重新保存 ModelScope Token。")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    payload = {
        "model": req.model,
        "prompt": req.prompt.strip(),
    }
    if req.width and req.height:
        payload["width"] = req.width
        payload["height"] = req.height
        payload["size"] = modelscope_size(req.size or f"{req.width}x{req.height}")
    elif req.size:
        payload["size"] = modelscope_size(req.size)
    if req.image_urls:
        payload["image_url"] = [modelscope_image_url(url, max_size=1536) for url in req.image_urls]
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            submit_res = await client.post(
                f"{api_root}/images/generations",
                headers=headers,
                json=payload
            )
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"MS Generate Task submitted ({req.model}), ID: {task_id}")

            TERMINAL_FAILED_STATUSES = {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}

            for i in range(300):
                await asyncio.sleep(2)
                try:
                    result = await client.get(
                        f"{api_root}/tasks/{task_id}",
                        headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                    )
                    data = result.json()
                    status = data.get("task_status")
                    print(f"MS Task {task_id} poll {i}: status={status}")

                    if status == "SUCCEED":
                        img_url = data["output_images"][0]
                        local_path = ""
                        try:
                            async with httpx.AsyncClient() as dl_client:
                                img_res = await dl_client.get(img_url)
                                if img_res.status_code == 200:
                                    model_prefix = re.sub(r"[^A-Za-z0-9_-]+", "_", str(req.model or "ms")).strip("_") or "ms"
                                    local_path, _path = save_generated_image_bytes(
                                        img_res.content,
                                        prefix=f"ms_{model_prefix}_",
                                        fallback_extension=image_fallback_extension(
                                            img_url,
                                            img_res.headers.get("Content-Type", ""),
                                        ),
                                    )
                                else:
                                    local_path = img_url
                        except Exception:
                            local_path = img_url

                        record = {
                            "timestamp": time.time(),
                            "prompt": req.prompt,
                            "images": [local_path],
                            "type": "klein",
                            "model": req.model,
                        }
                        save_to_history(record)
                        if GLOBAL_LOOP:
                            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(record), GLOBAL_LOOP)
                        return {"url": local_path, "task_id": task_id}

                    elif status in TERMINAL_FAILED_STATUSES:
                        error_info = data.get("error_info") or data.get("message") or data.get("detail") or str(data)
                        raise HTTPException(status_code=502, detail=f"MS task {status}: {error_info}")

                except HTTPException:
                    raise
                except Exception as loop_e:
                    print(f"MS polling error: {loop_e}")
                    continue

            raise HTTPException(status_code=504, detail="MS 生图超时")

    except HTTPException:
        raise
    except Exception as e:
        print(f"MS generate error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- 本地 ComfyUI 生图 ---

@app.post("/api/generate")
def generate(req: GenerateRequest):
    global NEXT_TASK_ID
    current_task = None
    target_backend = None
    with QUEUE_LOCK:
        task_id = NEXT_TASK_ID
        NEXT_TASK_ID += 1
        current_task = {"task_id": task_id, "client_id": req.client_id}
        QUEUE.append(current_task)

    try:
        required_images = collect_required_comfy_media(req.params)

        requested_backend = str(req.preferred_backend or "").strip()
        managed_backend = globals().get('COMFY_APPS') and requested_backend == COMFY_APPS.runtime.address
        if req.local_only and ((requested_backend not in COMFYUI_INSTANCES and not managed_backend) or not re.fullmatch(r"(?:127\.0\.0\.1|localhost):\d+", requested_backend)):
            raise ValueError("本地应用只能提交到已配置的本机 ComfyUI，不会转交云端")
        if requested_backend in COMFYUI_INSTANCES or (req.local_only and managed_backend):
            target_backend = requested_backend
            with LOAD_LOCK:
                BACKEND_LOCAL_LOAD[target_backend] = BACKEND_LOCAL_LOAD.get(target_backend, 0) + 1
        else:
            target_backend = reserve_best_backend(required_images)

        for image_name in required_images:
            need_sync = False
            try:
                check_url = f"http://{target_backend}/view?filename={urllib.parse.quote(image_name)}&type=input"
                resp = requests.get(check_url, stream=True, timeout=0.5)
                resp.close()
                if resp.status_code != 200:
                    need_sync = True
            except:
                need_sync = True

            if need_sync:
                image_content = None
                image_type = "image/png"
                for addr in ([] if req.local_only else COMFYUI_INSTANCES):
                    if addr == target_backend: continue
                    try:
                        src_url = f"http://{addr}/view?filename={urllib.parse.quote(image_name)}&type=input"
                        r = requests.get(src_url, timeout=5)
                        if r.status_code == 200:
                            image_content = r.content
                            image_type = r.headers.get("Content-Type", "image/png")
                            break
                    except: continue

                if image_content:
                    try:
                        files = {'image': (image_name, image_content, image_type)}
                        requests.post(f"http://{target_backend}/upload/image", files=files, timeout=10)
                    except Exception as e:
                        print(f"Sync upload failed: {e}")

        workflow_path = os.path.join(WORKFLOW_DIR, req.workflow_json)
        if not os.path.exists(workflow_path) and req.workflow_json == "Z-Image.json":
            workflow_path = WORKFLOW_PATH
        if not os.path.exists(workflow_path):
            raise Exception(f"Workflow file not found: {req.workflow_json}")

        with open(workflow_path, 'r', encoding='utf-8') as f:
            workflow = json.load(f)

        seed = random.randint(1, 4294967295)

        if not req.preserve_workflow:
            if "23" in workflow and req.prompt:
                workflow["23"]["inputs"]["text"] = req.prompt
            if "144" in workflow:
                workflow["144"]["inputs"]["width"] = req.width
                workflow["144"]["inputs"]["height"] = req.height
            if "22" in workflow:
                workflow["22"]["inputs"]["seed"] = seed
            if "158" in workflow:
                workflow["158"]["inputs"]["noise_seed"] = seed
            for node_id in ["146", "181"]:
                if node_id in workflow and "inputs" in workflow[node_id] and "seed" in workflow[node_id]["inputs"]:
                    workflow[node_id]["inputs"]["seed"] = seed
            if "184" in workflow and "inputs" in workflow["184"] and "seed" in workflow["184"]["inputs"]:
                workflow["184"]["inputs"]["seed"] = seed
            if "172" in workflow and "inputs" in workflow["172"] and "seed" in workflow["172"]["inputs"]:
                workflow["172"]["inputs"]["seed"] = seed
            for node_content in workflow.values():
                if (
                    isinstance(node_content, dict)
                    and node_content.get("class_type") == "SeedVR2"
                    and isinstance(node_content.get("inputs"), dict)
                    and "seed" in node_content["inputs"]
                ):
                    node_content["inputs"]["seed"] = seed
            if "14" in workflow and "inputs" in workflow["14"] and "seed" in workflow["14"]["inputs"]:
                workflow["14"]["inputs"]["seed"] = seed
        if req.local_only and req.workflow_snapshot is not None:
            workflow = json.loads(json.dumps(req.workflow_snapshot))

        app_item = _canvas_comfy_app_for_workflow(req.workflow_json, req.app_id)
        if app_item:
            apply_dlss5_preset(workflow, app_item, req.params)

        for node_id, node_inputs in req.params.items():
            if node_id in workflow:
                if "inputs" not in workflow[node_id]:
                    workflow[node_id]["inputs"] = {}
                for input_name, value in node_inputs.items():
                    workflow[node_id]["inputs"][input_name] = value

        p = {"prompt": workflow, "client_id": req.client_id if req.local_only and req.client_id else CLIENT_ID}
        data = json.dumps(p).encode('utf-8')
        try:
            post_req = urllib.request.Request(f"http://{target_backend}/prompt", data=data)
            prompt_id = json.loads(urllib.request.urlopen(post_req, timeout=10).read())['prompt_id']
        except urllib.error.HTTPError as e:
            error_body = e.read().decode('utf-8')
            raise Exception(f"HTTP Error {e.code}: {error_body}")

        history_data = None
        try:
            workflow_timeout = int(req.timeout_seconds or COMFYUI_HISTORY_TIMEOUT)
        except (TypeError, ValueError):
            workflow_timeout = COMFYUI_HISTORY_TIMEOUT
        workflow_timeout = max(30, min(COMFYUI_HISTORY_TIMEOUT, workflow_timeout))
        for i in range(workflow_timeout):
            try:
                res = get_comfy_history(target_backend, prompt_id)
                if prompt_id in res:
                    history_data = res[prompt_id]
                    break
            except Exception:
                pass
            time.sleep(1)

        if not history_data:
            raise Exception(f"ComfyUI 渲染超时（已等待 {workflow_timeout} 秒）")

        if history_data.get('status', {}).get('status_str') == 'error':
            messages = history_data.get('status', {}).get('messages', [])
            errors = [str(message[1].get('exception_message', message[1])) for message in messages
                      if isinstance(message, list) and len(message) > 1 and message[0] == 'execution_error' and isinstance(message[1], dict)]
            raise RuntimeError('ComfyUI 执行失败：' + ('；'.join(errors) or str(messages)))

        local_images = []
        local_videos = []
        local_audios = []
        local_texts = []
        local_files = []
        local_items = []
        local_urls = []
        current_timestamp = time.time()
        if 'outputs' in history_data:
            # 先把所有节点的输出收集为候选（带上 class_type），再决定下载哪些，
            # 避免把冗余的预览/对比图、调试文本一起下载进结果（后端层过滤，历史记录也更干净）。
            workflow_nodes = workflow if isinstance(workflow, dict) else {}
            def _class_type_of(nid):
                node_def = workflow_nodes.get(str(nid))
                return str(node_def.get("class_type") or "") if isinstance(node_def, dict) else ""
            file_candidates = []   # (node_id, class_type, output_key, item, kind)
            text_candidates = []   # (node_id, class_type, text, name)
            for node_id in history_data['outputs']:
                node_output = history_data['outputs'][node_id]
                class_type = _class_type_of(node_id)
                for output_key, item in collect_comfy_file_items(node_output):
                    file_candidates.append((node_id, class_type, output_key, item, comfy_output_kind(item)))
                for text, name in comfy_text_values_from_output(node_output):
                    text_candidates.append((node_id, class_type, text, name))

            # 只要存在“非预览节点”产出的图片，就把 PreviewImage/对比节点的图片视为冗余丢弃；
            # 若整个工作流只有预览图（没有 SaveImage 等），则保留预览图作为唯一结果，避免零输出。
            has_primary_image = any(
                kind == "image" and not comfy_class_is_preview(ct)
                for (_nid, ct, _ok, _it, kind) in file_candidates
            )
            prefix = f"{req.type}_{int(current_timestamp)}_"
            for node_id, class_type, output_key, item, kind in file_candidates:
                if kind == "image" and has_primary_image and comfy_class_is_preview(class_type):
                    continue  # 跳过冗余的预览/对比图
                local_path = download_comfy_output(target_backend, item, prefix=prefix)
                name = os.path.basename(str(item.get("filename") or "")) or os.path.basename(str(local_path).split("?", 1)[0])
                entry = {
                    "url": local_path,
                    "kind": kind,
                    "name": name,
                    "node_id": str(node_id),
                    "output_key": str(output_key),
                    "class_type": class_type,
                }
                if kind == "image":
                    local_images.append(local_path)
                elif kind == "video":
                    local_videos.append(local_path)
                elif kind == "audio":
                    local_audios.append(local_path)
                elif kind == "text":
                    local_texts.append(local_path)
                else:
                    local_files.append(local_path)
                local_items.append(entry)
                local_urls.append(local_path)

            # 默认抑制 show/utility 类节点的调试文本，避免 .txt 噪声混入结果。
            for node_id, class_type, text, name in text_candidates:
                if comfy_class_is_debug_text(class_type):
                    continue
                local_path = save_comfy_text_output(text, prefix=prefix, name=name)
                entry = {
                    "url": local_path,
                    "kind": "text",
                    "name": os.path.basename(str(local_path).split("?", 1)[0]),
                    "node_id": str(node_id),
                    "output_key": "text",
                    "class_type": class_type,
                }
                local_texts.append(local_path)
                local_items.append(entry)
                local_urls.append(local_path)

        history_params = dict(req.params) if isinstance(req.params, dict) else {}
        project_id = str(req.project_id or "").strip()
        if project_id:
            history_params["project_id"] = project_id
        result = {
            "prompt": req.prompt if req.prompt else "Detail Enhance",
            "images": local_images,
            "videos": local_videos,
            "audios": local_audios,
            "texts": local_texts,
            "files": local_files,
            "items": local_items,
            "outputs": local_urls,
            "seed": seed,
            "timestamp": current_timestamp,
            "type": req.type,
            "history_source": normalize_history_source(req.history_source, "canvas"),
            "project_id": project_id,
            "workflow_json": req.workflow_json,
            "task_id": task_id,
            "prompt_id": prompt_id,
            "backend": target_backend,
            "params": history_params
        }
        if req.record_history:
            save_to_history(result)
            if GLOBAL_LOOP:
                asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
        return result

    except Exception as e:
        return {"images": [], "error": str(e)}
    finally:
        if target_backend:
            with LOAD_LOCK:
                if BACKEND_LOCAL_LOAD.get(target_backend, 0) > 0:
                    BACKEND_LOCAL_LOAD[target_backend] -= 1
        if current_task:
            with QUEUE_LOCK:
                if current_task in QUEUE:
                    QUEUE.remove(current_task)

# --- ComfyUI 工作流管理 ---

BUILTIN_WORKFLOWS = {"Z-Image.json", "Z-Image-Enhance.json", "2511.json", "klein-enhance.json", "Flux2-Klein.json", "upscale.json", "seedvr2-official-upscale.json", "swinir-upscale.json"}
CUSTOM_WORKFLOW_FOLDER = "custom"
LEGACY_CUSTOM_WORKFLOW_FOLDER = "自定义"
WORKFLOW_COMPONENT_RE = re.compile(r'^[^/\\:*?"<>|\x00-\x1f]+$')
WORKFLOW_NAME_RE = re.compile(r'^(?:[^/\\:*?"<>|\x00-\x1f]+/)*[^/\\:*?"<>|\x00-\x1f]+\.json$', re.IGNORECASE)

class WorkflowField(BaseModel):
    id: str
    node: str = ""
    input: str = ""
    name: str = ""
    type: str = "text"
    default: Any = None
    min: Optional[float] = None
    max: Optional[float] = None
    step: Optional[float] = None
    options: List[str] = []
    random_enabled: bool = False
    advanced: bool = False

class WorkflowConfig(BaseModel):
    title: str = ""
    fields: List[WorkflowField] = []
    mini_cards: Dict[str, Any] = {}

class WorkflowUploadRequest(BaseModel):
    name: str
    workflow: Dict[str, Any]
    folder: str = ""

class WorkflowRunRequest(BaseModel):
    fields: Dict[str, Any] = {}
    config: WorkflowConfig
    client_id: str = ""

def workflow_path_from_name(name: str) -> str:
    name = str(name or "").strip().replace("\\", "/")
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    path = os.path.abspath(os.path.join(WORKFLOW_DIR, *name.split("/")))
    workflow_root = os.path.abspath(WORKFLOW_DIR)
    if os.path.commonpath([workflow_root, path]) != workflow_root:
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    return path

def is_valid_workflow_name(name: str) -> bool:
    """Validate a workflow reference while allowing project subdirectories.

    Workflow references are deliberately relative to ComfyUI/workflows.  A
    component may contain Chinese names, spaces and punctuation commonly used
    by local projects, but never path traversal or Windows path separators.
    """
    text = str(name or "").strip().replace("\\", "/")
    if not text or text.startswith("/") or text.endswith("/"):
        return False
    parts = text.split("/")
    if any(not part or part in {".", ".."} or len(part) > 180 for part in parts):
        return False
    if not parts[-1].lower().endswith(".json") or parts[-1].lower().endswith(".config.json"):
        return False
    return bool(WORKFLOW_NAME_RE.fullmatch(text)) and all(
        WORKFLOW_COMPONENT_RE.fullmatch(part) for part in parts
    )

def is_valid_workflow_folder(folder: str) -> bool:
    text = str(folder or "").strip().replace("\\", "/").strip("/")
    if not text:
        return True
    parts = text.split("/")
    return all(
        part not in {"", ".", ".."}
        and len(part) <= 180
        and WORKFLOW_COMPONENT_RE.fullmatch(part)
        for part in parts
    )

def workflow_config_path(name: str) -> str:
    return workflow_path_from_name(name)[:-5] + ".config.json"

def is_builtin_workflow(name: str) -> bool:
    return "/" not in name and os.path.basename(name) in BUILTIN_WORKFLOWS

def runninghub_workflow_store_path() -> str:
    return RUNNINGHUB_WORKFLOW_STORE_FILE

def load_runninghub_workflow_store():
    if not os.path.exists(RUNNINGHUB_WORKFLOW_STORE_FILE):
        return {}
    try:
        with open(RUNNINGHUB_WORKFLOW_STORE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def save_runninghub_workflow_store(store):
    os.makedirs(DATA_DIR, exist_ok=True)
    with open(RUNNINGHUB_WORKFLOW_STORE_FILE, "w", encoding="utf-8") as f:
        json.dump(store, f, ensure_ascii=False, indent=2)

def prune_runninghub_workflow_store_for_provider(provider):
    if not isinstance(provider, dict) or provider.get("id") != "runninghub":
        return
    store = load_runninghub_workflow_store()
    if not store:
        return
    keep_ids = {
        runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
        for entry in provider.get("rh_workflows") or []
        if isinstance(entry, dict) and entry.get("hidden") is not True
    }
    keep_ids.discard("")
    removed = False
    for workflow_id in list(store.keys()):
        if runninghub_workflow_store_key(workflow_id) not in keep_ids:
            store.pop(workflow_id, None)
            removed = True
    if removed:
        save_runninghub_workflow_store(store)

def runninghub_workflow_config_has_payload(cfg):
    if not isinstance(cfg, dict):
        return False
    return bool(cfg.get("fields") or cfg.get("workflowJson") or cfg.get("raw"))

def runninghub_static_workflow_entry(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return None
    static_provider = load_static_runninghub_provider()
    for entry in (static_provider or {}).get("rh_workflows", []) or []:
        if runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id")) == key:
            return entry
    return None

def runninghub_static_workflow_config(workflow_id: str):
    entry = runninghub_static_workflow_entry(workflow_id)
    if not isinstance(entry, dict):
        return None
    key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
    cfg = {
        "workflowId": key,
        "title": entry.get("title") or key,
        "description": entry.get("note") or entry.get("description") or "",
        "fields": [
            field for field in (runninghub_normalize_field(item) for item in (entry.get("fields") or []))
            if not runninghub_is_saved_link_field(field)
        ],
        "workflowJson": entry.get("workflowJson") if isinstance(entry.get("workflowJson"), dict) else {},
        "optionalImageMode": entry.get("optionalImageMode") or "prune-workflow",
        "raw": entry.get("raw") if isinstance(entry.get("raw"), dict) else {},
        "updatedAt": entry.get("updatedAt") or 0,
        "source": "static_template",
    }
    return cfg if runninghub_workflow_config_has_payload(cfg) else None

def runninghub_workflow_entry_from_config(cfg, fallback=None):
    fallback = fallback if isinstance(fallback, dict) else {}
    key = runninghub_workflow_store_key((cfg or {}).get("workflowId") or fallback.get("workflowId") or fallback.get("id"))
    if not key:
        return None
    return normalize_runninghub_entry({
        "id": key,
        "workflowId": key,
        "title": (cfg or {}).get("title") or fallback.get("title") or fallback.get("name") or f"工作流 {key[-6:]}",
        "note": (cfg or {}).get("description") or fallback.get("note") or fallback.get("description") or "",
        "thumbnail": fallback.get("thumbnail") or "",
        "enabled": fallback.get("enabled", True),
        "fields": (cfg or {}).get("fields") or fallback.get("fields") or [],
        "workflowJson": (cfg or {}).get("workflowJson") if isinstance((cfg or {}).get("workflowJson"), dict) else fallback.get("workflowJson") or {},
        "optionalImageMode": (cfg or {}).get("optionalImageMode") or fallback.get("optionalImageMode") or "prune-workflow",
        "raw": (cfg or {}).get("raw") if isinstance((cfg or {}).get("raw"), dict) else fallback.get("raw") or {},
        "updatedAt": (cfg or {}).get("updatedAt") or fallback.get("updatedAt") or 0,
    }, "workflow")

def runninghub_saved_hidden_workflow_ids():
    if not os.path.exists(API_PROVIDERS_FILE):
        return set()
    try:
        with open(API_PROVIDERS_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        return set()
    hidden = set()
    for provider in raw if isinstance(raw, list) else []:
        if not isinstance(provider, dict) or str(provider.get("id") or "").strip().lower() != "runninghub":
            continue
        for entry in provider.get("rh_workflows") or []:
            if not isinstance(entry, dict) or entry.get("hidden") is not True:
                continue
            key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
            if key:
                hidden.add(key)
    return hidden

def runninghub_provider_with_workflow_store(provider):
    if not isinstance(provider, dict) or provider.get("id") != "runninghub":
        return provider
    store = load_runninghub_workflow_store()
    if not store:
        return provider
    merged = dict(provider)
    workflows = [dict(item) for item in (merged.get("rh_workflows") or []) if isinstance(item, dict)]
    hidden_ids = {
        runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
        for item in workflows
        if item.get("hidden") is True and runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
    }
    hidden_ids.update(runninghub_saved_hidden_workflow_ids())
    by_id = {
        runninghub_workflow_store_key(item.get("workflowId") or item.get("id")): item
        for item in workflows
        if runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
    }
    for workflow_id, cfg in store.items():
        if workflow_id in hidden_ids:
            continue
        if not isinstance(cfg, dict) or not runninghub_workflow_config_has_payload(cfg):
            continue
        existing = by_id.get(workflow_id)
        selected = runninghub_select_workflow_config(existing, cfg, workflow_id)
        entry = runninghub_workflow_entry_from_config(selected, existing)
        if not entry:
            continue
        if existing is None:
            workflows.append(entry)
        else:
            existing.update(entry)
    merged["rh_workflows"] = normalize_runninghub_entries(workflows, "workflow")
    return merged

def runninghub_provider_workflow_config(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return None
    if key in runninghub_saved_hidden_workflow_ids():
        return None
    providers = load_api_providers()
    provider = next((item for item in providers if item.get("id") == "runninghub"), None)
    if not provider:
        return None
    for entry in provider.get("rh_workflows") or []:
        entry_key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
        if entry_key != key:
            continue
        if entry.get("hidden") is True:
            return None
        cfg = {
            "workflowId": key,
            "title": entry.get("title") or key,
            "description": entry.get("note") or entry.get("description") or "",
            "fields": [
                field for field in (runninghub_normalize_field(item) for item in (entry.get("fields") or []))
                if not runninghub_is_saved_link_field(field)
            ],
            "workflowJson": entry.get("workflowJson") if isinstance(entry.get("workflowJson"), dict) else {},
            "optionalImageMode": entry.get("optionalImageMode") or "prune-workflow",
            "raw": entry.get("raw") if isinstance(entry.get("raw"), dict) else {},
            "updatedAt": entry.get("updatedAt") or 0,
            "source": "api_providers",
        }
        return cfg if runninghub_workflow_config_has_payload(cfg) else None
    return None

def runninghub_select_workflow_config(local_cfg, provider_cfg, workflow_id: str = ""):
    static_cfg = runninghub_static_workflow_config(workflow_id)
    if isinstance(local_cfg, dict) and isinstance(provider_cfg, dict):
        try:
            local_updated = int(local_cfg.get("updatedAt") or 0)
        except Exception:
            local_updated = 0
        try:
            provider_updated = int(provider_cfg.get("updatedAt") or 0)
        except Exception:
            provider_updated = 0
        return provider_cfg if provider_updated > local_updated else local_cfg
    if isinstance(local_cfg, dict):
        return local_cfg
    if isinstance(provider_cfg, dict):
        return provider_cfg
    if static_cfg:
        return static_cfg
    return None

def sync_runninghub_workflow_to_provider(cfg):
    if not isinstance(cfg, dict):
        return
    key = runninghub_workflow_store_key(cfg.get("workflowId"))
    if not key:
        return
    providers = load_api_providers()
    provider = next((item for item in providers if item.get("id") == "runninghub"), None)
    if not provider:
        provider = {
            "id": "runninghub",
            "name": "RunningHub",
            "base_url": RUNNINGHUB_DEFAULT_BASE_URL,
            "protocol": "runninghub",
            "image_generation_endpoint": "",
            "image_edit_endpoint": "",
            "enabled": True,
            "primary": False,
            "image_models": [],
            "chat_models": [],
            "video_models": [],
            "ms_loras": [],
            "ms_defaults_version": 0,
            "rh_apps": RUNNINGHUB_DEFAULT_APPS,
            "rh_workflows": [],
        }
        providers.append(provider)
    workflows = provider.setdefault("rh_workflows", [])
    entry = None
    for item in workflows:
        item_key = runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
        if item_key == key:
            entry = item
            break
    if entry is None:
        entry = {
            "id": key,
            "workflowId": key,
            "title": cfg.get("title") or f"工作流 {key[-6:]}",
            "note": cfg.get("description") or "",
            "thumbnail": "",
            "enabled": True,
        }
        workflows.append(entry)
    entry.update({
        "id": key,
        "workflowId": key,
        "title": cfg.get("title") or entry.get("title") or f"工作流 {key[-6:]}",
        "note": cfg.get("description") or "",
        "fields": [
            field for field in (runninghub_normalize_field(item) for item in (cfg.get("fields") or []))
            if not runninghub_is_saved_link_field(field)
        ],
        "workflowJson": cfg.get("workflowJson") if isinstance(cfg.get("workflowJson"), dict) else {},
        "optionalImageMode": cfg.get("optionalImageMode") or "prune-workflow",
        "raw": cfg.get("raw") if isinstance(cfg.get("raw"), dict) else {},
        "updatedAt": cfg.get("updatedAt") or now_ms(),
    })
    if "enabled" not in entry:
        entry["enabled"] = True
    if "thumbnail" not in entry:
        entry["thumbnail"] = ""
    save_api_providers([normalize_provider(item) for item in providers])

def remove_runninghub_workflow_from_provider(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return
    providers = load_api_providers()
    changed = False
    for provider in providers:
        if provider.get("id") != "runninghub":
            continue
        workflows = provider.get("rh_workflows") or []
        removed = next((
            item for item in workflows
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) == key
        ), None)
        kept = [
            item for item in workflows
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) != key
        ]
        static_provider = load_static_runninghub_provider()
        static_workflow = next((
            item for item in (static_provider or {}).get("rh_workflows", [])
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) == key
        ), None)
        if static_workflow:
            tombstone = normalize_runninghub_entry({**static_workflow, **(removed or {}), "enabled": False, "hidden": True}, "workflow")
            if tombstone:
                kept.append(tombstone)
        if static_workflow or len(kept) != len(workflows):
            provider["rh_workflows"] = kept
            changed = True
    if changed:
        save_api_providers([normalize_provider(item) for item in providers])

def runninghub_workflow_store_key(workflow_id: str) -> str:
    return normalize_runninghub_reference_id(workflow_id, "workflow")

def runninghub_normalize_field(raw, fallback=None):
    fallback = fallback or {}
    if hasattr(raw, "dict"):
        raw = raw.dict()
    if not isinstance(raw, dict):
        raw = {}
    options = raw.get("options", fallback.get("options", []))
    if isinstance(options, str):
        options = [item.strip() for item in re.split(r"[\r\n,]+", options) if item.strip()]
    elif isinstance(options, list):
        options = [str(item).strip() for item in options if str(item).strip()]
    else:
        options = []
    field_id = str(raw.get("id") or raw.get("fieldId") or raw.get("key") or raw.get("nodeId") or fallback.get("id") or "").strip()
    node_id = str(raw.get("nodeId") or fallback.get("nodeId") or raw.get("node_id") or "").strip()
    field_name = str(raw.get("fieldName") or raw.get("inputName") or raw.get("name") or fallback.get("fieldName") or "").strip()
    field_value = raw.get("fieldValue")
    if field_value is None:
        field_value = raw.get("defaultValue")
    if field_value is None:
        field_value = raw.get("value")
    if field_value is None:
        field_value = fallback.get("fieldValue", "")
    if isinstance(field_value, (dict, list)):
        field_value = json.dumps(field_value, ensure_ascii=False)
    elif field_value is None:
        field_value = ""
    else:
        field_value = str(field_value)
    return {
        "id": field_id or f"{node_id}::{field_name}",
        "nodeId": node_id,
        "fieldName": field_name,
        "fieldValue": field_value,
        "fieldType": str(raw.get("fieldType") or fallback.get("fieldType") or "TEXT"),
        "label": str(raw.get("label") or raw.get("title") or field_name or fallback.get("label") or ""),
        "enabled": bool(raw.get("enabled", fallback.get("enabled", True))),
        "sourceFromUpstream": bool(raw.get("sourceFromUpstream", fallback.get("sourceFromUpstream", True))),
        "group": str(raw.get("group") or fallback.get("group") or ""),
        "note": str(raw.get("note") or fallback.get("note") or ""),
        "options": options,
        "random_enabled": bool(raw.get("random_enabled", fallback.get("random_enabled", False))),
        "min": raw.get("min", fallback.get("min", "")),
        "max": raw.get("max", fallback.get("max", "")),
        "step": raw.get("step", fallback.get("step", "")),
        "imageOrder": int(raw.get("imageOrder") or raw.get("image_order") or fallback.get("imageOrder") or 0),
        "required": bool(raw.get("required", fallback.get("required", False))),
    }

def runninghub_is_saved_link_field(field):
    if not isinstance(field, dict):
        return False
    value = field.get("fieldValue")
    if not isinstance(value, str):
        return False
    text = value.strip()
    if not (text.startswith("[") and text.endswith("]")):
        return False
    try:
        parsed = json.loads(text)
    except Exception:
        return False
    return runninghub_is_workflow_link_value(parsed)

def runninghub_collect_workflow_fields(workflow_json):
    fields = []
    if not isinstance(workflow_json, dict):
        return fields
    for node_id, node_content in workflow_json.items():
        if not isinstance(node_content, dict):
            continue
        inputs = node_content.get("inputs")
        if not isinstance(inputs, dict):
            continue
        for field_name, raw_value in inputs.items():
            if runninghub_is_workflow_link_value(raw_value):
                continue
            if isinstance(raw_value, (dict, list)):
                field_value = json.dumps(raw_value, ensure_ascii=False)
            elif raw_value is None:
                field_value = ""
            else:
                field_value = str(raw_value)
            field_type = runninghub_infer_workflow_field_type(field_name, field_value)
            fields.append({
                "id": f"{node_id}::{field_name}",
                "nodeId": str(node_id),
                "fieldName": str(field_name),
                "fieldValue": field_value,
                "fieldType": field_type,
                "label": str(field_name),
                "enabled": False,
                "sourceFromUpstream": True,
                "group": str(
                    (node_content.get("_meta") or {}).get("title")
                    or node_content.get("class_type")
                    or node_content.get("_class")
                    or node_content.get("type")
                    or ""
                ),
                "note": "",
                "imageOrder": 0,
                "required": field_type == "IMAGE",
            })
    return fields

class ComfyInstancesPayload(BaseModel):
    instances: List[str] = []

@app.get("/api/comfyui/instances")
def get_comfyui_instances():
    return {"instances": COMFYUI_INSTANCES}

@app.put("/api/comfyui/instances")
def save_comfyui_instances(payload: ComfyInstancesPayload):
    # 宽容校验：去前后空白、去 http(s):// 前缀、去尾部斜杠；要求形如 host:port
    cleaned = []
    for item in payload.instances:
        s = str(item or "").strip()
        if not s:
            continue
        s = re.sub(r"^https?://", "", s)
        s = s.rstrip("/")
        if ":" not in s:
            raise HTTPException(status_code=400, detail=f"地址缺少端口号：{item}（应为 host:port，例如 127.0.0.1:8188）")
        host, _, port = s.rpartition(":")
        if not host or not port.isdigit():
            raise HTTPException(status_code=400, detail=f"地址不合法：{item}（应为 host:port，例如 127.0.0.1:8188）")
        if s in cleaned:
            continue
        cleaned.append(s)
    if not cleaned:
        raise HTTPException(status_code=400, detail="至少保留一个 ComfyUI 后端地址")
    # 写入 env 文件
    try:
        update_env_values({"COMFYUI_INSTANCES": ",".join(cleaned)})
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"写入 env 失败：{e}")
    # 更新进程中的全局变量
    global COMFYUI_INSTANCES, COMFYUI_ADDRESS, BACKEND_LOCAL_LOAD
    COMFYUI_INSTANCES = cleaned
    COMFYUI_ADDRESS = cleaned[0]
    new_load = {addr: 0 for addr in cleaned}
    for addr, n in (BACKEND_LOCAL_LOAD or {}).items():
        if addr in new_load:
            new_load[addr] = n
    BACKEND_LOCAL_LOAD = new_load
    return {"instances": COMFYUI_INSTANCES}

@app.get("/api/workflows")
def list_workflows():
    if not os.path.isdir(WORKFLOW_DIR):
        return {"workflows": []}
    items = []
    for root, dirs, files in os.walk(WORKFLOW_DIR):
        # 工作流目录可以按项目自由分层。只跳过隐藏/缓存目录，不能再把
        # 根目录限制为 custom/自定义，否则其它项目的工作流永远不会出现在
        # 设置页和画布节点的切换列表里。
        dirs[:] = [
            d for d in dirs
            if d not in {".", "..", "__pycache__"} and not d.startswith(".")
        ]
        for fn in sorted(files):
            if not fn.endswith(".json") or fn.endswith(".config.json"):
                continue
            rel = os.path.relpath(os.path.join(root, fn), WORKFLOW_DIR).replace("\\", "/")
            if not is_valid_workflow_name(rel):
                continue
            if is_builtin_workflow(rel):
                continue
            cfg = {}
            cfg_path = workflow_config_path(rel)
            if os.path.exists(cfg_path):
                try:
                    with open(cfg_path, "r", encoding="utf-8") as f:
                        cfg = json.load(f) or {}
                except Exception:
                    cfg = {}
            folder = os.path.dirname(rel).replace("\\", "/")
            items.append({
                "name": rel,
                "title": cfg.get("title") or fn.replace(".json", ""),
                "builtin": False,
                "field_count": len(cfg.get("fields") or []),
                "folder": folder,
                "project": folder or "根目录",
            })
    items.sort(key=lambda item: (
        0 if item.get("folder") in {CUSTOM_WORKFLOW_FOLDER, LEGACY_CUSTOM_WORKFLOW_FOLDER} else 1,
        str(item.get("folder") or "").casefold(),
        str(item.get("title") or item.get("name") or "").casefold(),
    ))
    return {"workflows": items}

@app.get("/api/workflows/{name:path}")
def get_workflow(name: str):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    with open(workflow_path, "r", encoding="utf-8") as f:
        workflow = json.load(f)
    cfg = {"title": name.replace(".json", ""), "fields": []}
    cfg_path = workflow_config_path(name)
    if os.path.exists(cfg_path):
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                cfg = json.load(f) or cfg
        except Exception:
            pass
    app_item = _canvas_comfy_app_for_workflow(name)
    preset = dlss5_preset_field(app_item) if app_item else None
    if preset:
        app_library = globals().get("COMFY_APPS")
        info = app_library._catalog_info() if app_library else {}
        preset = dlss5_preset_field(app_item, info) or preset
    if preset:
        fields = cfg.setdefault("fields", [])
        existing = next((field for field in fields if field.get("id") == preset["id"]), None)
        if existing:
            existing.update({key: value for key, value in preset.items() if key != "name"})
        else:
            fields.append(preset)
    return {"name": name, "workflow": workflow, "config": cfg, "builtin": is_builtin_workflow(name)}

@app.post("/api/workflows")
def upload_workflow(payload: WorkflowUploadRequest):
    name = os.path.basename(payload.name.strip())
    if not name.endswith(".json"):
        name = name + ".json"
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="工作流名称不合法，请使用中文/英文/数字/_-.")
    folder = str(payload.folder or "").strip().replace("\\", "/").strip("/")
    if not is_valid_workflow_folder(folder):
        raise HTTPException(status_code=400, detail="工作流项目目录不合法")
    if not isinstance(payload.workflow, dict) or not payload.workflow:
        raise HTTPException(status_code=400, detail="工作流 JSON 为空")
    # 简单校验：是 API 格式（节点 id 为 key，含 class_type）
    sample = next(iter(payload.workflow.values()), None)
    if not isinstance(sample, dict) or "class_type" not in sample:
        raise HTTPException(status_code=400, detail="不是有效的 ComfyUI API 工作流 JSON（需包含 class_type）")
    folder = folder or CUSTOM_WORKFLOW_FOLDER
    target_dir = os.path.join(WORKFLOW_DIR, *folder.split("/"))
    os.makedirs(target_dir, exist_ok=True)
    stored_name = f"{folder}/{name}" if folder else name
    path = workflow_path_from_name(stored_name)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload.workflow, f, ensure_ascii=False, indent=2)
    return {"name": stored_name}

@app.put("/api/workflows/{name:path}/config")
def save_workflow_config(name: str, payload: WorkflowConfig):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    cfg_path = workflow_config_path(name)
    with open(cfg_path, "w", encoding="utf-8") as f:
        json.dump(payload.dict(), f, ensure_ascii=False, indent=2)
    return {"config": payload.dict()}

@app.delete("/api/workflows/{name:path}")
def delete_workflow(name: str):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    if is_builtin_workflow(name):
        raise HTTPException(status_code=400, detail="内置工作流不可删除")
    workflow_path = workflow_path_from_name(name)
    cfg_path = workflow_config_path(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    os.remove(workflow_path)
    if os.path.exists(cfg_path):
        os.remove(cfg_path)
    removed_apps = []
    app_library = globals().get('COMFY_APPS')
    if app_library and hasattr(app_library, 'sync_deleted_workflow'):
        removed_apps = app_library.sync_deleted_workflow(name)
    return {"ok": True, "removed_apps": removed_apps}

@app.post("/api/workflows/{name:path}/run")
def run_workflow(name: str, payload: WorkflowRunRequest):
    if not is_valid_workflow_name(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    if not os.path.exists(workflow_path_from_name(name)):
        raise HTTPException(status_code=404, detail="Workflow not found")
    # 根据 config 的字段把值映射成 params 节点覆盖
    params: Dict[str, Dict[str, Any]] = {}
    for field in payload.config.fields:
        if not field.node or not field.input:
            continue
        if field.id in payload.fields:
            value = payload.fields[field.id]
            # 类型转换
            if field.type in ("number", "slider"):
                try:
                    value = float(value) if (field.step and field.step < 1) else int(float(value))
                except Exception:
                    pass
            elif field.type == "boolean":
                value = bool(value)
            elif field.type == "dropdown":
                # 下拉值如果看起来是数字（如 "1024" / "2048" / "0.8"），自动转成 int/float
                if isinstance(value, str):
                    s = value.strip()
                    try:
                        if s and ('.' in s or 'e' in s.lower()):
                            value = float(s)
                        elif s and (s.lstrip('-').isdigit()):
                            value = int(s)
                    except (ValueError, TypeError):
                        pass
            params.setdefault(field.node, {})[field.input] = value
    req = GenerateRequest(
        prompt="",
        workflow_json=name,
        params=params,
        type="workflow-test",
        client_id=payload.client_id or str(uuid.uuid4()),
    )
    return generate(req)

